insert into public.tarot_cards
  (id, arcana, suit, number, name_en, name_ko, image_path, keywords_up, keywords_rev, meaning_up, meaning_rev)
values
  (0, 'major', null, 0, 'The Fool', '바보', '/tarot/00.webp', array['새로운 시작', '설렘', '용기'], array['망설임', '충동', '준비 부족'], '바보 카드는 아무것도 정해지지 않은 출발선에 선 순수한 마음을 뜻해요. 계산하지 않고 한 걸음 내딛는 용기가 새로운 흐름을 열어줘요.', '역방향 바보는 마음이 앞서 발을 헛디디거나, 반대로 겁이 나서 출발을 미루는 모습이에요. 설렘은 그대로 두고 발밑을 한 번만 살피면 괜찮아요.'),
  (1, 'major', null, 1, 'The Magician', '마법사', '/tarot/01.webp', array['표현력', '매력', '실행'], array['어긋난 말', '자신감 부족', '꾸밈'], '마법사 카드는 필요한 재료를 모두 손에 쥐고 원하는 것을 현실로 만드는 힘이에요. 말과 행동으로 마음을 표현할수록 일이 술술 풀리기 쉬워요.', '역방향 마법사는 가진 힘을 제대로 쓰지 못하거나, 진심보다 보여주기에 신경 쓰는 모습이에요. 꾸밈을 덜어내고 솔직해지면 다시 매력이 살아나요.'),
  (2, 'major', null, 2, 'The High Priestess', '여사제', '/tarot/02.webp', array['직감', '조용한 마음', '기다림'], array['숨긴 감정', '오해', '불안'], '여사제 카드는 겉으로 드러나지 않는 깊은 마음과 직감을 뜻해요. 서두르기보다 조용히 지켜보며 느낌을 믿을 때 답이 보이기 쉬워요.', '역방향 여사제는 마음을 너무 깊이 숨기거나, 불안한 상상이 직감을 가리는 모습이에요. 혼자 짐작하기보다 확인해 보면 마음이 가벼워져요.'),
  (3, 'major', null, 3, 'The Empress', '여황제', '/tarot/03.webp', array['다정함', '풍요', '사랑받음'], array['지나친 헌신', '서운함', '자기 소홀'], '여황제 카드는 사랑을 주고받는 따뜻하고 풍요로운 에너지예요. 나를 아끼는 마음이 자연스럽게 매력으로 드러나는 때예요.', '역방향 여황제는 상대를 챙기느라 나를 돌보지 못하거나, 준 만큼 받지 못해 서운한 모습이에요. 나에게도 같은 다정함을 건네 주세요.'),
  (4, 'major', null, 4, 'The Emperor', '황제', '/tarot/04.webp', array['안정', '책임감', '확신'], array['고집', '통제', '경직'], '황제 카드는 단단한 기반과 책임감 있는 태도를 뜻해요. 관계에서도 믿음직하게 중심을 잡아줄 때 안정감이 생겨요.', '역방향 황제는 내 방식을 고집하거나 관계를 통제하려는 마음이에요. 힘을 조금 빼고 상대의 생각에 귀 기울이면 균형이 잡혀요.'),
  (5, 'major', null, 5, 'The Hierophant', '교황', '/tarot/05.webp', array['신뢰', '진지함', '약속'], array['틀에서 벗어남', '가치관 차이', '의심'], '교황 카드는 믿음과 약속, 서로가 존중하는 가치를 뜻해요. 진지하고 성실한 관계를 쌓기 좋은 기운이에요.', '역방향 교황은 정해진 틀이 답답하게 느껴지거나 서로의 가치관이 엇갈리는 모습이에요. 다름을 인정하는 대화가 필요해요.'),
  (6, 'major', null, 6, 'The Lovers', '연인', '/tarot/06.webp', array['끌림', '선택', '마음의 조화'], array['엇갈림', '갈등', '망설이는 선택'], '연인 카드는 두 마음이 서로를 향해 끌리고, 진심으로 선택하는 순간을 뜻해요. 마음이 통하는 관계가 피어나기 좋은 기운이에요.', '역방향 연인은 마음이 엇갈리거나 선택 앞에서 갈팡질팡하는 모습이에요. 내가 정말 원하는 게 무엇인지 먼저 들여다보면 좋아요.'),
  (7, 'major', null, 7, 'The Chariot', '전차', '/tarot/07.webp', array['전진', '의지', '적극성'], array['조급함', '방향 잃음', '충돌'], '전차 카드는 강한 의지로 앞으로 나아가는 힘이에요. 원하는 것이 분명할 때 관계를 이끌어 갈 수 있어요.', '역방향 전차는 마음이 급해 방향을 잃거나, 서로 다른 쪽으로 힘을 쓰는 모습이에요. 속도를 줄이고 방향부터 맞추면 좋아요.'),
  (8, 'major', null, 8, 'Strength', '힘', '/tarot/08.webp', array['다정한 용기', '인내', '부드러운 힘'], array['자신감 저하', '감정 기복', '조급함'], '힘 카드는 거친 마음도 부드럽게 다독이는 따뜻한 용기예요. 다정함과 인내가 관계를 단단하게 만들어줘요.', '역방향 힘은 자신감이 떨어지거나 감정을 다스리기 어려운 모습이에요. 나를 다그치기보다 다정하게 다독여 주세요.'),
  (9, 'major', null, 9, 'The Hermit', '은둔자', '/tarot/09.webp', array['혼자만의 시간', '성찰', '신중함'], array['고립', '외로움', '닫힌 마음'], '은둔자 카드는 혼자만의 시간 속에서 내 마음을 깊이 들여다보는 지혜예요. 서두르지 않고 나를 이해할 때 길이 보여요.', '역방향 은둔자는 마음을 너무 닫아 외로움이 커지거나, 혼자 생각에만 빠져 있는 모습이에요. 조금씩 바깥과 연결되면 좋아요.'),
  (10, 'major', null, 10, 'Wheel of Fortune', '운명의 수레바퀴', '/tarot/10.webp', array['전환점', '흐름', '우연한 기회'], array['엇갈린 타이밍', '반복', '기다림'], '운명의 수레바퀴는 흐름이 바뀌고 새로운 기회가 찾아오는 전환점이에요. 우연처럼 보이는 만남이 의미 있게 다가올 수 있어요.', '역방향 수레바퀴는 타이밍이 잠시 엇갈리거나 같은 패턴이 반복되는 모습이에요. 흐름이 바뀔 때까지 나를 다듬으며 기다려 보세요.'),
  (11, 'major', null, 11, 'Justice', '정의', '/tarot/11.webp', array['균형', '공정함', '솔직함'], array['불균형', '서운함', '치우침'], '정의 카드는 주고받는 마음의 균형과 솔직한 판단을 뜻해요. 서로에게 공정할 때 관계가 건강해져요.', '역방향 정의는 한쪽으로 기운 관계나 쌓인 서운함을 보여줘요. 감정보다 사실을 차분히 나누면 균형을 되찾을 수 있어요.'),
  (12, 'major', null, 12, 'The Hanged Man', '매달린 사람', '/tarot/12.webp', array['다른 시선', '기다림', '내려놓음'], array['헛된 희생', '정체', '답답함'], '매달린 사람 카드는 잠시 멈춰 다른 각도에서 바라볼 때 새로운 답이 보인다는 뜻이에요. 기다림이 의미 있는 시간이 될 수 있어요.', '역방향 매달린 사람은 보답 없는 희생을 이어가거나 답답하게 제자리에 머무는 모습이에요. 놓아야 할 것을 놓을 용기가 필요해요.'),
  (13, 'major', null, 13, 'Death', '죽음', '/tarot/13.webp', array['끝과 시작', '변화', '정리'], array['미련', '변화 거부', '정체'], '죽음 카드는 무서운 뜻이 아니라 하나의 단계가 끝나고 새로운 단계가 시작되는 변화를 뜻해요. 낡은 것을 정리할 때 새로운 것이 들어와요.', '역방향 죽음은 끝내야 할 것을 놓지 못하고 붙잡고 있는 모습이에요. 변화를 받아들이면 마음이 훨씬 가벼워질 수 있어요.'),
  (14, 'major', null, 14, 'Temperance', '절제', '/tarot/14.webp', array['조화', '균형', '천천히'], array['불균형', '조급함', '어긋남'], '절제 카드는 서로 다른 것을 알맞게 섞어 조화를 이루는 지혜예요. 서두르지 않고 균형을 맞출 때 관계가 편안해져요.', '역방향 절제는 감정이 한쪽으로 치우치거나 속도가 맞지 않아 어긋나는 모습이에요. 조금씩 맞춰 가는 연습이 필요해요.'),
  (15, 'major', null, 15, 'The Devil', '악마', '/tarot/15.webp', array['강한 끌림', '집착', '유혹'], array['벗어남', '해방', '건강한 거리'], '악마 카드는 강하게 끌리는 마음과 함께, 그 끌림에 묶여 버리는 집착을 뜻해요. 설렘과 집착을 구분하는 게 중요해요.', '역방향 악마는 나를 묶던 감정이나 관계에서 벗어나 자유로워지는 모습이에요. 건강한 거리를 찾으면 마음이 가벼워져요.'),
  (16, 'major', null, 16, 'The Tower', '탑', '/tarot/16.webp', array['갑작스러운 변화', '깨달음', '새로 세우기'], array['변화를 피함', '불안', '조용한 정리'], '탑 카드는 예상하지 못한 변화로 익숙한 것이 흔들리는 순간이에요. 당황스러울 수 있지만, 진짜 모습을 깨닫고 다시 단단히 세울 기회가 돼요.', '역방향 탑은 필요한 변화를 피하거나, 큰 흔들림이 조용히 지나가는 모습이에요. 미뤄 둔 정리를 천천히 해 나가면 좋아요.'),
  (17, 'major', null, 17, 'The Star', '별', '/tarot/17.webp', array['희망', '회복', '순수한 마음'], array['낙담', '자신감 부족', '희망을 잃음'], '별 카드는 어둠 뒤에 반짝이는 희망과 마음의 회복을 뜻해요. 순수한 마음으로 바라는 것이 조금씩 가까워져요.', '역방향 별은 희망이 잠시 흐려지고 스스로를 믿지 못하는 모습이에요. 작은 기대부터 다시 품으면 빛이 돌아와요.'),
  (18, 'major', null, 18, 'The Moon', '달', '/tarot/18.webp', array['불확실함', '상상', '감성'], array['오해가 풀림', '선명해짐', '불안 해소'], '달 카드는 모든 게 또렷하지 않아 상상과 불안이 커지는 밤 같은 시간이에요. 보이는 것만 믿기보다 천천히 확인하는 게 필요해요.', '역방향 달은 안개가 걷히며 오해가 풀리고 진실이 선명해지는 모습이에요. 불안했던 마음이 조금씩 편안해질 수 있어요.'),
  (19, 'major', null, 19, 'The Sun', '태양', '/tarot/19.webp', array['행복', '밝은 마음', '솔직함'], array['잠시 흐림', '들뜸', '기대 조절'], '태양 카드는 밝고 따뜻한 기운으로 마음이 활짝 피어나는 순간이에요. 솔직하고 즐거운 에너지가 좋은 인연을 끌어당겨요.', '역방향 태양은 구름에 잠시 가려진 해처럼 기쁨이 조금 줄어든 모습이에요. 기대를 조절하면 작은 행복이 다시 보여요.'),
  (20, 'major', null, 20, 'Judgement', '심판', '/tarot/20.webp', array['깨달음', '다시 보기', '새로운 부름'], array['망설임', '자책', '결정 미룸'], '심판 카드는 지난 일을 돌아보며 깨닫고, 새로운 부름에 응답하는 순간이에요. 마음속 진짜 목소리를 듣게 될 수 있어요.', '역방향 심판은 과거에 머물러 자책하거나 결정을 미루는 모습이에요. 나를 용서할 때 앞으로 나아갈 수 있어요.'),
  (21, 'major', null, 21, 'The World', '세계', '/tarot/21.webp', array['완성', '충만함', '새로운 여정'], array['마무리 직전', '아쉬움', '미완성'], '세계 카드는 하나의 여정이 아름답게 완성되고 마음이 충만해지는 순간이에요. 원하던 관계가 이뤄지거나 한 단계가 잘 마무리될 수 있어요.', '역방향 세계는 거의 다 왔지만 마지막 한 조각이 남은 모습이에요. 조급해하지 않고 마무리를 챙기면 완성에 가까워져요.'),
  (22, 'minor', 'wands', 1, 'Ace of Wands', '완드 에이스', '/tarot/22.webp', array['설렘의 시작', '열정', '새 인연'], array['식은 열정', '망설임', '늦어지는 시작'], '완드 에이스는 마음에 불꽃이 탁 튀는 새로운 시작이에요. 설렘과 열정이 솟아나 무언가를 시작하고 싶어지는 기운이에요.', '역방향 완드 에이스는 불씨는 있지만 쉽게 타오르지 않는 모습이에요. 시작이 늦어져도 불씨를 꺼뜨리지 않고 돌보면 괜찮아요.'),
  (23, 'minor', 'wands', 2, 'Two of Wands', '완드 2', '/tarot/23.webp', array['계획', '다음 단계', '결심'], array['망설임', '익숙함에 머묾', '두려움'], '완드 2는 손에 세상을 쥐고 다음 걸음을 계획하는 모습이에요. 지금 자리에서 더 넓은 가능성을 바라보며 결심하는 기운이에요.', '역방향 완드 2는 새로운 걸음을 내딛기 두려워 익숙한 자리에 머무는 모습이에요. 작은 계획부터 세우면 두려움이 줄어요.'),
  (24, 'minor', 'wands', 3, 'Three of Wands', '완드 3', '/tarot/24.webp', array['기다림의 결실', '확장', '멀리 보기'], array['지연', '기대 어긋남', '답답함'], '완드 3은 언덕 위에서 배가 돌아오기를 기다리며 멀리 내다보는 모습이에요. 뿌린 노력이 결실로 돌아오기 시작하는 기운이에요.', '역방향 완드 3은 기다리던 소식이 늦어지거나 기대와 다르게 흘러가는 모습이에요. 계획을 조금 고치면 다시 길이 열려요.'),
  (25, 'minor', 'wands', 4, 'Four of Wands', '완드 4', '/tarot/25.webp', array['축하', '안정된 기쁨', '편안함'], array['어수선함', '불안정', '작은 갈등'], '완드 4는 꽃으로 장식한 문 아래에서 기쁨을 나누는 축제의 모습이에요. 관계가 안정되고 함께 축하할 일이 생기는 기운이에요.', '역방향 완드 4는 축하할 일이 미뤄지거나 분위기가 어수선한 모습이에요. 작은 갈등을 풀면 다시 편안함을 찾을 수 있어요.'),
  (26, 'minor', 'wands', 5, 'Five of Wands', '완드 5', '/tarot/26.webp', array['경쟁', '의견 차이', '활기찬 다툼'], array['갈등 해소', '회피', '속으로 삭임'], '완드 5는 여러 사람이 막대기를 부딪치며 경쟁하는 모습이에요. 의견이 엇갈리거나 경쟁자가 생길 수 있지만, 활기찬 에너지이기도 해요.', '역방향 완드 5는 다툼이 가라앉거나, 반대로 갈등을 피하며 속으로 삭이는 모습이에요. 솔직한 대화로 풀면 편안해져요.'),
  (27, 'minor', 'wands', 6, 'Six of Wands', '완드 6', '/tarot/27.webp', array['인정받음', '자신감', '좋은 소식'], array['자신감 하락', '인정 욕구', '주목받지 못함'], '완드 6은 승리의 월계관을 쓰고 사람들의 환호를 받는 모습이에요. 노력이 인정받고 자신감이 높아지는 기운이에요.', '역방향 완드 6은 기대만큼 인정받지 못해 자신감이 줄어든 모습이에요. 남의 인정보다 내가 나를 알아봐 주는 게 먼저예요.'),
  (28, 'minor', 'wands', 7, 'Seven of Wands', '완드 7', '/tarot/28.webp', array['내 마음 지키기', '용기', '당당함'], array['지침', '방어적', '압박감'], '완드 7은 높은 곳에서 여러 막대에 맞서 자리를 지키는 모습이에요. 내 마음과 기준을 당당하게 지키는 용기의 기운이에요.', '역방향 완드 7은 지켜야 할 것이 많아 지치거나 지나치게 방어적인 모습이에요. 모든 걸 혼자 막아내지 않아도 괜찮아요.'),
  (29, 'minor', 'wands', 8, 'Eight of Wands', '완드 8', '/tarot/29.webp', array['빠른 진전', '연락', '설레는 소식'], array['지연', '엇갈린 연락', '조급함'], '완드 8은 여덟 개의 막대가 빠르게 날아가는 모습이에요. 소식이 빠르게 오가고 일이 속도감 있게 진행되는 기운이에요.', '역방향 완드 8은 연락이 늦어지거나 일이 엇갈리는 모습이에요. 조급함을 내려놓으면 흐름이 다시 이어져요.'),
  (30, 'minor', 'wands', 9, 'Nine of Wands', '완드 9', '/tarot/30.webp', array['끈기', '마지막 고비', '신중함'], array['지침', '의심', '포기하고 싶음'], '완드 9는 지친 몸으로도 끝까지 자리를 지키는 모습이에요. 마지막 고비를 앞두고 끈기와 신중함이 필요한 기운이에요.', '역방향 완드 9는 너무 지쳐 포기하고 싶거나 상처 때문에 의심이 많아진 모습이에요. 잠시 쉬어 가도 괜찮아요.'),
  (31, 'minor', 'wands', 10, 'Ten of Wands', '완드 10', '/tarot/31.webp', array['무거운 짐', '책임감', '버거움'], array['짐 내려놓기', '부담 덜기', '도움 요청'], '완드 10은 무거운 막대 묶음을 혼자 짊어지고 걸어가는 모습이에요. 책임감은 크지만 너무 많은 짐을 지고 있을 수 있어요.', '역방향 완드 10은 무거운 짐을 내려놓거나 나눌 수 있게 되는 모습이에요. 혼자 다 하려 하지 않을 때 마음이 가벼워져요.'),
  (32, 'minor', 'wands', 11, 'Page of Wands', '완드 페이지', '/tarot/32.webp', array['호기심', '설레는 소식', '새로운 관심'], array['미숙함', '변덕', '소식 지연'], '완드 페이지는 새로운 것에 호기심을 갖고 설렘을 전하는 젊은 전령이에요. 반가운 소식이나 새로운 관심이 시작되는 기운이에요.', '역방향 완드 페이지는 관심이 쉽게 식거나 마음을 서툴게 표현하는 모습이에요. 설렘을 꾸준함으로 이어가면 좋아요.'),
  (33, 'minor', 'wands', 12, 'Knight of Wands', '완드 나이트', '/tarot/33.webp', array['열정적 접근', '모험', '직진'], array['성급함', '충동', '변덕'], '완드 나이트는 말을 타고 힘차게 달려가는 열정적인 기사예요. 망설임 없이 직진하는 용기와 모험의 기운이에요.', '역방향 완드 나이트는 마음이 앞서 성급하게 행동하거나 열정이 금방 식는 모습이에요. 속도를 조절하면 열정이 오래가요.'),
  (34, 'minor', 'wands', 13, 'Queen of Wands', '완드 퀸', '/tarot/34.webp', array['자신감 있는 매력', '따뜻함', '당당함'], array['질투', '자신감 부족', '예민함'], '완드 퀸은 해바라기를 들고 당당하게 앉은 따뜻하고 매력적인 여왕이에요. 자신감 있고 밝은 매력이 사람을 끌어당기는 기운이에요.', '역방향 완드 퀸은 자신감이 흔들려 질투하거나 예민해진 모습이에요. 나의 따뜻함을 나에게도 먼저 건네 주세요.'),
  (35, 'minor', 'wands', 14, 'King of Wands', '완드 킹', '/tarot/35.webp', array['리더십', '비전', '든든함'], array['고집', '조급함', '독단'], '완드 킹은 큰 꿈을 품고 사람들을 이끄는 열정적인 왕이에요. 분명한 방향과 리더십으로 관계를 이끄는 기운이에요.', '역방향 완드 킹은 내 뜻대로만 하려 하거나 조급하게 밀어붙이는 모습이에요. 상대의 의견에 귀 기울이면 균형이 잡혀요.'),
  (36, 'minor', 'cups', 1, 'Ace of Cups', '컵 에이스', '/tarot/36.webp', array['새로운 사랑', '넘치는 감정', '순수한 마음'], array['막힌 감정', '표현 망설임', '마음 비움'], '컵 에이스는 사랑이 흘러넘치는 잔처럼 새로운 감정이 샘솟는 시작이에요. 순수한 사랑과 따뜻한 마음이 피어나는 기운이에요.', '역방향 컵 에이스는 감정이 막혀 잘 흐르지 않거나 마음을 표현하기 어려운 모습이에요. 내 마음부터 채우면 다시 흐르기 시작해요.'),
  (37, 'minor', 'cups', 2, 'Two of Cups', '컵 2', '/tarot/37.webp', array['마음이 통함', '서로의 끌림', '교감'], array['엇갈림', '불균형', '오해'], '컵 2는 두 사람이 잔을 마주하며 마음을 나누는 모습이에요. 서로에게 끌리고 마음이 통하는 따뜻한 교감의 기운이에요.', '역방향 컵 2는 마음이 엇갈리거나 주고받는 감정의 균형이 깨진 모습이에요. 솔직한 대화로 서로의 마음을 맞춰 보면 좋아요.'),
  (38, 'minor', 'cups', 3, 'Three of Cups', '컵 3', '/tarot/38.webp', array['즐거운 모임', '우정', '축하'], array['관계의 어긋남', '삼각관계', '과한 놀이'], '컵 3은 친구들이 잔을 들어 함께 축하하는 즐거운 모습이에요. 우정과 즐거운 모임 속에서 기쁨이 커지는 기운이에요.', '역방향 컵 3은 모임 속 관계가 어긋나거나 제3자가 끼어드는 모습이에요. 관계의 경계를 분명히 하면 좋아요.'),
  (39, 'minor', 'cups', 4, 'Four of Cups', '컵 4', '/tarot/39.webp', array['무관심', '권태', '생각에 잠김'], array['새로운 관심', '다시 보기', '기회 알아차림'], '컵 4는 눈앞에 내밀어진 잔을 알아차리지 못하고 생각에 잠긴 모습이에요. 마음이 무뎌져 다가오는 기회를 놓치기 쉬운 기운이에요.', '역방향 컵 4는 무뎌졌던 마음이 깨어나 새로운 기회를 알아차리는 모습이에요. 다시 주변을 둘러보면 좋은 것이 보여요.'),
  (40, 'minor', 'cups', 5, 'Five of Cups', '컵 5', '/tarot/40.webp', array['상실감', '아쉬움', '남은 것'], array['회복', '받아들임', '다시 일어섬'], '컵 5는 쏟아진 잔을 바라보며 슬퍼하는 모습이지만, 뒤에는 아직 쓰러지지 않은 잔 두 개가 남아 있어요. 아쉬움 속에서도 남은 것을 볼 수 있는 기운이에요.', '역방향 컵 5는 슬픔을 받아들이고 다시 일어서는 모습이에요. 남아 있는 좋은 것들을 향해 고개를 돌릴 수 있어요.'),
  (41, 'minor', 'cups', 6, 'Six of Cups', '컵 6', '/tarot/41.webp', array['추억', '순수함', '다정한 기억'], array['과거에 머묾', '현재로 돌아옴', '성장'], '컵 6은 어린 시절처럼 순수한 마음으로 꽃을 건네는 모습이에요. 다정한 추억과 순수한 마음이 관계를 따뜻하게 만드는 기운이에요.', '역방향 컵 6은 과거의 추억에 너무 머물러 있거나, 이제 현재로 돌아오는 모습이에요. 추억은 간직하고 지금을 살아가면 좋아요.'),
  (42, 'minor', 'cups', 7, 'Seven of Cups', '컵 7', '/tarot/42.webp', array['여러 선택지', '상상', '환상'], array['현실 직시', '선택', '명확함'], '컵 7은 구름 위 여러 잔에 담긴 환상 앞에서 고민하는 모습이에요. 선택지가 많아 보이지만 상상과 현실을 구분하는 게 중요한 기운이에요.', '역방향 컵 7은 환상이 걷히고 현실이 분명하게 보이는 모습이에요. 이제 정말 원하는 것을 선택할 수 있어요.'),
  (43, 'minor', 'cups', 8, 'Eight of Cups', '컵 8', '/tarot/43.webp', array['떠나감', '더 깊은 의미 찾기', '내려놓음'], array['망설임', '돌아봄', '떠나지 못함'], '컵 8은 쌓아 둔 잔을 뒤로하고 더 깊은 의미를 찾아 떠나는 모습이에요. 채워지지 않는 마음을 내려놓고 새로운 길로 나아가는 기운이에요.', '역방향 컵 8은 떠나야 할지 머물러야 할지 망설이는 모습이에요. 내 마음이 진짜 원하는 것을 먼저 확인하면 좋아요.'),
  (44, 'minor', 'cups', 9, 'Nine of Cups', '컵 9', '/tarot/44.webp', array['소원 성취', '만족', '행복'], array['채워지지 않음', '욕심', '기대 조절'], '컵 9는 원하던 것을 이루고 만족스럽게 웃는 모습이에요. 바라던 소원이 이뤄지기 쉬운 행복한 기운이에요.', '역방향 컵 9는 원하는 것을 얻어도 마음이 채워지지 않거나 기대가 너무 커진 모습이에요. 이미 가진 행복을 돌아보면 좋아요.'),
  (45, 'minor', 'cups', 10, 'Ten of Cups', '컵 10', '/tarot/45.webp', array['행복한 관계', '따뜻한 가정', '충만함'], array['관계의 균열', '가치관 차이', '기대 어긋남'], '컵 10은 무지개 아래에서 사랑하는 사람들과 함께 행복을 나누는 모습이에요. 오래도록 이어지는 따뜻하고 충만한 관계의 기운이에요.', '역방향 컵 10은 겉으로는 행복해 보여도 서로 바라는 그림이 조금씩 다른 모습이에요. 솔직한 대화로 같은 그림을 그려 가면 좋아요.'),
  (46, 'minor', 'cups', 11, 'Page of Cups', '컵 페이지', '/tarot/46.webp', array['설레는 소식', '감성', '다정한 표현'], array['서툰 감정', '감정 기복', '미성숙'], '컵 페이지는 잔 속 물고기를 보며 신기해하는 순수한 소년이에요. 설레는 감정의 소식이나 다정한 표현이 찾아오는 기운이에요.', '역방향 컵 페이지는 감정을 서툴게 표현하거나 기분이 쉽게 흔들리는 모습이에요. 마음을 천천히 정리하면 좋아요.'),
  (47, 'minor', 'cups', 12, 'Knight of Cups', '컵 나이트', '/tarot/47.webp', array['로맨틱한 제안', '다정한 접근', '고백'], array['비현실적 기대', '변덕', '말뿐인 약속'], '컵 나이트는 잔을 들고 천천히 다가오는 로맨틱한 기사예요. 다정한 고백이나 데이트 제안이 찾아오기 쉬운 기운이에요.', '역방향 컵 나이트는 달콤한 말에 비해 행동이 따르지 않거나 기대가 지나치게 큰 모습이에요. 말보다 행동을 지켜보면 좋아요.'),
  (48, 'minor', 'cups', 13, 'Queen of Cups', '컵 퀸', '/tarot/48.webp', array['공감', '따뜻한 배려', '깊은 감정'], array['감정에 휩쓸림', '지나친 헌신', '예민함'], '컵 퀸은 잔을 바라보며 깊은 감정을 헤아리는 다정한 여왕이에요. 공감과 배려로 마음을 어루만지는 따뜻한 기운이에요.', '역방향 컵 퀸은 감정에 너무 휩쓸리거나 상대를 챙기느라 나를 잃는 모습이에요. 나의 감정도 소중히 돌봐 주세요.'),
  (49, 'minor', 'cups', 14, 'King of Cups', '컵 킹', '/tarot/49.webp', array['감정의 안정', '포용력', '성숙한 사랑'], array['감정 억누름', '냉정함', '감정 조절 어려움'], '컵 킹은 거친 바다 위에서도 침착하게 잔을 든 왕이에요. 감정을 성숙하게 다스리며 상대를 포용하는 안정된 기운이에요.', '역방향 컵 킹은 감정을 억누르다 차갑게 보이거나, 감정을 다스리기 어려운 모습이에요. 솔직한 감정 표현이 관계를 따뜻하게 해요.'),
  (50, 'minor', 'swords', 1, 'Ace of Swords', '소드 에이스', '/tarot/50.webp', array['명확함', '진실', '솔직한 말'], array['혼란', '날카로운 말', '오해'], '소드 에이스는 구름을 가르고 솟은 칼처럼 생각이 또렷해지고 진실이 드러나는 기운이에요. 솔직하고 분명한 말이 관계를 정리해 줘요.', '역방향 소드 에이스는 생각이 엉키거나 말이 날카롭게 전해지는 모습이에요. 한 번 더 생각하고 부드럽게 말하면 좋아요.'),
  (51, 'minor', 'swords', 2, 'Two of Swords', '소드 2', '/tarot/51.webp', array['고민', '결정 보류', '마음의 벽'], array['결정', '감정 마주하기', '혼란 해소'], '소드 2는 눈을 가린 채 두 칼을 엇갈려 든 모습이에요. 결정을 미루며 마음을 지키고 있는 고민의 기운이에요.', '역방향 소드 2는 미뤄 둔 결정을 내리거나 감추던 감정을 마주하는 모습이에요. 마음을 열면 답이 분명해져요.'),
  (52, 'minor', 'swords', 3, 'Three of Swords', '소드 3', '/tarot/52.webp', array['마음의 아픔', '서운함', '슬픔'], array['회복', '상처 치유', '용서'], '소드 3은 하트에 칼이 꽂힌 모습으로 마음이 아픈 순간을 뜻해요. 아프지만, 그 아픔을 인정할 때 치유가 시작돼요.', '역방향 소드 3은 아팠던 마음이 조금씩 아물어 가는 모습이에요. 상처를 돌보며 다시 웃을 준비를 하는 기운이에요.'),
  (53, 'minor', 'swords', 4, 'Four of Swords', '소드 4', '/tarot/53.webp', array['휴식', '재충전', '잠시 멈춤'], array['회복', '다시 움직임', '지친 마음'], '소드 4는 조용히 누워 쉬고 있는 기사의 모습이에요. 마음과 몸을 쉬게 하며 재충전하는 시간이 필요한 기운이에요.', '역방향 소드 4는 충분히 쉬고 다시 움직일 준비를 하거나, 쉬지 못해 지친 모습이에요. 나에게 맞는 쉼을 챙겨 주세요.'),
  (54, 'minor', 'swords', 5, 'Five of Swords', '소드 5', '/tarot/54.webp', array['다툼 뒤의 허무함', '이기려는 마음', '갈등'], array['화해', '갈등 정리', '내려놓음'], '소드 5는 다툼에서 이겼지만 주변이 떠나간 허전한 모습이에요. 이기려는 마음보다 관계를 지키는 마음이 중요하다는 기운이에요.', '역방향 소드 5는 다툼을 멈추고 화해하거나 갈등을 정리하는 모습이에요. 자존심을 내려놓으면 관계가 회복될 수 있어요.'),
  (55, 'minor', 'swords', 6, 'Six of Swords', '소드 6', '/tarot/55.webp', array['나아감', '회복의 여정', '변화'], array['정체', '떠나지 못함', '미련'], '소드 6은 배를 타고 잔잔한 물을 건너 새로운 곳으로 나아가는 모습이에요. 어려운 시기를 지나 더 편안한 곳으로 가는 회복의 기운이에요.', '역방향 소드 6은 떠나야 할 곳을 떠나지 못하고 머무는 모습이에요. 천천히라도 한 걸음 나아가면 마음이 편해져요.'),
  (56, 'minor', 'swords', 7, 'Seven of Swords', '소드 7', '/tarot/56.webp', array['숨은 마음', '전략', '조심스러움'], array['솔직해짐', '진실이 드러남', '양심'], '소드 7은 칼을 몰래 들고 조심스럽게 빠져나가는 모습이에요. 숨기는 마음이나 혼자 해결하려는 전략의 기운이에요.', '역방향 소드 7은 숨겼던 것이 드러나거나 솔직해지기로 마음먹는 모습이에요. 진실한 태도가 관계를 지켜 줘요.'),
  (57, 'minor', 'swords', 8, 'Eight of Swords', '소드 8', '/tarot/57.webp', array['스스로 만든 제약', '막막함', '두려움'], array['벗어남', '자유', '새로운 시선'], '소드 8은 눈이 가려진 채 칼 사이에 서 있지만, 사실 묶인 끈은 느슨한 모습이에요. 두려움이 나를 가두고 있을 뿐, 벗어날 길이 있는 기운이에요.', '역방향 소드 8은 나를 가두던 생각에서 벗어나 자유로워지는 모습이에요. 새로운 시선으로 보면 길이 보여요.'),
  (58, 'minor', 'swords', 9, 'Nine of Swords', '소드 9', '/tarot/58.webp', array['걱정', '불안한 밤', '생각 과잉'], array['걱정 해소', '회복', '도움 요청'], '소드 9는 밤에 잠 못 들고 걱정에 잠긴 모습이에요. 실제보다 머릿속 걱정이 더 크게 느껴지는 기운이에요.', '역방향 소드 9는 걱정이 조금씩 가라앉고 마음이 편안해지는 모습이에요. 누군가와 나누면 걱정은 더 빨리 줄어들어요.'),
  (59, 'minor', 'swords', 10, 'Ten of Swords', '소드 10', '/tarot/59.webp', array['끝맺음', '바닥을 침', '새로운 새벽'], array['회복의 시작', '다시 일어섬', '끝을 받아들임'], '소드 10은 가장 힘든 순간을 지나고 있지만, 저 멀리 새벽빛이 밝아오는 모습이에요. 더 내려갈 곳이 없는 끝은 곧 새로운 시작의 기운이에요.', '역방향 소드 10은 힘든 시기를 지나 조금씩 다시 일어서는 모습이에요. 회복의 첫걸음을 내딛는 기운이에요.'),
  (60, 'minor', 'swords', 11, 'Page of Swords', '소드 페이지', '/tarot/60.webp', array['호기심', '관찰', '새로운 소식'], array['뒷말', '성급한 말', '조급함'], '소드 페이지는 바람 속에서 칼을 들고 주변을 살피는 호기심 많은 젊은이예요. 새로운 정보나 소식을 알아가는 기운이에요.', '역방향 소드 페이지는 확인되지 않은 말에 흔들리거나 성급하게 말하는 모습이에요. 듣고 확인한 뒤 말하면 좋아요.'),
  (61, 'minor', 'swords', 12, 'Knight of Swords', '소드 나이트', '/tarot/61.webp', array['직진', '빠른 결단', '솔직함'], array['성급함', '무심한 말', '충돌'], '소드 나이트는 바람을 가르며 전속력으로 달려가는 기사예요. 빠르게 결단하고 솔직하게 돌진하는 기운이에요.', '역방향 소드 나이트는 너무 서두르거나 생각 없이 말해 부딪히는 모습이에요. 속도를 줄이고 상대를 살피면 좋아요.'),
  (62, 'minor', 'swords', 13, 'Queen of Swords', '소드 퀸', '/tarot/62.webp', array['분명한 기준', '독립심', '솔직함'], array['차가움', '날카로움', '마음의 벽'], '소드 퀸은 칼을 곧게 세우고 분명하게 판단하는 여왕이에요. 감정에 휩쓸리지 않고 솔직하고 분명한 기준을 지키는 기운이에요.', '역방향 소드 퀸은 상처 때문에 마음을 닫거나 말이 날카로워지는 모습이에요. 단단함 속에 따뜻함을 조금 더해 주면 좋아요.'),
  (63, 'minor', 'swords', 14, 'King of Swords', '소드 킹', '/tarot/63.webp', array['이성적 판단', '공정함', '신뢰'], array['냉정함', '독단', '감정 무시'], '소드 킹은 칼을 들고 공정하게 판단하는 지혜로운 왕이에요. 감정보다 이성으로 상황을 정리하고 신뢰를 주는 기운이에요.', '역방향 소드 킹은 지나치게 냉정하거나 내 판단만 고집하는 모습이에요. 머리와 마음의 균형을 찾으면 좋아요.'),
  (64, 'minor', 'pentacles', 1, 'Ace of Pentacles', '펜타클 에이스', '/tarot/64.webp', array['현실적인 시작', '안정', '좋은 기회'], array['놓친 기회', '준비 부족', '불안정'], '펜타클 에이스는 손바닥 위에 놓인 황금 동전처럼 현실적이고 단단한 기회가 찾아오는 기운이에요. 천천히 키워 갈 수 있는 안정된 시작이에요.', '역방향 펜타클 에이스는 기회가 늦어지거나 준비가 덜 된 모습이에요. 기초를 차근차근 다지면 다시 기회가 와요.'),
  (65, 'minor', 'pentacles', 2, 'Two of Pentacles', '펜타클 2', '/tarot/65.webp', array['균형 잡기', '유연함', '바쁜 일상'], array['균형 깨짐', '벅참', '우선순위 혼란'], '펜타클 2는 두 동전을 들고 유연하게 저글링하는 모습이에요. 바쁜 일상 속에서도 균형을 잡으며 여러 일을 해내는 기운이에요.', '역방향 펜타클 2는 여러 일이 겹쳐 균형이 깨지고 벅찬 모습이에요. 우선순위를 정하면 마음이 가벼워져요.'),
  (66, 'minor', 'pentacles', 3, 'Three of Pentacles', '펜타클 3', '/tarot/66.webp', array['함께 만들어 감', '협력', '노력의 인정'], array['손발이 안 맞음', '노력 부족', '소통 부족'], '펜타클 3은 여러 사람이 함께 성당을 짓는 모습이에요. 서로 힘을 모아 무언가를 함께 만들어 가는 협력의 기운이에요.', '역방향 펜타클 3은 서로 손발이 맞지 않거나 한쪽만 노력하는 모습이에요. 각자의 역할을 이야기하면 균형이 맞춰져요.'),
  (67, 'minor', 'pentacles', 4, 'Four of Pentacles', '펜타클 4', '/tarot/67.webp', array['지키려는 마음', '안정 추구', '조심스러움'], array['놓아줌', '집착 내려놓기', '마음 열기'], '펜타클 4는 동전을 꼭 끌어안고 놓지 않는 모습이에요. 가진 것을 지키고 안정을 원하지만, 너무 꽉 쥐면 마음이 닫힐 수 있는 기운이에요.', '역방향 펜타클 4는 꽉 쥐고 있던 것을 내려놓고 마음을 여는 모습이에요. 조금 느슨해질 때 새로운 것이 들어와요.'),
  (68, 'minor', 'pentacles', 5, 'Five of Pentacles', '펜타클 5', '/tarot/68.webp', array['외로움', '소외감', '어려운 시기'], array['회복', '도움을 받음', '따뜻함을 찾음'], '펜타클 5는 눈 오는 밤 따뜻한 창문 밖을 지나가는 두 사람의 모습이에요. 외롭고 힘든 시기지만, 가까이에 도움의 손길이 있다는 기운이에요.', '역방향 펜타클 5는 힘든 시기를 지나 따뜻함과 도움을 찾는 모습이에요. 마음이 조금씩 회복되는 흐름이에요.'),
  (69, 'minor', 'pentacles', 6, 'Six of Pentacles', '펜타클 6', '/tarot/69.webp', array['주고받음', '나눔', '배려'], array['불균형', '일방적인 관계', '조건부 마음'], '펜타클 6은 저울을 들고 필요한 사람에게 나누어 주는 모습이에요. 마음을 주고받으며 균형을 이루는 따뜻한 기운이에요.', '역방향 펜타클 6은 한쪽만 주거나 받는 기울어진 관계의 모습이에요. 서로 주고받는 균형을 다시 맞춰 보면 좋아요.'),
  (70, 'minor', 'pentacles', 7, 'Seven of Pentacles', '펜타클 7', '/tarot/70.webp', array['인내', '기다림', '천천히 자람'], array['조급함', '노력 대비 아쉬움', '방향 점검'], '펜타클 7은 정성껏 가꾼 나무의 열매를 바라보며 기다리는 모습이에요. 노력한 만큼 천천히 결실이 자라나는 인내의 기운이에요.', '역방향 펜타클 7은 노력에 비해 결과가 더디게 느껴지거나 조급한 모습이에요. 방향을 점검하고 꾸준히 가면 좋아요.'),
  (71, 'minor', 'pentacles', 8, 'Eight of Pentacles', '펜타클 8', '/tarot/71.webp', array['정성', '꾸준한 노력', '성실함'], array['지루함', '완벽주의', '노력의 방향'], '펜타클 8은 동전 하나하나를 정성껏 새기는 장인의 모습이에요. 꾸준하고 성실한 노력이 관계를 단단하게 만드는 기운이에요.', '역방향 펜타클 8은 반복되는 노력에 지치거나 완벽하려고 애쓰는 모습이에요. 즐거움을 되찾으면 다시 힘이 나요.'),
  (72, 'minor', 'pentacles', 9, 'Nine of Pentacles', '펜타클 9', '/tarot/72.webp', array['자기만족', '여유', '스스로 빛남'], array['의존', '외로움', '자존감 흔들림'], '펜타클 9는 풍성한 정원에서 여유롭게 시간을 즐기는 모습이에요. 스스로 일궈 낸 만족과 자립의 여유가 빛나는 기운이에요.', '역방향 펜타클 9는 혼자인 것이 외롭게 느껴지거나 누군가에게 기대고 싶은 모습이에요. 나의 가치를 먼저 믿어 주세요.'),
  (73, 'minor', 'pentacles', 10, 'Ten of Pentacles', '펜타클 10', '/tarot/73.webp', array['오래가는 관계', '안정', '함께하는 미래'], array['가치관 차이', '불안정', '현실적 갈등'], '펜타클 10은 여러 세대가 함께 모인 풍요로운 가정의 모습이에요. 오래도록 이어지는 안정된 관계와 함께하는 미래의 기운이에요.', '역방향 펜타클 10은 현실적인 문제나 가치관 차이로 관계가 흔들리는 모습이에요. 서로의 생각을 맞춰 가는 대화가 필요해요.'),
  (74, 'minor', 'pentacles', 11, 'Page of Pentacles', '펜타클 페이지', '/tarot/74.webp', array['새로운 배움', '성실한 관심', '기회'], array['미루기', '집중력 부족', '현실 회피'], '펜타클 페이지는 동전을 소중히 들여다보며 배움에 집중하는 젊은이예요. 성실한 관심과 새로운 기회를 차근차근 키우는 기운이에요.', '역방향 펜타클 페이지는 해야 할 일을 미루거나 집중하지 못하는 모습이에요. 작은 것부터 시작하면 다시 흐름이 생겨요.'),
  (75, 'minor', 'pentacles', 12, 'Knight of Pentacles', '펜타클 나이트', '/tarot/75.webp', array['믿음직함', '꾸준함', '책임감'], array['지루함', '느린 진전', '고집'], '펜타클 나이트는 천천히, 하지만 묵묵히 나아가는 성실한 기사예요. 화려하진 않아도 꾸준하고 믿음직한 마음을 보여주는 기운이에요.', '역방향 펜타클 나이트는 너무 느리거나 변화 없이 반복되어 지루해지는 모습이에요. 작은 변화를 더하면 생기가 돌아와요.'),
  (76, 'minor', 'pentacles', 13, 'Queen of Pentacles', '펜타클 퀸', '/tarot/76.webp', array['따뜻한 돌봄', '현실적인 배려', '안정감'], array['자기 소홀', '지나친 걱정', '균형 잃음'], '펜타클 퀸은 풍성한 자연 속에서 동전을 소중히 품은 다정한 여왕이에요. 따뜻하고 현실적인 배려로 상대에게 안정감을 주는 기운이에요.', '역방향 펜타클 퀸은 남을 돌보느라 나를 소홀히 하거나 걱정이 많아진 모습이에요. 나를 돌보는 것도 잊지 마세요.'),
  (77, 'minor', 'pentacles', 14, 'King of Pentacles', '펜타클 킹', '/tarot/77.webp', array['든든함', '안정된 관계', '책임감'], array['고집', '물질 중시', '융통성 부족'], '펜타클 킹은 풍요로운 정원에서 든든하게 자리를 지키는 왕이에요. 안정되고 책임감 있는 태도로 관계를 지켜 주는 기운이에요.', '역방향 펜타클 킹은 현실적인 것만 중요하게 여기거나 고집이 세진 모습이에요. 마음의 따뜻함도 함께 챙기면 좋아요.')
insert into public.tarot_interpretations
  (card_id, topic_code, is_reversed, headline, message, advice)
values
  (0, 'crush', false, '가볍게 다가가도 괜찮아요', '짝사랑을 너무 무겁게 품기보다 가벼운 인사 한마디로 시작해 보기 좋은 흐름이에요. 아직 아무것도 정해지지 않았다는 건 그만큼 가능성이 열려 있다는 뜻이기도 해요.', '오늘은 결과를 생각하지 말고 그 사람에게 웃으며 인사 한 번 건네 보세요.'),
  (0, 'crush', true, '마음만 앞서가고 있어요', '상상 속에서는 이미 많은 일이 일어났지만, 실제 거리는 아직 그대로일 수 있어요. 서두르면 상대가 당황할 수 있으니 조금씩 가까워지는 편이 좋아요.', '그 사람에 대해 내가 정말 아는 것을 세 가지만 적어 보세요. 마음이 한결 차분해져요.'),
  (0, 'their_heart', false, '편하고 즐거운 사람으로 보여요', '그 사람은 당신을 부담 없이 웃게 해 주는 사람으로 느끼는 것 같아요. 아직 깊은 감정까지 정리되진 않았지만, 함께 있을 때의 가벼운 즐거움은 분명해 보여요.', '무거운 질문보다 같이 웃을 수 있는 이야기를 먼저 꺼내 보세요.'),
  (0, 'their_heart', true, '아직 마음을 정하지 못했어요', '상대는 당신이 싫진 않지만 이 관계를 어떻게 이어갈지 스스로도 잘 모르는 상태일 수 있어요. 지금은 답을 재촉하기보다 상대의 속도를 지켜봐 주는 게 좋아요.', '답을 기다리는 동안 내 하루도 즐겁게 채워 두세요.'),
  (0, 'some', false, '설레는 첫 페이지예요', '썸이 막 시작된 듯한 풋풋한 흐름이에요. 정해진 규칙 없이 자유롭게 대화가 오가는 지금이 가장 설레는 때일 수 있어요.', '처음 가 보는 곳으로 가볍게 놀러 가자고 제안해 보세요.'),
  (0, 'some', true, '속도가 서로 달라요', '한 사람은 앞서가고 한 사람은 멈춰 있는 느낌이 들 수 있어요. 지금 관계가 어디쯤인지 서로 확인하지 않은 채 흘러가고 있는지도 몰라요.', '연락의 빈도보다 대화의 온도를 먼저 맞춰 보세요.'),
  (0, 'breakup', false, '새 출발선에 서 있어요', '지난 관계를 돌아보기보다 새로운 나로 출발하기 좋은 기운이에요. 다시 만나든 아니든, 지금의 나는 이전과 다른 마음으로 시작할 수 있어요.', '오늘은 예전에 해 보고 싶었던 작은 일 하나를 혼자 해 보세요.'),
  (0, 'breakup', true, '서두르지 않아도 괜찮아요', '외로움에 떠밀려 연락하거나 새 사람을 급히 찾고 싶은 마음이 들 수 있어요. 마음이 충분히 정리된 뒤에 내리는 선택이 나를 더 지켜줘요.', '연락하고 싶을 때는 메모장에 먼저 적어 두고 하루만 기다려 보세요.'),
  (0, 'confess', false, '가볍게 마음을 건네 봐요', '완벽한 순간을 기다리기보다 솔직한 한마디가 통하기 쉬운 흐름이에요. 무겁지 않게, 지금 느끼는 그대로 전하면 상대도 편하게 받아들일 수 있어요.', '"너랑 있으면 즐거워"처럼 부담 없는 말부터 시작해 보세요.'),
  (0, 'confess', true, '조금 더 알아가도 좋아요', '지금 고백하면 마음은 전해져도 상대가 준비되지 않았을 수 있어요. 서로를 더 알아가는 시간을 조금 쌓은 뒤라면 더 편하게 마음을 나눌 수 있어요.', '고백 전에 둘만의 대화 시간을 한두 번 더 만들어 보세요.'),
  (1, 'crush', false, '내 매력을 보여줄 때예요', '당신에게는 그 사람의 눈길을 끌 매력이 충분해요. 마음속으로만 바라보기보다 대화를 먼저 걸거나 작은 도움을 건네면 관계가 움직이기 시작해요.', '그 사람이 관심 있는 주제를 하나 골라 먼저 말을 걸어 보세요.'),
  (1, 'crush', true, '나다움이 가장 큰 매력이에요', '잘 보이려고 애쓰다 보니 오히려 내 모습이 흐려지고 있을 수 있어요. 꾸민 모습보다 편안한 나일 때 상대도 더 가까이 느껴요.', '오늘은 잘 보이려는 말 대신 내가 정말 좋아하는 것 이야기를 해 보세요.'),
  (1, 'their_heart', false, '당신에게 흥미를 느껴요', '그 사람은 당신의 말솜씨나 재주에 은근히 끌리고 있는 것 같아요. 함께 있으면 뭔가 재미있는 일이 생길 것 같다고 느낄 수 있어요.', '다음 대화에서 상대의 이야기에 재치 있게 반응해 보세요.'),
  (1, 'their_heart', true, '진심을 확인하고 싶어 해요', '상대는 당신의 말이 진심인지, 그냥 하는 말인지 헷갈려하고 있을 수 있어요. 말보다 행동으로 꾸준히 보여주면 믿음이 쌓여요.', '약속한 작은 일 하나를 꼭 지켜서 보여주세요.'),
  (1, 'some', false, '주도권이 당신에게 있어요', '썸의 흐름을 원하는 방향으로 이끌 힘이 당신에게 있는 시기예요. 먼저 약속을 잡거나 분위기를 만들면 상대도 자연스럽게 따라올 수 있어요.', '날짜와 장소까지 정해서 구체적으로 만남을 제안해 보세요.'),
  (1, 'some', true, '말과 행동을 맞춰 봐요', '말로는 관심을 보이면서 행동은 망설이고 있거나, 그 반대일 수 있어요. 상대가 헷갈리지 않도록 신호를 분명하게 보내 주면 좋아요.', '연락을 기다리기보다 내가 먼저 한 번 연락해 보세요.'),
  (1, 'breakup', false, '내 힘으로 다시 일어서요', '관계의 끝이 나를 작게 만들지 않아요. 지금은 내가 가진 재능과 에너지를 나를 위해 쓰기 좋은 때이고, 그 모습이 새로운 인연도 불러와요.', '미뤄 둔 배움이나 취미를 하나 시작해 보세요.'),
  (1, 'breakup', true, '말로 붙잡기보다 정리해요', '다시 잘해 보자는 말로 상황을 바꾸고 싶은 마음이 들 수 있어요. 하지만 지금은 말보다 내 마음을 차분히 정리하는 시간이 먼저예요.', '보내고 싶은 메시지가 있다면 보내지 않는 편지로 써 보세요.'),
  (1, 'confess', false, '말이 잘 통하는 때예요', '당신의 말에 힘이 실리는 시기라 마음을 전하기 좋은 흐름이에요. 준비한 말을 너무 꾸미지 않고 진심을 담아 말하면 잘 전해질 수 있어요.', '고백할 말을 짧게 한 문장으로 정리해 두세요.'),
  (1, 'confess', true, '준비한 말보다 진심이 먼저예요', '멋진 고백을 계획할수록 긴장이 커지고 있을 수 있어요. 화려한 연출보다 담백한 진심이 상대에게 더 잘 닿아요.', '거울 앞에서 한 번 소리 내어 말해 보면 긴장이 풀려요.'),
  (2, 'crush', false, '조용히 마음이 자라고 있어요', '겉으로 드러내지 않았지만 당신의 마음은 차분하고 깊게 자라고 있어요. 지금은 서두르기보다 그 사람을 조용히 알아가며 직감을 믿어도 좋은 때예요.', '그 사람에 대한 느낌을 일기에 짧게 적어 보세요.'),
  (2, 'crush', true, '혼자 상상이 커지고 있어요', '그 사람의 작은 행동 하나에 혼자 의미를 붙이며 마음을 졸이고 있을 수 있어요. 상상보다 실제 대화가 더 많은 걸 알려줄 거예요.', '궁금한 게 있다면 가벼운 질문으로 직접 물어보세요.'),
  (2, 'their_heart', false, '말하지 않은 호감이 있어요', '그 사람은 겉으로 표현하진 않지만 당신을 조용히 의식하고 있는 것 같아요. 속마음을 쉽게 꺼내지 않는 성향이라 천천히 다가가 주면 좋아요.', '상대가 편하게 말할 수 있도록 먼저 차분히 들어주세요.'),
  (2, 'their_heart', true, '속마음을 감추고 있어요', '상대가 자기 마음을 스스로도 잘 모르거나 일부러 감추고 있을 수 있어요. 지금 보이는 반응만으로 마음을 판단하지 않는 게 좋아요.', '추측은 잠시 내려놓고 상대의 말과 행동을 있는 그대로 봐 주세요.'),
  (2, 'some', false, '말없이 통하는 사이예요', '말로 확인하지 않아도 서로의 분위기를 느끼고 있는 썸이에요. 다만 마음이 깊어질수록 한 번쯤은 말로 나누는 순간이 필요해질 수 있어요.', '둘만 아는 이야기를 하나 만들어 보세요.'),
  (2, 'some', true, '확인이 필요한 때예요', '서로 눈치만 보며 관계가 애매하게 머물러 있을 수 있어요. 혼자 해석하는 대신 지금 마음을 조금씩 꺼내 보면 흐름이 선명해져요.', '"요즘 너랑 얘기하는 게 좋아"처럼 작은 마음부터 표현해 보세요.'),
  (2, 'breakup', false, '내 마음의 소리를 들어요', '다시 만나고 싶은 건지, 그때의 내가 그리운 건지 조용히 들여다보기 좋은 때예요. 답은 상대보다 내 마음 안에 있을 가능성이 커요.', '산책하며 혼자만의 시간을 가져 보세요.'),
  (2, 'breakup', true, '정리되지 않은 감정이 있어요', '괜찮은 척했지만 아직 마음속에 남은 감정이 있을 수 있어요. 그 감정을 억누르기보다 인정해 줘야 진짜로 정리할 수 있어요.', '믿을 수 있는 친구에게 솔직한 마음을 털어놓아 보세요.'),
  (2, 'confess', false, '조금 더 지켜봐도 좋아요', '지금은 말하기보다 상대의 마음을 조용히 살피기 좋은 때예요. 직감이 ''지금이야''라고 말하는 순간이 오면 그때 전해도 늦지 않아요.', '상대가 나에게 보내는 작은 신호들을 눈여겨봐 주세요.'),
  (2, 'confess', true, '망설임의 이유를 살펴봐요', '고백을 미루는 데에는 불안한 마음이 숨어 있을 수 있어요. 무엇이 걱정되는지 알면 고백할 용기도 생겨요.', '고백이 걱정되는 이유를 하나씩 적어 보세요. 생각보다 작을 수 있어요.'),
  (3, 'crush', false, '따뜻한 매력이 빛나요', '당신의 다정하고 포근한 분위기가 그 사람에게 자연스럽게 전해지는 때예요. 억지로 노력하지 않아도 함께 있는 시간이 편안하게 느껴질 수 있어요.', '좋아하는 옷을 입고 기분 좋은 하루를 보내 보세요.'),
  (3, 'crush', true, '주기만 하고 있진 않나요', '그 사람을 챙기느라 내 마음이 지쳐 있을 수 있어요. 일방적으로 주는 마음보다 서로 주고받을 때 관계가 더 단단해져요.', '오늘은 그 사람보다 나를 위해 작은 선물을 해 주세요.'),
  (3, 'their_heart', false, '곁에 있으면 편안해해요', '그 사람은 당신과 있을 때 마음이 놓이고 편하다고 느끼는 것 같아요. 당신이 주는 따뜻함을 고맙게 여기고 있을 가능성이 커요.', '함께 맛있는 걸 먹으며 편안한 시간을 보내 보세요.'),
  (3, 'their_heart', true, '고마움을 표현하지 못하고 있어요', '상대는 당신의 다정함에 익숙해져서 고마움을 미처 표현하지 못하고 있을 수 있어요. 서운한 마음이 있다면 쌓아두지 않는 게 좋아요.', '부드럽게 "나도 이런 게 필요해"라고 말해 보세요.'),
  (3, 'some', false, '무르익어 가는 썸이에요', '함께 보내는 시간이 쌓이며 관계가 자연스럽게 따뜻해지고 있어요. 서로를 챙기는 마음이 오가는 지금, 썸이 한 단계 깊어지기 좋은 흐름이에요.', '직접 만든 간식이나 작은 선물을 건네 보세요.'),
  (3, 'some', true, '한쪽만 애쓰고 있어요', '썸을 이어가려는 노력이 한쪽에 치우쳐 있을 수 있어요. 내가 들이는 마음만큼 상대도 표현하는지 차분히 살펴보면 좋아요.', '연락을 먼저 하는 횟수를 조금 줄이고 상대의 반응을 지켜보세요.'),
  (3, 'breakup', false, '나를 돌보는 시간이에요', '이별 뒤의 지금은 나를 충분히 아끼고 채워 주기 좋은 때예요. 마음이 넉넉해지면 다시 만나든 새로운 사람을 만나든 더 건강한 사랑을 할 수 있어요.', '좋아하는 음식을 먹고 푹 쉬는 하루를 보내 보세요.'),
  (3, 'breakup', true, '허전함을 급히 채우지 않아요', '빈자리가 크게 느껴져 누군가에게 기대고 싶어질 수 있어요. 지금은 다른 사람보다 나 자신이 나를 먼저 돌봐 줘야 할 때예요.', '외로울 때 할 수 있는 나만의 루틴을 하나 만들어 보세요.'),
  (3, 'confess', false, '따뜻하게 전하기 좋아요', '당신의 진심이 다정하게 전해지기 좋은 흐름이에요. 편안한 분위기 속에서 마음을 전하면 상대도 부드럽게 받아줄 수 있어요.', '분위기 좋은 카페처럼 편안한 장소에서 이야기해 보세요.'),
  (3, 'confess', true, '내 마음부터 채워요', '상대를 위해 많은 걸 해 주고 그 보답으로 고백을 기대하고 있을 수 있어요. 고백은 대가가 아니라 내 마음을 전하는 일이라는 걸 기억해 주세요.', '고백하기 전에 내가 원하는 관계를 먼저 생각해 보세요.'),
  (4, 'crush', false, '믿음직한 모습이 통해요', '들뜬 표현보다 한결같고 믿음직한 태도가 그 사람에게 좋은 인상을 줄 수 있어요. 천천히, 하지만 꾸준히 다가가는 방식이 잘 어울려요.', '약속 시간 지키기처럼 작은 신뢰를 쌓아 보세요.'),
  (4, 'crush', true, '내 기준만 고집하고 있어요', '그 사람이 이렇게 해 줬으면 하는 기대가 너무 커져 있을 수 있어요. 내 기준을 조금 내려놓으면 그 사람의 진짜 모습이 더 잘 보여요.', '그 사람의 행동을 평가하기보다 궁금해해 보세요.'),
  (4, 'their_heart', false, '진지하게 생각하고 있어요', '그 사람은 당신과의 관계를 가볍게 보지 않고 책임감 있게 생각하는 것 같아요. 표현은 서툴러도 마음은 꽤 단단할 수 있어요.', '상대의 묵묵한 행동 속 마음을 알아봐 주세요.'),
  (4, 'their_heart', true, '부담을 느끼고 있을 수 있어요', '상대는 관계에서 주도권이나 기대에 대한 부담을 느끼고 있을 수 있어요. 서로 편하게 의견을 나눌 수 있는 분위기가 필요해요.', '결정을 함께 내리는 작은 경험을 만들어 보세요.'),
  (4, 'some', false, '관계에 틀이 잡혀 가요', '썸이 점점 안정적인 모습을 갖춰 가는 흐름이에요. 연락과 만남이 규칙적으로 이어지고 있다면 관계를 분명히 할 준비가 되어 가는 중일 수 있어요.', '정기적으로 만나는 요일을 하나 정해 보세요.'),
  (4, 'some', true, '밀고 당기기가 지나쳐요', '누가 먼저 다가가는지를 두고 서로 자존심을 세우고 있을 수 있어요. 이기려는 마음을 내려놓으면 관계가 한결 편해져요.', '오늘은 먼저 연락하는 쪽이 되어 보세요.'),
  (4, 'breakup', false, '중심을 다시 세워요', '흔들렸던 일상을 다시 단단하게 세우기 좋은 때예요. 내 생활의 중심이 잡히면 지난 관계도 한결 차분하게 바라볼 수 있어요.', '기상 시간과 잠드는 시간을 일정하게 지켜 보세요.'),
  (4, 'breakup', true, '통제할 수 없는 건 놓아줘요', '상대의 마음이나 결과를 내 뜻대로 바꾸고 싶은 마음이 들 수 있어요. 바꿀 수 없는 것을 받아들이는 것도 나를 지키는 힘이에요.', '내가 할 수 있는 일과 없는 일을 나눠 적어 보세요.'),
  (4, 'confess', false, '확신을 가지고 말해요', '마음이 충분히 단단해졌다면 분명하게 전하기 좋은 흐름이에요. 돌려 말하기보다 정직하고 담백하게 말하는 것이 더 잘 통해요.', '원하는 관계를 한 문장으로 분명하게 정리해 보세요.'),
  (4, 'confess', true, '답을 강요하지 않아요', '고백과 함께 바로 답을 듣고 싶은 마음이 클 수 있어요. 상대에게 생각할 시간을 주면 더 진심 어린 대답을 들을 수 있어요.', '"천천히 생각해도 괜찮아"라는 말을 함께 건네 보세요.'),
  (5, 'crush', false, '진지한 마음이 통해요', '가벼운 장난보다 성실하고 진지한 태도가 그 사람에게 더 잘 닿을 수 있어요. 공통의 관심사나 모임을 통해 자연스럽게 가까워지기 좋아요.', '그 사람과 함께하는 모임이나 활동에 꾸준히 참여해 보세요.'),
  (5, 'crush', true, '나만의 방식이 필요해요', '남들이 말하는 연애 공식에 맞추려다 오히려 지칠 수 있어요. 나에게 맞는 속도와 방식으로 다가가도 괜찮아요.', '연애 조언은 잠시 멈추고 내 느낌대로 해 보세요.'),
  (5, 'their_heart', false, '믿을 수 있는 사람으로 봐요', '그 사람은 당신을 믿을 수 있는 사람, 진지하게 대할 사람으로 여기는 것 같아요. 가볍지 않은 관계를 원하고 있을 수 있어요.', '상대의 고민을 진지하게 들어주세요.'),
  (5, 'their_heart', true, '생각이 다르다고 느껴요', '상대는 연애에 대한 생각이나 가치관이 당신과 조금 다르다고 느끼고 있을 수 있어요. 다른 점을 확인하는 대화가 오해를 줄여줘요.', '연애에서 중요하게 생각하는 것을 서로 이야기해 보세요.'),
  (5, 'some', false, '진지한 관계로 가는 중이에요', '썸이 장난스러운 단계를 지나 진지한 관계를 향해 가고 있어요. 서로의 가치관이 잘 맞는다면 자연스럽게 다음 단계로 이어질 수 있어요.', '주변 친구들에게 그 사람을 소개해 보는 것도 좋아요.'),
  (5, 'some', true, '관계의 정의가 달라요', '한 사람은 썸이라 생각하고 다른 사람은 친구라고 생각하는 것처럼, 서로 관계를 다르게 보고 있을 수 있어요. 기대를 맞춰 보는 시간이 필요해요.', '지금 우리 사이를 어떻게 생각하는지 가볍게 물어보세요.'),
  (5, 'breakup', false, '지난 관계에서 배워요', '지난 관계를 돌아보며 내가 연애에서 무엇을 중요하게 여기는지 알 수 있는 때예요. 그 배움이 다음 인연을 더 단단하게 만들어줘요.', '다음 연애에서 지키고 싶은 약속 세 가지를 적어 보세요.'),
  (5, 'breakup', true, '예전 틀에 갇히지 않아요', '익숙한 관계라서 다시 돌아가고 싶은 마음이 들 수 있어요. 익숙함과 행복은 다를 수 있으니, 다시 만나는 것만 답이라고 생각하지 않아도 괜찮아요.', '그 사람이 그리운 건지, 익숙함이 그리운 건지 조용히 적어 보세요.'),
  (5, 'confess', false, '진지하게 전하기 좋아요', '장난처럼 넘기기보다 진지하게 마음을 전하기 좋은 흐름이에요. 성실하게 준비한 고백이 신뢰를 줄 수 있어요.', '조용하고 차분한 장소를 골라 진지하게 이야기해 보세요.'),
  (5, 'confess', true, '형식보다 진심이에요', '정해진 고백 방식에 얽매일 필요는 없어요. 나다운 방식으로 마음을 전하는 게 더 자연스러울 수 있어요.', '남들이 하는 이벤트 대신 나만의 표현을 생각해 보세요.'),
  (6, 'crush', false, '마음이 서로를 향하고 있어요', '짝사랑이 한쪽만의 마음이 아닐 수 있다는 기운이 보여요. 그 사람과 함께하는 순간마다 느껴지는 끌림을 믿어 봐도 좋아요.', '둘이서 이야기할 수 있는 시간을 조금 더 만들어 보세요.'),
  (6, 'crush', true, '마음의 박자가 달라요', '내 마음과 그 사람의 마음이 지금은 조금 다른 박자로 움직이고 있을 수 있어요. 억지로 맞추기보다 서로를 더 알아가는 게 먼저예요.', '그 사람이 좋아하는 것을 하나 더 알아봐 주세요.'),
  (6, 'their_heart', false, '당신에게 끌리고 있어요', '그 사람은 당신에게 분명한 호감과 끌림을 느끼고 있는 것 같아요. 함께 있을 때 마음이 잘 통한다고 생각하고 있을 수 있어요.', '상대가 보내는 호감 신호에 따뜻하게 반응해 주세요.'),
  (6, 'their_heart', true, '마음속 고민이 있어요', '상대는 당신에게 마음이 있으면서도 다른 고민이나 선택 때문에 망설이고 있을 수 있어요. 지금은 재촉보다 이해가 필요해요.', '상대가 고민을 편하게 말할 수 있게 기다려 주세요.'),
  (6, 'some', false, '연인으로 가는 갈림길이에요', '썸이 연애로 이어지기 좋은 흐름이에요. 서로의 마음이 잘 맞고 있다면 이제 관계를 분명히 선택하는 순간이 다가오고 있어요.', '둘만의 특별한 데이트를 계획해 보세요.'),
  (6, 'some', true, '서로 다른 그림을 그려요', '같은 썸 안에서도 서로 원하는 관계의 모습이 다를 수 있어요. 엇갈림을 그냥 두기보다 솔직한 대화로 맞춰 보면 좋아요.', '"우리 어떤 사이일까?"를 부드럽게 꺼내 보세요.'),
  (6, 'breakup', false, '진심으로 선택할 때예요', '다시 만날지, 새로운 길을 갈지 내 진심으로 선택할 수 있는 때예요. 어떤 선택이든 나를 아끼는 방향이라면 좋은 선택이에요.', '두 가지 길을 상상했을 때 마음이 편한 쪽을 느껴 보세요.'),
  (6, 'breakup', true, '같은 갈등이 반복될 수 있어요', '다시 만나더라도 예전과 같은 이유로 엇갈릴 수 있다는 신호예요. 무엇이 달라질 수 있는지 먼저 생각해 보고, 마음 정리도 함께 해 두면 좋아요.', '헤어진 이유를 차분히 돌아보며 적어 보세요.'),
  (6, 'confess', false, '마음을 전하기 좋은 때예요', '두 사람의 마음이 가까워진 지금, 진심을 전하기 좋은 흐름이에요. 망설이기보다 솔직하게 말하면 좋은 대답을 들을 가능성이 커요.', '그 사람이 특별하다는 걸 솔직하게 말해 보세요.'),
  (6, 'confess', true, '확신이 생길 때까지요', '아직 내 마음이나 상대의 마음에 확신이 부족할 수 있어요. 조금 더 함께 시간을 보내며 서로를 확인한 뒤 전해도 늦지 않아요.', '고백 전에 둘만의 대화 시간을 한 번 더 가져 보세요.'),
  (7, 'crush', false, '적극적으로 다가가요', '지금은 짝사랑을 마음속에만 두기보다 한 걸음 앞으로 나아가기 좋은 때예요. 당신의 적극적인 모습이 관계를 움직이는 힘이 돼요.', '그 사람에게 먼저 약속을 제안해 보세요.'),
  (7, 'crush', true, '속도를 조금 늦춰요', '빨리 가까워지고 싶은 마음에 조급해져 있을 수 있어요. 상대의 속도를 존중하면 오히려 더 빨리 가까워질 수 있어요.', '연락 답장을 재촉하지 말고 여유를 가져 보세요.'),
  (7, 'their_heart', false, '가까워지고 싶어 해요', '그 사람은 당신과의 관계를 앞으로 진전시키고 싶은 마음이 있는 것 같아요. 적극적인 표현이 그 신호일 수 있어요.', '상대가 다가올 때 반갑게 맞아 주세요.'),
  (7, 'their_heart', true, '마음이 복잡해요', '상대는 여러 일로 마음이 바쁘고 복잡해 관계에 집중하기 어려운 상태일 수 있어요. 당신에 대한 마음과는 별개일 수 있어요.', '상대가 바쁠 땐 짧고 따뜻한 응원 메시지를 보내 보세요.'),
  (7, 'some', false, '썸이 빠르게 진전돼요', '썸이 힘차게 앞으로 나아가는 흐름이에요. 서로 같은 방향을 보고 있다면 관계가 빠르게 깊어질 수 있어요.', '이번 주 안에 둘만의 약속을 하나 잡아 보세요.'),
  (7, 'some', true, '서로 다른 방향을 봐요', '한 사람은 앞으로 가고 싶고 다른 사람은 멈추고 싶을 수 있어요. 방향을 맞추지 않으면 썸이 제자리를 맴돌 수 있어요.', '서로 원하는 관계의 속도를 이야기해 보세요.'),
  (7, 'breakup', false, '앞을 향해 나아가요', '지난 일에 머물기보다 내 삶을 앞으로 이끌어 갈 힘이 생기는 때예요. 목표를 세우고 움직이면 마음도 함께 회복돼요.', '이번 달 이루고 싶은 목표를 하나 세워 보세요.'),
  (7, 'breakup', true, '감정에 끌려가지 않아요', '충동적으로 연락하거나 결정을 내리고 싶은 마음이 들 수 있어요. 마음이 진정된 뒤에 선택하면 후회가 줄어들어요.', '중요한 결정은 하루 지나서 다시 생각해 보세요.'),
  (7, 'confess', false, '지금 밀고 나가도 좋아요', '용기를 내어 마음을 전하기 좋은 흐름이에요. 망설임을 털어내고 당당하게 말하면 당신의 진심이 힘 있게 전해질 수 있어요.', '고백할 날짜를 정하고 그날을 향해 준비해 보세요.'),
  (7, 'confess', true, '급하게 서두르지 않아요', '마음이 급해 준비 없이 고백하고 싶어질 수 있어요. 분위기와 타이밍을 조금만 살피면 훨씬 좋은 결과로 이어질 수 있어요.', '상대가 여유 있는 날을 골라 보세요.'),
  (8, 'crush', false, '부드럽게 다가가면 돼요', '강하게 밀어붙이기보다 다정하고 꾸준하게 다가가는 게 잘 통하는 때예요. 당신의 따뜻한 인내가 그 사람의 마음을 천천히 열어줄 수 있어요.', '그 사람이 힘들어 보일 때 따뜻한 말 한마디를 건네 보세요.'),
  (8, 'crush', true, '나를 먼저 믿어 줘요', '그 사람에 비해 내가 부족하다고 느끼고 있을 수 있어요. 당신은 이미 충분히 매력 있는 사람이니 스스로를 작게 보지 않아도 돼요.', '내가 가진 좋은 점을 세 가지 적어 보세요.'),
  (8, 'their_heart', false, '편안하게 기대고 싶어 해요', '그 사람은 당신의 다정함과 차분함에서 큰 위로를 받는 것 같아요. 함께 있으면 마음이 누그러진다고 느낄 수 있어요.', '상대의 이야기를 끝까지 들어주세요.'),
  (8, 'their_heart', true, '마음을 다스리는 중이에요', '상대는 자신의 감정을 정리하느라 표현이 들쑥날쑥할 수 있어요. 반응 하나하나에 너무 마음 쓰지 않아도 괜찮아요.', '상대의 기분이 오락가락할 땐 한 발 물러서 기다려 주세요.'),
  (8, 'some', false, '천천히 단단해지는 썸이에요', '서두르지 않고 서로를 배려하며 관계가 깊어지는 흐름이에요. 인내심 있게 쌓아 온 시간이 믿음으로 자라고 있어요.', '상대의 작은 노력에 고마움을 표현해 보세요.'),
  (8, 'some', true, '감정이 앞서고 있어요', '서운함이나 질투 같은 감정이 커져 썸의 분위기가 흔들릴 수 있어요. 감정을 바로 쏟아내기보다 한 번 숨을 고르면 좋아요.', '속상한 일이 있으면 하루 정도 생각을 정리한 뒤 이야기해 보세요.'),
  (8, 'breakup', false, '다정하게 나를 회복해요', '이별의 아픔을 다정하게 다독이며 이겨낼 힘이 당신 안에 있어요. 천천히 회복하는 과정 자체가 당신을 더 단단하게 만들어줘요.', '오늘 하루 나에게 "잘하고 있어"라고 말해 주세요.'),
  (8, 'breakup', true, '감정이 출렁여도 괜찮아요', '괜찮다가도 갑자기 마음이 무너지는 날이 있을 수 있어요. 그건 자연스러운 과정이니 나를 탓하지 않아도 돼요.', '힘든 날엔 무리하지 말고 일찍 잠자리에 들어 보세요.'),
  (8, 'confess', false, '용기를 낼 수 있어요', '떨리는 마음을 다스리고 진심을 전할 용기가 생기는 때예요. 부드럽고 솔직하게 말하면 상대도 편하게 받아들일 수 있어요.', '심호흡을 세 번 하고 천천히 말해 보세요.'),
  (8, 'confess', true, '자신감을 먼저 채워요', '아직 거절이 두려워 마음이 움츠러들어 있을 수 있어요. 나를 믿는 마음이 조금 더 단단해지면 고백도 자연스러워져요.', '고백 전에 나를 응원해 주는 친구와 이야기해 보세요.'),
  (9, 'crush', false, '내 마음을 들여다볼 때예요', '그 사람을 정말 좋아하는지, 그 사람의 어떤 점이 좋은지 차분히 생각해 보기 좋은 때예요. 마음이 분명해지면 다가갈 방법도 보여요.', '그 사람을 좋아하게 된 순간을 떠올려 적어 보세요.'),
  (9, 'crush', true, '혼자 끙끙 앓고 있어요', '마음을 아무에게도 말하지 못하고 혼자 품느라 외로울 수 있어요. 믿을 수 있는 사람에게 털어놓기만 해도 한결 가벼워져요.', '친한 친구에게 짝사랑 이야기를 살짝 꺼내 보세요.'),
  (9, 'their_heart', false, '조심스럽게 생각하고 있어요', '그 사람은 당신에 대한 마음을 혼자 조용히 정리하고 있는 것 같아요. 신중한 성격이라 표현이 늦을 수 있어요.', '상대가 생각할 시간을 충분히 주세요.'),
  (9, 'their_heart', true, '마음의 문이 닫혀 있어요', '상대는 지금 연애보다 혼자만의 시간이 더 필요한 상태일 수 있어요. 당신 때문이 아니라 상대의 상황 때문일 가능성이 커요.', '부담 주지 않는 선에서 가끔 안부만 전해 보세요.'),
  (9, 'some', false, '천천히 서로를 알아가요', '썸이 빠르게 진행되기보다 천천히 깊어지는 흐름이에요. 조용한 대화 속에서 서로의 진짜 모습을 알아가기 좋은 때예요.', '조용한 곳에서 깊은 이야기를 나눠 보세요.'),
  (9, 'some', true, '거리감이 느껴져요', '썸이 잠시 멈춘 듯 거리감이 느껴질 수 있어요. 상대가 혼자만의 시간이 필요한 건지 살펴보면 좋아요.', '연락이 뜸해도 조급해하지 말고 내 일상을 지켜 보세요.'),
  (9, 'breakup', false, '나를 이해하는 시간이에요', '이별 뒤 혼자만의 시간은 나를 더 깊이 이해할 수 있는 소중한 기회예요. 이 시간을 지나면 더 성숙한 마음으로 새 인연을 맞을 수 있어요.', '혼자 조용히 걸으며 마음을 정리해 보세요.'),
  (9, 'breakup', true, '너무 오래 숨지 않아요', '아픔 때문에 사람들과의 연결을 끊고 혼자 지내고 있을 수 있어요. 조금씩이라도 밖으로 나오면 마음이 회복되는 속도가 빨라져요.', '이번 주에 친구 한 명과 짧게라도 만나 보세요.'),
  (9, 'confess', false, '조금 더 생각해도 좋아요', '고백하기 전에 내 마음과 상대와의 관계를 차분히 정리하기 좋은 때예요. 서두르지 않아도 마음이 분명해지면 타이밍은 자연스럽게 와요.', '고백 후 바라는 관계를 미리 그려 보세요.'),
  (9, 'confess', true, '혼자 결론 내리지 않아요', '"분명 안 될 거야"라고 혼자 단정하고 있을 수 있어요. 상대의 마음은 직접 확인하기 전까지 알 수 없어요.', '부정적인 생각이 들 땐 그 근거가 무엇인지 적어 보세요.'),
  (10, 'crush', false, '흐름이 바뀌고 있어요', '짝사랑에 새로운 바람이 불어오는 흐름이에요. 생각지 못한 계기로 그 사람과 가까워질 기회가 생길 수 있어요.', '평소와 다른 길이나 장소에 가 보세요. 우연이 기회가 될 수 있어요.'),
  (10, 'crush', true, '타이밍을 기다려요', '지금은 마음과 상황의 타이밍이 조금 엇갈려 있을 수 있어요. 흐름은 늘 바뀌니 조급해하지 않아도 괜찮아요.', '기다리는 동안 내가 즐거운 일에 집중해 보세요.'),
  (10, 'their_heart', false, '마음이 움직이기 시작했어요', '그 사람의 마음에 당신이 들어오기 시작한 것 같아요. 어떤 계기로 당신을 새롭게 보게 됐을 수 있어요.', '상대와 함께한 즐거운 순간을 한 번 더 만들어 보세요.'),
  (10, 'their_heart', true, '마음이 왔다 갔다 해요', '상대의 마음이 상황에 따라 흔들리고 있을 수 있어요. 지금의 반응만 보고 결론 내리지 않는 게 좋아요.', '상대의 반응에 일희일비하지 말고 내 페이스를 지켜 보세요.'),
  (10, 'some', false, '썸에 전환점이 와요', '썸이 새로운 단계로 넘어갈 수 있는 전환점이 다가오고 있어요. 작은 사건 하나가 관계를 크게 바꿀 수 있어요.', '평소와 다른 데이트를 제안해 보세요.'),
  (10, 'some', true, '같은 자리를 맴돌아요', '썸이 진전 없이 같은 패턴을 반복하고 있을 수 있어요. 흐름을 바꾸려면 작은 변화가 필요해요.', '늘 하던 연락 방식에 작은 변화를 줘 보세요.'),
  (10, 'breakup', false, '새로운 흐름이 와요', '이별 뒤 삶에 새로운 흐름이 들어오고 있어요. 다시 만나는 인연이든 새로운 인연이든, 바뀐 흐름 속에서 나를 위한 선택을 할 수 있어요.', '새로운 사람들을 만날 수 있는 자리에 나가 보세요.'),
  (10, 'breakup', true, '같은 패턴을 돌아봐요', '비슷한 이유로 이별이 반복되고 있진 않은지 살펴보기 좋은 때예요. 패턴을 알면 다음엔 다른 선택을 할 수 있어요.', '지난 연애들의 공통점을 하나 찾아 적어 보세요.'),
  (10, 'confess', false, '좋은 타이밍이 다가와요', '고백하기 좋은 흐름이 찾아오고 있어요. 자연스럽게 분위기가 무르익는 순간이 오면 그때를 놓치지 않으면 좋아요.', '둘만의 시간이 생기는 날을 눈여겨봐 두세요.'),
  (10, 'confess', true, '조금만 더 기다려요', '지금은 타이밍이 살짝 어긋나 있을 수 있어요. 상대의 상황이 바뀌고 분위기가 무르익을 때까지 기다리는 것도 방법이에요.', '고백 대신 오늘은 가벼운 안부를 전해 보세요.'),
  (11, 'crush', false, '있는 그대로 바라봐요', '그 사람을 지나치게 이상화하지도, 깎아내리지도 않고 있는 그대로 보기 좋은 때예요. 균형 잡힌 시선이 더 좋은 선택으로 이어져요.', '그 사람의 좋은 점과 아쉬운 점을 함께 적어 보세요.'),
  (11, 'crush', true, '마음의 무게가 기울어 있어요', '내가 주는 마음에 비해 돌아오는 게 적어 서운할 수 있어요. 이 관계가 나에게도 좋은지 한 번 생각해 보면 좋아요.', '내가 지치지 않는 선을 정해 두세요.'),
  (11, 'their_heart', false, '공평하게 대하고 싶어 해요', '그 사람은 당신을 존중하며 공정하게 대하고 싶어 하는 것 같아요. 감정보다 이성적으로 관계를 바라보는 성향일 수 있어요.', '솔직하고 분명하게 이야기하는 대화를 나눠 보세요.'),
  (11, 'their_heart', true, '서운함이 쌓여 있어요', '상대는 관계에서 무언가 불공평하다고 느끼고 있을 수 있어요. 오해가 있다면 차분하게 풀어 보는 게 좋아요.', '"혹시 서운한 거 있었어?"라고 먼저 물어보세요.'),
  (11, 'some', false, '서로 주고받는 썸이에요', '연락과 관심이 균형 있게 오가는 건강한 썸이에요. 이 균형이 유지된다면 관계가 자연스럽게 다음 단계로 나아갈 수 있어요.', '서로의 노력을 알아봐 주는 말을 건네 보세요.'),
  (11, 'some', true, '한쪽으로 기울어 있어요', '썸에서 한 사람만 애쓰고 있는 것 같은 느낌이 들 수 있어요. 기울어진 관계는 오래가기 어려우니 솔직하게 이야기해 보면 좋아요.', '내가 원하는 것을 분명하게 표현해 보세요.'),
  (11, 'breakup', false, '공정하게 돌아봐요', '이별의 이유를 누구 탓으로 돌리기보다 공정하게 돌아보기 좋은 때예요. 그래야 미련도 원망도 덜어낼 수 있어요.', '나와 상대 각자의 입장을 한 번씩 적어 보세요.'),
  (11, 'breakup', true, '나를 너무 탓하지 않아요', '이별의 책임을 혼자 짊어지고 있을 수 있어요. 관계는 두 사람이 함께 만든 것이니 나를 너무 몰아세우지 않아도 돼요.', '스스로에게 "그때의 나도 최선을 다했어"라고 말해 주세요.'),
  (11, 'confess', false, '솔직하게 말할 때예요', '돌려 말하지 않고 내 마음을 정직하게 전하기 좋은 흐름이에요. 상대도 솔직한 대답으로 응해줄 가능성이 커요.', '하고 싶은 말을 꾸밈없이 담백하게 정리해 보세요.'),
  (11, 'confess', true, '감정만 앞서지 않게요', '서운함이나 조급함이 섞인 고백은 의도와 다르게 전해질 수 있어요. 마음이 차분해졌을 때 전하는 게 좋아요.', '고백 전에 내 감정을 한 번 정리해 보세요.'),
  (12, 'crush', false, '다른 시선으로 바라봐요', '지금까지와 다른 방식으로 그 사람을 바라보면 새로운 면이 보일 수 있어요. 잠시 멈춰서 관계를 바라보는 시간이 도움이 돼요.', '그 사람의 입장이 되어 나를 바라본다고 상상해 보세요.'),
  (12, 'crush', true, '혼자 기다리기만 해요', '그 사람이 먼저 다가와 주길 바라며 오래 기다리고 있을 수 있어요. 기다림이 너무 길어진다면 나를 위한 선택도 생각해 보면 좋아요.', '기다림의 기한을 스스로 정해 보세요.'),
  (12, 'their_heart', false, '아직 판단을 미루고 있어요', '그 사람은 당신에 대한 마음을 결정하지 않고 지켜보는 중인 것 같아요. 서두르지 않고 천천히 생각하고 싶어 할 수 있어요.', '부담을 주지 않고 편안하게 대해 주세요.'),
  (12, 'their_heart', true, '상황에 묶여 있어요', '상대는 마음이 있어도 현재 상황 때문에 움직이기 어려운 상태일 수 있어요. 상대의 사정을 이해해 주는 마음이 필요해요.', '상대의 상황을 먼저 물어봐 주세요.'),
  (12, 'some', false, '잠시 멈춤도 의미 있어요', '썸이 잠시 멈춘 것처럼 보여도 서로를 생각하는 시간이 흐르고 있어요. 이 멈춤이 관계를 더 깊게 만들 수 있어요.', '조급한 마음은 내려놓고 상대를 기다려 주세요.'),
  (12, 'some', true, '애매함이 길어져요', '썸이 오래도록 애매하게 머물러 지칠 수 있어요. 관계를 분명히 하고 싶다면 이제는 이야기를 꺼낼 때일 수 있어요.', '내가 원하는 관계를 먼저 정리해 보세요.'),
  (12, 'breakup', false, '놓아주는 법을 배워요', '붙잡고 있던 마음을 내려놓을 때 오히려 마음이 자유로워질 수 있어요. 이별을 다른 시선으로 보면 성장의 의미가 보이기도 해요.', '지난 관계에서 얻은 좋은 것 하나를 떠올려 보세요.'),
  (12, 'breakup', true, '기다림만 하지 않아요', '다시 연락이 오기만을 기다리며 내 시간을 멈춰 두고 있을 수 있어요. 기다림보다 내 삶을 다시 움직이는 게 나를 더 행복하게 해줘요.', '미뤄 둔 약속이나 계획을 하나 다시 잡아 보세요.'),
  (12, 'confess', false, '잠시 기다려 봐요', '지금은 고백보다 한 걸음 물러서서 상황을 지켜보기 좋은 때예요. 조금 기다리면 더 좋은 타이밍과 방법이 보일 수 있어요.', '상대의 일정이나 기분이 여유로운 때를 살펴보세요.'),
  (12, 'confess', true, '망설임이 너무 길어요', '고백을 미루는 시간이 길어지면서 마음이 더 무거워지고 있을 수 있어요. 완벽한 때를 기다리기보다 작은 표현부터 시작해 보면 좋아요.', '고백 대신 오늘은 "보고 싶었어" 같은 말부터 해 보세요.'),
  (13, 'crush', false, '새로운 단계로 넘어가요', '짝사랑이 지금의 모습에서 다른 모습으로 바뀔 때가 다가오고 있어요. 바라보기만 하던 관계를 끝내고 새로운 관계로 나아갈 수 있어요.', '지금까지와 다른 방식으로 그 사람에게 다가가 보세요.'),
  (13, 'crush', true, '익숙한 마음을 놓지 못해요', '오래 품어 온 짝사랑이 익숙해져서 변화를 두려워하고 있을 수 있어요. 마음을 표현하든 정리하든, 한 걸음 움직이면 새 흐름이 생겨요.', '이 짝사랑이 나에게 어떤 의미인지 생각해 보세요.'),
  (13, 'their_heart', false, '관계를 새롭게 보고 있어요', '그 사람은 당신과의 관계를 이전과 다르게 보기 시작한 것 같아요. 친구나 지인 이상의 관계로 생각이 바뀌고 있을 수 있어요.', '상대에게 새로운 내 모습을 보여주세요.'),
  (13, 'their_heart', true, '변화를 망설이고 있어요', '상대는 관계가 달라지는 것이 두려워 지금 상태를 유지하고 싶어 할 수 있어요. 천천히 안심할 수 있게 해 주면 좋아요.', '관계가 바뀌어도 편안할 수 있다는 걸 보여 주세요.'),
  (13, 'some', false, '썸의 모양이 바뀌어요', '썸이 지금의 단계를 지나 새로운 관계로 바뀌어 갈 수 있는 흐름이에요. 애매함이 끝나고 관계가 분명해지는 시점이 다가오고 있어요.', '관계를 분명히 하는 대화를 준비해 보세요.'),
  (13, 'some', true, '애매함을 붙잡고 있어요', '변화가 두려워서 썸을 애매한 상태로 두고 있을 수 있어요. 어느 쪽이든 분명해질 때 마음도 편해져요.', '내가 이 관계에서 정말 원하는 것을 정해 보세요.'),
  (13, 'breakup', false, '한 장을 넘기는 때예요', '지난 관계의 한 장을 마무리하고 새로운 장을 시작할 수 있는 때예요. 끝은 아프지만 그만큼 새로운 인연이 들어올 자리가 생겨요.', '추억이 담긴 물건을 정리할 상자를 하나 마련해 보세요.'),
  (13, 'breakup', true, '놓아줄 준비를 해요', '끝난 관계를 계속 붙잡고 있으면 마음이 앞으로 나아가기 어려워요. 천천히라도 놓아주는 연습을 하면 새로운 시작이 보여요.', '상대의 SNS를 보는 횟수를 조금씩 줄여 보세요.'),
  (13, 'confess', false, '관계를 바꿀 용기를 내요', '지금의 애매한 관계를 끝내고 새로운 관계로 나아가기 좋은 흐름이에요. 고백이 관계를 바꾸는 계기가 될 수 있어요.', '고백 후 어떤 결과든 받아들일 마음의 준비를 해 보세요.'),
  (13, 'confess', true, '변화가 두려울 수 있어요', '고백하면 지금의 관계가 달라질까 봐 걱정하고 있을 수 있어요. 그 걱정을 인정하고, 내가 원하는 게 무엇인지 먼저 정리해 보면 좋아요.', '고백하지 않았을 때 남을 아쉬움도 함께 생각해 보세요.'),
  (14, 'crush', false, '천천히 가까워져요', '짝사랑이 서두르지 않고 자연스럽게 가까워지는 흐름이에요. 그 사람과의 거리를 조금씩 좁혀 가면 편안한 관계가 될 수 있어요.', '그 사람과 가벼운 대화를 조금씩 자주 나눠 보세요.'),
  (14, 'crush', true, '감정이 너무 커졌어요', '짝사랑에 쏟는 마음이 너무 커서 일상의 균형이 흔들릴 수 있어요. 내 생활도 함께 챙길 때 마음이 건강해져요.', '그 사람 생각이 날 때 다른 즐거운 일에 잠깐 집중해 보세요.'),
  (14, 'their_heart', false, '편안하게 맞춰 가고 싶어 해요', '그 사람은 당신과 함께할 때 편안하고 조화롭다고 느끼는 것 같아요. 서두르지 않고 천천히 관계를 키워 가고 싶어 할 수 있어요.', '상대의 속도에 맞춰 편안하게 대해 주세요.'),
  (14, 'their_heart', true, '거리를 조절하고 있어요', '상대는 관계의 속도나 거리감에 대해 고민하고 있을 수 있어요. 너무 가깝거나 멀지 않게 맞춰 주면 좋아요.', '상대가 편안해하는 거리를 존중해 주세요.'),
  (14, 'some', false, '서로 잘 맞춰 가고 있어요', '서로 다른 두 사람이 조화롭게 맞춰 가는 좋은 썸이에요. 서두르지 않아도 관계가 자연스럽게 깊어질 수 있어요.', '서로의 취향을 하나씩 섞은 데이트를 계획해 보세요.'),
  (14, 'some', true, '속도가 맞지 않아요', '썸의 속도가 서로 달라 어긋나는 느낌이 들 수 있어요. 대화를 통해 서로 편한 속도를 찾아가면 좋아요.', '서로의 연락 스타일을 이야기해 보세요.'),
  (14, 'breakup', false, '마음의 균형을 찾아요', '이별 뒤 흔들린 마음이 천천히 균형을 되찾는 때예요. 급하게 결론 내리지 않고 조금씩 회복하면 돼요.', '규칙적인 운동이나 산책으로 몸과 마음을 함께 돌봐 주세요.'),
  (14, 'breakup', true, '극단적인 선택은 미뤄요', '마음이 흔들려 갑자기 연락하거나 모든 걸 끊어버리고 싶을 수 있어요. 큰 결정은 마음이 차분해진 뒤로 미루는 게 좋아요.', '결정하기 전에 일주일만 시간을 가져 보세요.'),
  (14, 'confess', false, '자연스러운 흐름을 따라요', '억지로 타이밍을 만들기보다 자연스럽게 분위기가 무르익을 때를 기다리면 좋아요. 그 순간이 오면 편안하게 마음을 전할 수 있어요.', '평소처럼 편안한 대화 속에서 마음을 살짝 비춰 보세요.'),
  (14, 'confess', true, '조금 더 맞춰 가요', '아직 서로의 마음이나 상황이 맞지 않는 부분이 있을 수 있어요. 조금 더 시간을 보내며 맞춰 간 뒤 고백하면 좋아요.', '함께하는 시간을 조금 더 늘려 보세요.'),
  (15, 'crush', false, '끌림이 아주 강해요', '그 사람에게 강하게 끌리는 마음이 느껴져요. 다만 생각이 너무 그 사람에게만 쏠려 있다면 내 일상도 함께 챙기면 좋아요.', '그 사람의 SNS를 보는 시간을 조금 줄여 보세요.'),
  (15, 'crush', true, '마음이 가벼워지고 있어요', '짝사랑에 묶여 있던 마음이 조금씩 자유로워지고 있어요. 그 사람을 좋아하는 마음은 그대로 두되, 나를 잃지 않는 균형이 생기고 있어요.', '나를 위한 즐거운 계획을 하나 세워 보세요.'),
  (15, 'their_heart', false, '강하게 끌리고 있어요', '그 사람은 당신에게 강한 매력과 끌림을 느끼는 것 같아요. 다만 그 끌림이 진지한 마음인지는 시간을 두고 지켜보면 좋아요.', '끌림 너머 상대의 진짜 마음을 천천히 확인해 보세요.'),
  (15, 'their_heart', true, '부담을 덜고 싶어 해요', '상대는 관계에서 느끼던 부담이나 얽매임에서 조금 벗어나고 싶어 할 수 있어요. 편안한 거리를 주면 오히려 마음이 열릴 수 있어요.', '연락이나 만남의 빈도를 상대가 편한 만큼 맞춰 주세요.'),
  (15, 'some', false, '뜨겁지만 살펴봐요', '썸에 강렬한 끌림이 있지만, 감정에만 휩쓸리기 쉬운 흐름이에요. 설렘 속에서도 서로를 존중하는 관계인지 살펴보면 좋아요.', '이 관계에서 내가 편안한지 스스로 물어보세요.'),
  (15, 'some', true, '건강한 거리를 찾아요', '지나치게 얽매였던 썸에서 벗어나 건강한 거리를 찾아가는 흐름이에요. 서로에게 숨 쉴 틈을 주면 관계가 더 편해질 수 있어요.', '각자의 시간을 존중하는 약속을 해 보세요.'),
  (15, 'breakup', false, '미련을 알아차려요', '지난 관계에 대한 강한 미련이 마음을 붙잡고 있을 수 있어요. 그 감정을 알아차리는 것만으로도 벗어나는 첫걸음이 돼요.', '미련이 올라올 때 그 감정을 그대로 적어 보세요.'),
  (15, 'breakup', true, '자유로워지고 있어요', '나를 붙잡던 감정에서 조금씩 벗어나는 흐름이에요. 마음이 가벼워진 자리에 새로운 인연이 들어올 수 있어요.', '새로운 경험에 마음을 열어 보세요.'),
  (15, 'confess', false, '감정을 한 번 정리해요', '끌림이 강할수록 감정에 휩쓸려 고백하고 싶어질 수 있어요. 순간의 감정인지 깊은 마음인지 한 번 정리하면 좋아요.', '하룻밤 지나도 같은 마음인지 확인해 보세요.'),
  (15, 'confess', true, '가벼운 마음으로 전해요', '부담감이 줄어든 지금, 가볍고 솔직하게 마음을 전하기 좋아요. 결과에 너무 매달리지 않으면 고백도 편해져요.', '결과보다 내 마음을 전한다는 데 의미를 두어 보세요.'),
  (16, 'crush', false, '새로운 사실을 알게 돼요', '짝사랑에 대해 예상치 못한 사실을 알게 되거나 마음이 크게 흔들릴 수 있어요. 당황스러워도 그 덕분에 관계를 더 분명하게 볼 수 있어요.', '놀라운 일이 생기면 바로 반응하기보다 하루 생각해 보세요.'),
  (16, 'crush', true, '흔들림이 지나가고 있어요', '짝사랑으로 인한 마음의 흔들림이 조금씩 가라앉고 있어요. 미뤄 왔던 마음 정리를 천천히 해 나가기 좋은 때예요.', '지금 내 마음이 어떤지 솔직하게 적어 보세요.'),
  (16, 'their_heart', false, '마음에 큰 변화가 있어요', '그 사람의 마음이나 상황에 갑작스러운 변화가 생겼을 수 있어요. 반응이 평소와 다르더라도 당신 때문만은 아닐 수 있어요.', '상대가 이야기할 때까지 차분히 기다려 주세요.'),
  (16, 'their_heart', true, '변화를 미루고 있어요', '상대는 마음을 정해야 하는 상황을 피하고 싶어 할 수 있어요. 재촉하기보다 편안한 분위기를 만들어 주면 좋아요.', '부담 없는 일상 대화로 분위기를 풀어 주세요.'),
  (16, 'some', false, '관계가 크게 흔들려요', '썸에 예상치 못한 일이 생겨 분위기가 흔들릴 수 있어요. 이 흔들림을 통해 서로의 진짜 마음을 확인하게 될 수도 있어요.', '오해가 생기면 바로 솔직하게 이야기해 보세요.'),
  (16, 'some', true, '정리가 필요한 때예요', '썸에서 불편했던 부분을 계속 덮어두고 있을 수 있어요. 큰 문제가 되기 전에 천천히 이야기를 나누면 좋아요.', '작은 불편함부터 부드럽게 꺼내 보세요.'),
  (16, 'breakup', false, '다시 세우는 시간이에요', '이별이 갑작스럽게 느껴졌다면 마음이 많이 흔들렸을 거예요. 무너진 자리에서 나를 다시 단단하게 세워 갈 수 있어요.', '마음이 힘들 땐 믿을 수 있는 사람에게 도움을 요청해 보세요.'),
  (16, 'breakup', true, '천천히 정리해도 괜찮아요', '이별의 충격이 조금씩 가라앉고 있어요. 아직 정리하지 못한 감정이 있다면 서두르지 않고 하나씩 정리해 나가면 돼요.', '오늘 하나의 추억만 조용히 정리해 보세요.'),
  (16, 'confess', false, '예상치 못한 계기가 와요', '갑작스러운 상황이 고백의 계기가 될 수 있는 흐름이에요. 다만 감정이 격해진 순간보다는 마음이 진정된 뒤 전하는 게 좋아요.', '놀라운 일이 있었다면 하루 정도 지난 뒤 이야기해 보세요.'),
  (16, 'confess', true, '지금은 쉬어 가도 좋아요', '주변 상황이 어수선해 고백할 여유가 없을 수 있어요. 상황이 정리된 뒤에 전하면 마음이 더 잘 닿아요.', '지금은 내 일상을 먼저 정리해 보세요.'),
  (17, 'crush', false, '희망을 품어도 좋아요', '짝사랑에 희망적인 기운이 비추고 있어요. 순수한 마음으로 그 사람을 좋아하는 당신의 모습이 상대에게도 좋게 비칠 수 있어요.', '그 사람에게 진심 어린 칭찬을 한마디 건네 보세요.'),
  (17, 'crush', true, '작은 희망부터 다시요', '짝사랑이 이뤄지지 않을 것 같아 마음이 지쳐 있을 수 있어요. 큰 결과 대신 오늘의 작은 즐거움에 집중하면 마음이 회복돼요.', '그 사람과 나눈 즐거운 대화 하나를 떠올려 보세요.'),
  (17, 'their_heart', false, '좋은 기대를 품고 있어요', '그 사람은 당신과의 관계에 대해 밝고 희망적인 기대를 품고 있는 것 같아요. 당신을 보면 기분이 좋아진다고 느낄 수 있어요.', '상대에게 밝은 에너지를 나눠 주세요.'),
  (17, 'their_heart', true, '자신이 없어 보여요', '상대는 당신에게 호감이 있어도 스스로에 대한 자신감이 부족해 다가오지 못하고 있을 수 있어요. 따뜻한 격려가 도움이 돼요.', '상대의 좋은 점을 구체적으로 칭찬해 주세요.'),
  (17, 'some', false, '밝은 미래가 보여요', '썸이 희망적인 방향으로 흘러가고 있어요. 서로에게 좋은 기대를 품고 있다면 관계가 자연스럽게 피어날 수 있어요.', '함께 하고 싶은 일을 이야기 나눠 보세요.'),
  (17, 'some', true, '기대가 흐려졌어요', '썸이 기대만큼 진전되지 않아 실망하고 있을 수 있어요. 아직 끝난 게 아니니 조금 더 지켜봐도 괜찮아요.', '기대를 잠시 내려놓고 편하게 대해 보세요.'),
  (17, 'breakup', false, '마음이 회복되고 있어요', '이별의 아픔이 조금씩 아물며 마음에 희망이 돌아오고 있어요. 다시 사랑할 수 있다는 믿음이 새 인연을 부르는 힘이 돼요.', '앞으로의 나를 위한 작은 소원을 하나 적어 보세요.'),
  (17, 'breakup', true, '빛이 다시 와요', '지금은 앞이 잘 보이지 않아 막막할 수 있어요. 하지만 흐린 날이 지나면 별은 다시 보이니, 오늘은 나를 쉬게 해 주세요.', '좋아하는 음악을 들으며 푹 쉬어 보세요.'),
  (17, 'confess', false, '희망을 담아 전해요', '순수한 진심을 전하기 좋은 흐름이에요. 꾸밈없는 마음은 상대에게 따뜻하게 전해질 수 있어요.', '그 사람 덕분에 좋았던 순간을 함께 이야기해 보세요.'),
  (17, 'confess', true, '자신감을 먼저 채워요', '고백하고 싶지만 ''내가 될까?'' 하는 마음이 앞서 있을 수 있어요. 나를 믿는 마음이 생기면 그때 전해도 늦지 않아요.', '나를 응원하는 말을 거울 앞에서 해 보세요.'),
  (18, 'crush', false, '상상이 커지고 있어요', '그 사람의 마음을 알 수 없어 혼자 상상하며 불안해하고 있을 수 있어요. 확실하지 않은 것에 마음을 너무 쓰지 않아도 괜찮아요.', '추측 대신 실제 대화를 한 번 더 나눠 보세요.'),
  (18, 'crush', true, '마음이 선명해져요', '흐릿했던 그 사람의 마음이나 내 감정이 조금씩 분명해지고 있어요. 오해가 풀리면서 관계가 한결 편해질 수 있어요.', '궁금했던 걸 가볍게 물어보세요.'),
  (18, 'their_heart', false, '마음이 아직 흐릿해요', '그 사람도 당신에 대한 마음을 스스로 정확히 모르고 있을 수 있어요. 지금 보이는 반응만으로 판단하지 않는 게 좋아요.', '상대의 마음을 재촉하지 말고 지켜봐 주세요.'),
  (18, 'their_heart', true, '진심이 드러나고 있어요', '상대의 진짜 마음이 조금씩 드러나고 있어요. 그동안 헷갈렸던 행동의 이유를 알게 될 수 있어요.', '상대가 보내는 신호를 차분히 살펴보세요.'),
  (18, 'some', false, '애매한 안개 속이에요', '썸이 어디로 가는지 알 수 없어 불안할 수 있어요. 혼자 해석하기보다 서로의 마음을 조금씩 확인하는 게 도움이 돼요.', '오해가 생기면 바로 솔직하게 물어보세요.'),
  (18, 'some', true, '관계가 분명해져요', '애매했던 썸의 분위기가 걷히고 관계가 선명해지는 흐름이에요. 서로의 마음을 확인하기 좋은 때예요.', '지금 느끼는 마음을 솔직하게 나눠 보세요.'),
  (18, 'breakup', false, '불안한 마음을 다독여요', '이별 뒤 이런저런 생각과 불안이 밤마다 커질 수 있어요. 불확실한 상상보다 지금 내 마음을 돌보는 것이 먼저예요.', '잠들기 전 휴대폰 대신 따뜻한 차를 마셔 보세요.'),
  (18, 'breakup', true, '진실이 보이기 시작해요', '지난 관계에 대해 몰랐던 부분이 보이며 마음이 정리되기 시작해요. 이 선명함이 앞으로 나아갈 힘이 돼요.', '정리된 생각을 짧게 기록해 두세요.'),
  (18, 'confess', false, '조금 더 확인해요', '지금은 상대의 마음이 잘 보이지 않는 때예요. 고백 전에 서로의 마음을 조금 더 확인하면 좋아요.', '상대가 나를 어떻게 생각하는지 친구에게 넌지시 물어보세요.'),
  (18, 'confess', true, '안개가 걷히고 있어요', '불확실했던 마음이 분명해지면서 고백할 용기가 생기는 흐름이에요. 마음이 정리됐다면 솔직하게 전해 봐도 좋아요.', '편안한 분위기에서 진심을 전해 보세요.'),
  (19, 'crush', false, '밝은 기운이 비춰요', '짝사랑에 밝고 따뜻한 기운이 가득해요. 당신의 환한 웃음과 솔직한 모습이 그 사람의 마음을 열 수 있어요.', '그 사람 앞에서 마음껏 웃어 보세요.'),
  (19, 'crush', true, '잠시 구름이 꼈어요', '기대했던 만큼 반응이 오지 않아 서운할 수 있어요. 해는 그대로 있으니 조금만 기다리면 다시 밝아질 수 있어요.', '기대를 조금 내려놓고 편하게 대해 보세요.'),
  (19, 'their_heart', false, '함께 있으면 즐거워해요', '그 사람은 당신과 있을 때 행복하고 즐겁다고 느끼는 것 같아요. 당신을 밝은 에너지를 주는 사람으로 여기고 있어요.', '함께 웃을 수 있는 즐거운 일을 계획해 보세요.'),
  (19, 'their_heart', true, '표현이 줄었을 뿐이에요', '상대는 요즘 피곤하거나 바빠 표현이 줄었을 수 있어요. 당신에 대한 마음이 사라진 건 아닐 가능성이 커요.', '상대에게 힘이 되는 응원의 말을 건네 보세요.'),
  (19, 'some', false, '행복한 썸이에요', '썸이 밝고 즐겁게 피어나고 있어요. 서로에게 솔직하고 편안한 지금, 관계가 연애로 이어지기 좋은 흐름이에요.', '햇살 좋은 날 함께 산책하자고 제안해 보세요.'),
  (19, 'some', true, '들뜸을 조금 가라앉혀요', '썸이 좋아서 너무 앞서 기대하고 있을 수 있어요. 기대를 조절하면 작은 순간들도 더 즐겁게 느껴져요.', '오늘의 즐거움에만 집중해 보세요.'),
  (19, 'breakup', false, '다시 웃을 수 있어요', '이별의 그늘을 지나 다시 밝게 웃을 수 있는 날이 다가오고 있어요. 행복한 일상을 되찾으면 새로운 인연도 자연스럽게 찾아와요.', '나를 웃게 만드는 일을 하나 해 보세요.'),
  (19, 'breakup', true, '행복은 다시 와요', '지금은 즐거운 일이 잘 느껴지지 않을 수 있어요. 구름은 지나가기 마련이니 오늘은 작은 즐거움 하나만 찾아보세요.', '맛있는 음식이나 좋아하는 영화로 기분을 달래 보세요.'),
  (19, 'confess', false, '지금 전하기 좋아요', '밝은 기운이 가득해 마음을 전하기 아주 좋은 흐름이에요. 솔직하고 환한 고백이 좋은 대답으로 돌아올 가능성이 커요.', '밝은 낮이나 즐거운 분위기에서 마음을 전해 보세요.'),
  (19, 'confess', true, '분위기를 조금 더 살펴요', '상대가 요즘 기운이 없거나 바쁠 수 있어요. 상대의 기분이 밝아진 날 전하면 더 좋은 반응을 기대할 수 있어요.', '상대의 컨디션이 좋은 날을 골라 보세요.'),
  (20, 'crush', false, '진짜 마음을 깨달아요', '그 사람에 대한 내 마음이 무엇인지 분명하게 깨닫게 되는 때예요. 이 깨달음이 행동할 용기를 줄 수 있어요.', '그 사람에게 하고 싶은 말을 정리해 보세요.'),
  (20, 'crush', true, '망설이다 놓치지 않게요', '다가가고 싶지만 결정을 계속 미루고 있을 수 있어요. 너무 오래 고민하기보다 작은 행동 하나를 시작해 보면 좋아요.', '오늘 그 사람에게 메시지 하나를 보내 보세요.'),
  (20, 'their_heart', false, '당신을 다시 보고 있어요', '그 사람은 당신의 새로운 면을 발견하고 관계를 다시 생각하고 있는 것 같아요. 예전과 다른 마음이 생기고 있을 수 있어요.', '상대에게 새로운 내 모습을 보여 주세요.'),
  (20, 'their_heart', true, '결정을 내리지 못해요', '상대는 당신에 대한 마음을 정하지 못하고 망설이고 있을 수 있어요. 재촉하기보다 편안하게 기다려 주는 게 좋아요.', '상대가 결정할 시간을 존중해 주세요.'),
  (20, 'some', false, '새로운 단계로 부름이 와요', '썸이 다음 단계로 나아가라는 신호를 받는 흐름이에요. 서로의 마음을 확인하고 관계를 새롭게 정의하기 좋은 때예요.', '관계에 대해 진지하게 이야기해 보세요.'),
  (20, 'some', true, '과거에 머물러 있어요', '예전 연애의 상처 때문에 썸에서 한 발짝 물러서고 있을 수 있어요. 지금의 사람은 예전과 다르다는 걸 기억해 주세요.', '과거의 경험과 지금의 관계를 따로 생각해 보세요.'),
  (20, 'breakup', false, '돌아보고 일어서요', '지난 관계를 돌아보며 배운 것을 안고 새롭게 출발하기 좋은 때예요. 재회든 새 인연이든, 깨달음을 얻은 지금의 나는 더 성숙한 선택을 할 수 있어요.', '지난 관계에서 배운 점을 한 줄로 정리해 보세요.'),
  (20, 'breakup', true, '나를 용서해 줘요', '이별에 대해 나를 계속 탓하고 있을 수 있어요. 나를 용서해야 과거에서 벗어나 새로운 인연을 맞을 수 있어요.', '"그때는 그게 최선이었어"라고 스스로에게 말해 주세요.'),
  (20, 'confess', false, '마음의 목소리를 따라요', '고백하라는 내 마음의 목소리가 분명하게 들리는 때예요. 그 목소리를 따르면 후회 없는 선택이 될 수 있어요.', '고백할 날을 정하고 마음을 준비해 보세요.'),
  (20, 'confess', true, '결정을 미루고 있어요', '고백할지 말지 고민만 길어지고 있을 수 있어요. 결과보다 내 마음을 전하는 데 의미를 두면 결정이 쉬워져요.', '고백하지 않으면 아쉬울지 스스로 물어보세요.'),
  (21, 'crush', false, '마음이 열매를 맺어요', '오래 품어 온 짝사랑이 좋은 결실을 맺을 수 있는 기운이에요. 지금까지 쌓아 온 마음과 노력이 빛을 볼 수 있어요.', '그 사람과 함께하는 시간을 소중히 즐겨 보세요.'),
  (21, 'crush', true, '마지막 한 걸음이 남았어요', '그 사람과 거의 가까워졌지만 마지막 한 걸음이 부족할 수 있어요. 조금만 더 용기를 내면 관계가 완성될 수 있어요.', '망설였던 말이나 행동을 하나 해 보세요.'),
  (21, 'their_heart', false, '당신과 함께여서 충만해요', '그 사람은 당신과 함께할 때 마음이 꽉 차고 행복하다고 느끼는 것 같아요. 당신을 특별한 사람으로 여기고 있을 수 있어요.', '상대에게 고마운 마음을 표현해 보세요.'),
  (21, 'their_heart', true, '아직 마음을 다 열지 않았어요', '상대는 당신에게 마음이 있지만 아직 완전히 열지는 못한 상태일 수 있어요. 조금 더 시간을 주면 마음을 보여줄 수 있어요.', '상대가 편하게 마음을 열 수 있도록 기다려 주세요.'),
  (21, 'some', false, '썸이 결실을 맺어요', '썸이 연애로 완성되기 좋은 흐름이에요. 서로의 마음이 충분히 무르익었다면 관계를 분명히 할 때예요.', '특별한 날을 정해 마음을 나눠 보세요.'),
  (21, 'some', true, '마무리가 남았어요', '썸이 거의 연애에 가까워졌지만 마지막 확인이 남아 있을 수 있어요. 서로의 마음을 분명하게 나누면 관계가 완성돼요.', '"우리 사귀는 거 어때?"처럼 분명하게 물어보세요.'),
  (21, 'breakup', false, '한 여정이 잘 마무리돼요', '지난 관계가 하나의 여정으로 잘 마무리되며 마음이 정리되는 흐름이에요. 끝이 아닌 완성으로 받아들이면 새로운 여정이 시작될 수 있어요.', '지난 관계에 고마웠던 점을 마음속으로 전해 보세요.'),
  (21, 'breakup', true, '정리가 조금 남았어요', '이별을 거의 받아들였지만 아직 마음 한구석에 남은 감정이 있을 수 있어요. 마지막 정리까지 천천히 해 나가면 돼요.', '남은 감정을 편지로 써 보고 간직하거나 버려 보세요.'),
  (21, 'confess', false, '지금이 좋은 때예요', '마음이 충분히 무르익어 고백하기 아주 좋은 흐름이에요. 진심을 전하면 관계가 아름답게 완성될 수 있어요.', '의미 있는 장소에서 마음을 전해 보세요.'),
  (21, 'confess', true, '조금만 더 준비해요', '고백할 준비가 거의 됐지만 아직 마음이나 상황이 조금 덜 정리됐을 수 있어요. 마지막 준비를 마치면 더 자신 있게 전할 수 있어요.', '고백 전 마음을 정리할 시간을 하루만 더 가져 보세요.'),
  (22, 'crush', false, '마음에 불꽃이 튀었어요', '그 사람을 향한 설렘이 막 피어오르는 흐름이에요. 이 열정은 다가갈 용기가 되어 줄 수 있어요.', '설레는 마음이 식기 전에 먼저 인사를 건네 보세요.'),
  (22, 'crush', true, '불씨를 지켜 봐요', '좋아하는 마음은 있지만 행동으로 옮기기가 망설여질 수 있어요. 서두르지 않아도 되니, 마음의 불씨를 소중히 지켜 주세요.', '그 사람과 나눌 수 있는 작은 대화거리를 하나 준비해 보세요.'),
  (22, 'their_heart', false, '새로운 설렘을 느껴요', '그 사람은 당신에게서 새로운 설렘을 느끼기 시작한 것 같아요. 함께 있으면 왠지 기운이 난다고 생각할 수 있어요.', '상대가 관심 보이는 일에 함께 신나 해 주세요.'),
  (22, 'their_heart', true, '표현할 타이밍을 몰라요', '상대도 마음은 있지만 어떻게 표현해야 할지 몰라 망설이고 있을 수 있어요. 당신이 먼저 편한 분위기를 만들어 주면 좋아요.', '가볍게 먼저 연락해서 대화를 열어 주세요.'),
  (22, 'some', false, '썸에 불이 붙었어요', '썸이 막 시작되며 서로를 향한 열정이 커지는 흐름이에요. 지금의 설렘을 즐기며 함께하는 시간을 늘려 가면 좋아요.', '둘이 함께 해 볼 새로운 활동을 제안해 보세요.'),
  (22, 'some', true, '열기가 잠시 식었어요', '처음의 설렘이 조금 식은 듯 느껴질 수 있어요. 새로운 자극이 생기면 다시 불이 붙을 수 있어요.', '평소와 다른 장소에서 만나 보세요.'),
  (22, 'breakup', false, '새로운 열정이 생겨요', '이별 뒤 마음속에 새로운 열정이 피어나는 흐름이에요. 그 에너지를 나를 위한 일에 쓰면 새로운 인연도 자연스럽게 따라와요.', '새로운 취미나 운동을 시작해 보세요.'),
  (22, 'breakup', true, '의욕이 잠시 떨어졌어요', '이별 후 아무것도 하기 싫은 마음이 들 수 있어요. 지금은 큰 결심보다 작은 일 하나를 해내는 것으로 충분해요.', '오늘은 방 정리나 산책처럼 작은 일 하나만 해 보세요.'),
  (22, 'confess', false, '설렘을 그대로 전해요', '마음이 뜨거운 지금, 솔직하게 전하기 좋은 흐름이에요. 설레는 마음 그대로를 표현하면 상대에게도 그 열기가 전해질 수 있어요.', '"너 생각하면 설레"처럼 솔직한 표현을 해 보세요.'),
  (22, 'confess', true, '불씨를 조금 더 키워요', '아직 마음이 충분히 무르익지 않았거나 계기가 부족할 수 있어요. 함께하는 시간을 조금 더 쌓은 뒤 전하면 좋아요.', '고백 전 둘만의 추억을 하나 더 만들어 보세요.'),
  (23, 'crush', false, '다가갈 계획을 세워요', '짝사랑을 어떻게 이어갈지 차분히 계획하기 좋은 때예요. 바라보기만 하던 마음에서 한 걸음 나아갈 방법이 보여요.', '그 사람과 가까워질 수 있는 기회를 하나 정해 보세요.'),
  (23, 'crush', true, '지금 자리에 머물러 있어요', '다가가고 싶지만 지금의 편안한 거리를 깨기 두려울 수 있어요. 아주 작은 변화부터 시작해 보면 좋아요.', '평소보다 한마디만 더 대화를 이어가 보세요.'),
  (23, 'their_heart', false, '앞날을 생각하고 있어요', '그 사람은 당신과의 관계를 앞으로 어떻게 이어갈지 생각하는 것 같아요. 진지하게 미래를 그려 보고 있을 수 있어요.', '함께 하고 싶은 일을 이야기 나눠 보세요.'),
  (23, 'their_heart', true, '결정을 미루고 있어요', '상대는 관계를 진전시키고 싶은 마음과 망설임 사이에서 고민하고 있을 수 있어요. 부담 없는 기회를 만들어 주면 좋아요.', '가볍게 만날 수 있는 약속을 먼저 제안해 보세요.'),
  (23, 'some', false, '다음 단계를 고민해요', '썸이 다음 단계로 나아갈지 고민하는 시점이에요. 서로의 마음을 확인하면 관계의 방향이 분명해질 수 있어요.', '함께하는 미래 계획을 가볍게 이야기해 보세요.'),
  (23, 'some', true, '제자리걸음이에요', '썸이 편안하지만 진전이 없어 답답할 수 있어요. 누군가 먼저 한 걸음 내디뎌야 흐름이 바뀌어요.', '이번에는 내가 먼저 다음 약속을 잡아 보세요.'),
  (23, 'breakup', false, '새 길을 그려 봐요', '이별 뒤 앞으로의 삶을 새롭게 계획하기 좋은 때예요. 넓은 세상을 바라보면 지난 관계 밖에도 많은 가능성이 있다는 걸 알게 돼요.', '올해 꼭 해 보고 싶은 일을 세 가지 적어 보세요.'),
  (23, 'breakup', true, '떠나기 두려워요', '익숙했던 관계를 떠나보내기 두려워 마음이 머물러 있을 수 있어요. 새로운 길도 충분히 따뜻할 수 있다는 걸 기억해 주세요.', '가 보지 않았던 동네를 한번 걸어 보세요.'),
  (23, 'confess', false, '고백을 계획할 때예요', '마음을 전할 방법과 타이밍을 차분히 계획하기 좋은 흐름이에요. 준비된 고백은 자신감을 더해 줘요.', '고백할 장소와 날짜를 미리 정해 보세요.'),
  (23, 'confess', true, '망설임을 덜어 봐요', '고백하고 싶지만 지금 관계가 깨질까 두려울 수 있어요. 걱정을 하나씩 짚어 보면 생각보다 용기가 날 수 있어요.', '최악과 최선의 결과를 함께 적어 보세요.'),
  (24, 'crush', false, '좋은 소식이 다가와요', '그동안 쌓아 온 마음과 노력이 조금씩 결실로 돌아오는 흐름이에요. 그 사람과의 관계가 넓어질 기회가 생길 수 있어요.', '그 사람과 함께할 수 있는 새로운 계기를 찾아보세요.'),
  (24, 'crush', true, '반응이 늦어지고 있어요', '기대했던 반응이 늦어져 답답할 수 있어요. 상대의 속도가 다를 뿐이니 조금 더 여유를 가져 보면 좋아요.', '기다리는 동안 내 일상을 즐겁게 채워 보세요.'),
  (24, 'their_heart', false, '관계를 넓혀 가고 싶어 해요', '그 사람은 당신과의 관계를 더 넓고 깊게 이어가고 싶어 하는 것 같아요. 함께할 미래를 기대하고 있을 수 있어요.', '상대가 꿈꾸는 일에 관심을 보여 주세요.'),
  (24, 'their_heart', true, '다른 곳에 마음이 바빠요', '상대는 지금 다른 일에 신경 쓰느라 관계에 마음을 쏟기 어려울 수 있어요. 당신에 대한 마음과는 별개일 수 있어요.', '상대가 여유로워질 때까지 조금 기다려 주세요.'),
  (24, 'some', false, '썸이 넓어지고 있어요', '썸이 순조롭게 진행되며 더 큰 관계로 자라나는 흐름이에요. 서로의 일상에 조금씩 더 들어가고 있어요.', '서로의 친구들과 함께 만나 보는 것도 좋아요.'),
  (24, 'some', true, '진전이 더뎌요', '썸이 기대만큼 빨리 진전되지 않아 아쉬울 수 있어요. 서두르기보다 지금의 관계를 즐기면 흐름이 자연스럽게 이어져요.', '결과보다 함께하는 순간을 즐겨 보세요.'),
  (24, 'breakup', false, '더 넓은 세상이 보여요', '지난 관계 너머로 더 넓은 세상과 새로운 가능성이 보이기 시작해요. 마음이 정리되면 새로운 인연이 다가올 수 있어요.', '새로운 사람들을 만나는 모임에 나가 보세요.'),
  (24, 'breakup', true, '회복이 조금 더뎌요', '생각보다 마음이 빨리 정리되지 않아 답답할 수 있어요. 회복에는 각자의 속도가 있으니 나를 재촉하지 않아도 돼요.', '오늘 나를 위해 작은 칭찬을 해 주세요.'),
  (24, 'confess', false, '타이밍이 무르익고 있어요', '고백을 향한 준비가 잘 되어 가고 있는 흐름이에요. 조금 더 기다리면 좋은 기회가 찾아올 수 있어요.', '상대와 함께하는 행사나 약속이 있다면 그때를 눈여겨보세요.'),
  (24, 'confess', true, '조금 늦춰도 괜찮아요', '생각했던 고백 계획이 틀어질 수 있어요. 계획이 바뀌어도 마음은 그대로니, 더 좋은 기회를 기다려 보면 좋아요.', '고백 계획을 한 가지 더 준비해 두세요.'),
  (25, 'crush', false, '즐거운 자리가 생겨요', '그 사람과 즐거운 자리에서 가까워질 기회가 생길 수 있어요. 편안하고 행복한 분위기 속에서 관계가 자연스럽게 자라요.', '모임이나 파티에 그 사람을 초대해 보세요.'),
  (25, 'crush', true, '분위기가 어수선해요', '주변 상황이 어수선해서 그 사람에게 다가가기 어려울 수 있어요. 상황이 안정될 때까지 조금 기다려도 괜찮아요.', '지금은 편한 인사 정도로 관계를 이어가 보세요.'),
  (25, 'their_heart', false, '당신과 있으면 편안해해요', '그 사람은 당신과 있을 때 집처럼 편안하고 즐겁다고 느끼는 것 같아요. 함께하는 시간을 소중히 여기고 있어요.', '편안한 분위기에서 함께 시간을 보내 보세요.'),
  (25, 'their_heart', true, '주변 일로 마음이 바빠요', '상대는 지금 주변 일이 어수선해 관계에 집중하기 어려울 수 있어요. 당신을 향한 마음이 식은 건 아닐 수 있어요.', '상대에게 힘이 되는 짧은 응원을 보내 보세요.'),
  (25, 'some', false, '썸이 안정적이에요', '썸이 편안하고 안정적으로 자리 잡아 가고 있어요. 함께 축하할 일이 생기며 관계가 한 단계 깊어질 수 있어요.', '작은 기념일을 만들어 함께 축하해 보세요.'),
  (25, 'some', true, '작은 다툼을 풀어요', '썸 중에 작은 오해나 갈등이 생겨 분위기가 어색할 수 있어요. 빨리 풀면 오히려 관계가 더 단단해질 수 있어요.', '먼저 가볍게 화해의 말을 건네 보세요.'),
  (25, 'breakup', false, '내 자리를 다시 꾸며요', '이별 뒤 나만의 공간과 일상을 다시 편안하게 꾸미기 좋은 때예요. 안정된 일상이 마음을 회복시켜 줘요.', '방에 꽃이나 좋아하는 소품을 하나 놓아 보세요.'),
  (25, 'breakup', true, '허전함이 커요', '함께하던 일상이 사라져 허전함이 크게 느껴질 수 있어요. 가까운 사람들과 함께하는 시간이 마음을 채워 줄 수 있어요.', '가족이나 친구와 함께 식사해 보세요.'),
  (25, 'confess', false, '축하할 일이 생겨요', '고백이 좋은 결과로 이어져 함께 기뻐할 수 있는 흐름이에요. 편안하고 즐거운 분위기에서 마음을 전하면 좋아요.', '기분 좋은 날, 즐거운 자리에서 마음을 전해 보세요.'),
  (25, 'confess', true, '분위기를 먼저 살펴요', '지금은 주변 상황이 어수선해 고백하기 어려울 수 있어요. 분위기가 차분해진 뒤에 전하면 더 잘 닿아요.', '상대의 상황이 안정됐는지 먼저 살펴보세요.'),
  (26, 'crush', false, '경쟁자가 있을 수 있어요', '그 사람에게 관심 있는 사람이 주변에 더 있을 수 있어요. 남과 비교하기보다 나만의 매력을 보여 주는 게 좋아요.', '나만 할 수 있는 이야기로 그 사람과 대화해 보세요.'),
  (26, 'crush', true, '경쟁보다 나다움이에요', '누군가와 경쟁하는 듯한 피곤함이 줄어드는 흐름이에요. 신경전 대신 편안한 나로 다가가면 관계가 자연스러워져요.', '다른 사람은 신경 쓰지 말고 내 페이스대로 다가가 보세요.'),
  (26, 'their_heart', false, '당신에게 자극을 받아요', '그 사람은 당신과 티격태격하며 오히려 재미와 자극을 느끼고 있을 수 있어요. 장난스러운 신경전이 호감의 표현일 수 있어요.', '가벼운 장난에는 웃으며 받아쳐 주세요.'),
  (26, 'their_heart', true, '갈등을 피하고 싶어 해요', '상대는 부딪히는 게 싫어 하고 싶은 말을 참고 있을 수 있어요. 편하게 말할 수 있는 분위기를 만들어 주면 좋아요.', '"편하게 말해도 돼"라고 먼저 말해 주세요.'),
  (26, 'some', false, '티격태격하는 썸이에요', '썸에서 의견 차이나 작은 다툼이 생길 수 있어요. 서로 다른 점을 알아가는 과정이니 너무 걱정하지 않아도 괜찮아요.', '다툰 뒤에는 먼저 웃으며 화해해 보세요.'),
  (26, 'some', true, '말하지 않은 불만이 있어요', '겉으로는 평화로워 보여도 서로 하고 싶은 말을 참고 있을 수 있어요. 작은 불만은 쌓이기 전에 나누면 좋아요.', '"요즘 불편한 거 있어?"라고 가볍게 물어보세요.'),
  (26, 'breakup', false, '다툼의 이유를 돌아봐요', '이별 전 자주 부딪혔던 이유를 차분히 돌아보기 좋은 때예요. 이해가 생기면 원망도 미련도 조금씩 줄어들어요.', '우리가 자주 다퉜던 이유를 하나 적어 보세요.'),
  (26, 'breakup', true, '갈등이 가라앉고 있어요', '이별을 둘러싼 갈등이나 감정이 조금씩 가라앉고 있어요. 마음이 차분해지면 앞으로 어떻게 할지 더 분명하게 보여요.', '감정이 차분해진 지금, 내 마음을 정리해 보세요.'),
  (26, 'confess', false, '경쟁보다 진심이에요', '누군가 먼저 고백할까 봐 조급할 수 있어요. 서두르기보다 내 진심을 준비하는 게 더 중요해요.', '다른 사람과 비교하지 말고 내 마음을 전하는 데 집중해 보세요.'),
  (26, 'confess', true, '갈등부터 풀어요', '최근에 작은 다툼이 있었다면 고백보다 화해가 먼저예요. 관계가 편안해진 뒤 전하면 더 잘 받아들여질 수 있어요.', '먼저 화해하고 편안한 분위기를 만들어 보세요.'),
  (27, 'crush', false, '당신이 빛나는 때예요', '당신의 매력과 노력이 주변에서 인정받는 때예요. 그 사람도 당신의 빛나는 모습을 눈여겨보고 있을 수 있어요.', '자신 있는 분야에서 당당한 모습을 보여 주세요.'),
  (27, 'crush', true, '나를 먼저 인정해요', '그 사람에게 잘 보이고 싶은 마음에 자신감이 흔들릴 수 있어요. 남의 시선보다 내가 나를 믿어 주는 게 중요해요.', '오늘 잘한 일 하나를 스스로 칭찬해 주세요.'),
  (27, 'their_heart', false, '당신을 멋지다고 생각해요', '그 사람은 당신을 자랑스럽고 멋진 사람으로 여기는 것 같아요. 당신의 성취나 모습을 좋게 보고 있을 수 있어요.', '상대가 칭찬하면 기쁘게 받아 주세요.'),
  (27, 'their_heart', true, '자신 없어 하고 있어요', '상대는 당신 앞에서 자신감이 부족해 다가오지 못하고 있을 수 있어요. 상대의 좋은 점을 알아봐 주면 마음이 열려요.', '상대의 장점을 구체적으로 칭찬해 주세요.'),
  (27, 'some', false, '썸이 순조롭게 진행돼요', '썸이 잘 풀리며 주변에서도 잘 어울린다는 말을 들을 수 있는 흐름이에요. 자신감을 갖고 관계를 이어가면 좋아요.', '자신 있게 다음 데이트를 제안해 보세요.'),
  (27, 'some', true, '남의 시선을 신경 써요', '썸을 주변에 어떻게 보일지 신경 쓰느라 마음이 불편할 수 있어요. 두 사람의 마음이 가장 중요하다는 걸 기억해 주세요.', '주변 의견보다 내 느낌을 믿어 보세요.'),
  (27, 'breakup', false, '다시 자신감을 찾아요', '이별 뒤 나의 가치를 다시 발견하고 자신감을 되찾는 흐름이에요. 당당한 모습은 새로운 인연을 끌어당기는 힘이 돼요.', '최근 이룬 작은 성과를 떠올려 보세요.'),
  (27, 'breakup', true, '나의 가치를 기억해요', '이별 때문에 스스로를 작게 느끼고 있을 수 있어요. 관계가 끝났다고 나의 가치가 줄어드는 건 아니에요.', '나를 아끼는 사람들의 말을 떠올려 보세요.'),
  (27, 'confess', false, '자신 있게 전해요', '자신감이 가득한 지금, 당당하게 마음을 전하기 좋은 흐름이에요. 당신의 자신 있는 모습이 상대에게 믿음을 줄 수 있어요.', '기분 좋은 일이 있던 날, 그 기운을 빌려 마음을 전해 보세요.'),
  (27, 'confess', true, '자신감을 먼저 채워요', '고백하고 싶지만 스스로가 부족하게 느껴질 수 있어요. 나를 먼저 인정해 주면 고백할 용기도 자연스럽게 생겨요.', '고백 전 나의 좋은 점을 세 가지 적어 보세요.'),
  (28, 'crush', false, '내 마음을 지켜요', '주변의 말이나 상황에 흔들리지 않고 내 마음을 지켜 나가는 흐름이에요. 그 사람을 좋아하는 마음에 당당해져도 괜찮아요.', '주변 말보다 내 마음을 믿어 보세요.'),
  (28, 'crush', true, '너무 지쳐 있어요', '짝사랑을 이어가느라 마음이 많이 지쳐 있을 수 있어요. 잠시 쉬어 가도 마음은 사라지지 않아요.', '오늘은 그 사람 생각을 내려놓고 푹 쉬어 보세요.'),
  (28, 'their_heart', false, '당신을 지켜 주고 싶어 해요', '그 사람은 당신을 지켜 주고 싶은 마음이나, 자기 마음을 굳게 지키는 마음이 있는 것 같아요. 쉽게 흔들리지 않는 진심일 수 있어요.', '상대의 든든한 모습을 알아봐 주세요.'),
  (28, 'their_heart', true, '경계하고 있어요', '상대는 상처받을까 봐 마음의 벽을 세우고 있을 수 있어요. 천천히 믿음을 주면 벽이 조금씩 낮아져요.', '상대가 안심할 수 있도록 꾸준히 다정하게 대해 주세요.'),
  (28, 'some', false, '관계를 지켜 내요', '썸을 방해하는 일이 있어도 둘의 관계를 잘 지켜 낼 수 있는 흐름이에요. 서로를 믿는 마음이 힘이 돼요.', '주변 말에 흔들리지 말고 상대를 믿어 보세요.'),
  (28, 'some', true, '방어적으로 굴고 있어요', '상처받기 싫어 서로 방어적으로 대하고 있을 수 있어요. 한 사람이 먼저 마음을 열면 분위기가 달라져요.', '먼저 솔직한 마음 하나를 꺼내 보세요.'),
  (28, 'breakup', false, '나를 지켜 내요', '이별 뒤 흔들리는 마음을 굳게 지켜 내는 흐름이에요. 나를 아프게 했던 관계로 쉽게 돌아가지 않는 것도 용기예요.', '나를 지키기 위한 나만의 기준을 정해 보세요.'),
  (28, 'breakup', true, '혼자 버티지 않아도 돼요', '아픔을 혼자 버티느라 지쳐 있을 수 있어요. 주변에 기대는 것도 나를 지키는 방법이에요.', '힘들 때 연락할 수 있는 사람에게 연락해 보세요.'),
  (28, 'confess', false, '당당하게 전해요', '주변 상황에 흔들리지 않고 내 마음을 당당하게 전하기 좋은 흐름이에요. 당신의 진심에 자신을 가져도 좋아요.', '다른 사람의 의견보다 내 마음을 기준으로 정해 보세요.'),
  (28, 'confess', true, '마음의 준비를 더 해요', '고백 앞에서 마음이 지치거나 방어적이 되어 있을 수 있어요. 마음이 편안해진 뒤 전하면 더 자연스러워요.', '고백 전 스트레스를 풀 수 있는 시간을 가져 보세요.'),
  (29, 'crush', false, '연락이 활발해져요', '그 사람과 연락이 빠르게 오가며 가까워질 수 있는 흐름이에요. 반가운 소식이나 메시지가 올 수 있어요.', '그 사람에게 반가운 메시지를 먼저 보내 보세요.'),
  (29, 'crush', true, '답장이 늦어질 수 있어요', '연락이 기대만큼 빠르지 않아 마음이 조급해질 수 있어요. 답장의 속도가 마음의 크기는 아니니 너무 걱정하지 않아도 돼요.', '답장을 기다리는 동안 다른 일에 집중해 보세요.'),
  (29, 'their_heart', false, '빨리 가까워지고 싶어 해요', '그 사람은 당신과 빠르게 가까워지고 싶어 하는 것 같아요. 연락이나 만남이 자주 이어지는 건 그 마음의 표현일 수 있어요.', '상대의 연락에 반갑게 반응해 주세요.'),
  (29, 'their_heart', true, '상황이 바빠요', '상대는 지금 바쁜 일정 때문에 연락이 뜸할 수 있어요. 마음이 없어서가 아니라 여유가 없는 것일 수 있어요.', '부담 없는 짧은 메시지로 안부를 전해 보세요.'),
  (29, 'some', false, '썸이 빠르게 진전돼요', '썸이 속도감 있게 진행되며 관계가 빠르게 가까워지는 흐름이에요. 지금의 설렘을 즐기며 자연스럽게 따라가 보세요.', '생각난 김에 바로 만남을 제안해 보세요.'),
  (29, 'some', true, '타이밍이 엇갈려요', '연락이나 만남의 타이밍이 계속 엇갈려 답답할 수 있어요. 서로의 일정을 맞추는 대화가 도움이 돼요.', '서로 편한 연락 시간을 정해 보세요.'),
  (29, 'breakup', false, '상황이 빠르게 바뀌어요', '이별 뒤 상황이 빠르게 정리되거나 새로운 소식이 들어올 수 있어요. 흐름에 휩쓸리기보다 내 마음을 기준으로 판단하면 좋아요.', '새로운 소식이 오면 하루 생각해 본 뒤 답해 보세요.'),
  (29, 'breakup', true, '서두르지 않아도 돼요', '빨리 괜찮아지고 싶어 조급할 수 있어요. 마음의 회복에는 시간이 필요하니 천천히 가도 괜찮아요.', '오늘 하루를 무사히 보낸 나를 칭찬해 주세요.'),
  (29, 'confess', false, '타이밍이 빠르게 와요', '고백할 기회가 생각보다 빨리 찾아올 수 있는 흐름이에요. 마음의 준비가 됐다면 기회를 놓치지 말아요.', '고백할 말을 미리 준비해 두세요.'),
  (29, 'confess', true, '조금 기다려 봐요', '지금은 상황이 엇갈려 고백 타이밍이 맞지 않을 수 있어요. 서두르기보다 흐름이 맞춰질 때를 기다리면 좋아요.', '상대와 여유 있게 만날 수 있는 날을 찾아보세요.'),
  (30, 'crush', false, '조금만 더 힘내요', '오래 이어 온 짝사랑에 지쳤지만, 거의 마지막 고비에 와 있을 수 있어요. 조금만 더 마음을 지켜 보면 변화가 생길 수 있어요.', '지친 마음을 위해 나에게 작은 보상을 해 주세요.'),
  (30, 'crush', true, '쉬어 가도 괜찮아요', '짝사랑에 너무 많은 에너지를 써서 지쳐 있을 수 있어요. 잠시 쉬어도 마음은 사라지지 않으니 나를 먼저 돌봐 주세요.', '오늘은 그 사람 생각 없이 푹 쉬어 보세요.'),
  (30, 'their_heart', false, '조심스럽게 지켜보고 있어요', '그 사람은 예전의 상처 때문에 마음을 쉽게 열지 못하고 조심스럽게 지켜보는 것 같아요. 당신을 믿어도 될지 확인하고 있을 수 있어요.', '꾸준하고 한결같은 모습으로 믿음을 주세요.'),
  (30, 'their_heart', true, '마음이 지쳐 있어요', '상대는 지금 여러 일로 지쳐 관계에 마음 쓸 여유가 없을 수 있어요. 재촉보다는 따뜻한 응원이 필요해요.', '상대에게 힘내라는 짧은 메시지를 보내 보세요.'),
  (30, 'some', false, '고비를 넘기면 돼요', '썸이 오래 이어지며 지칠 수 있지만, 고비를 넘기면 관계가 분명해질 수 있어요. 조금만 더 인내심을 가져 보세요.', '서로의 마음을 확인하는 대화를 준비해 보세요.'),
  (30, 'some', true, '지쳐서 의심이 생겨요', '썸이 길어지며 상대의 마음을 의심하게 될 수 있어요. 혼자 의심하기보다 솔직하게 물어보면 마음이 편해져요.', '궁금한 마음을 솔직하게 털어놓아 보세요.'),
  (30, 'breakup', false, '끝까지 나를 지켜요', '이별의 아픔 속에서도 마지막까지 나를 지켜 내는 흐름이에요. 이 고비를 넘기면 마음이 한결 가벼워질 수 있어요.', '힘든 날에는 무리하지 말고 나를 쉬게 해 주세요.'),
  (30, 'breakup', true, '상처를 돌봐 줘요', '지난 상처 때문에 새로운 사람을 믿기 어려울 수 있어요. 상처가 아물 시간을 충분히 주는 것이 먼저예요.', '나를 아프게 했던 기억보다 나를 웃게 했던 기억을 떠올려 보세요.'),
  (30, 'confess', false, '신중하게 준비해요', '고백 전 마지막 고비를 넘기는 중이에요. 신중하게 준비하면 좋은 결과로 이어질 수 있어요.', '고백 전에 상대의 마음을 한 번 더 살펴보세요.'),
  (30, 'confess', true, '지금은 쉬어 가요', '지쳐 있는 상태에서의 고백은 마음이 충분히 전해지지 않을 수 있어요. 마음과 몸을 먼저 회복한 뒤 전하면 좋아요.', '고백보다 나를 먼저 돌보는 시간을 가져 보세요.'),
  (31, 'crush', false, '마음이 너무 무거워요', '짝사랑을 혼자 짊어지느라 마음이 무겁게 느껴질 수 있어요. 모든 걸 혼자 해결하려 하지 않아도 괜찮아요.', '믿을 수 있는 친구에게 마음을 털어놓아 보세요.'),
  (31, 'crush', true, '짐을 조금 내려놓아요', '짝사랑에 대한 부담이 조금씩 가벼워지는 흐름이에요. 결과에 대한 걱정을 내려놓으면 더 편하게 다가갈 수 있어요.', '결과보다 지금 내 마음에 집중해 보세요.'),
  (31, 'their_heart', false, '여유가 없어 보여요', '그 사람은 지금 책임져야 할 일이 많아 연애에 마음 쓸 여유가 부족할 수 있어요. 당신에 대한 마음과는 별개일 수 있어요.', '상대에게 부담 주지 않는 선에서 응원해 주세요.'),
  (31, 'their_heart', true, '부담을 덜고 싶어 해요', '상대는 무거운 일들을 정리하고 조금 가벼워지고 싶어 하는 것 같아요. 함께 있으면 편안한 사람이 되어 주면 좋아요.', '상대가 쉴 수 있는 편안한 시간을 함께 보내 보세요.'),
  (31, 'some', false, '썸이 버겁게 느껴져요', '썸을 이어가느라 한쪽이 너무 많은 부담을 지고 있을 수 있어요. 서로 노력을 나누면 관계가 더 편안해져요.', '내가 너무 많이 애쓰고 있지 않은지 살펴보세요.'),
  (31, 'some', true, '부담이 줄어들어요', '썸에서 느끼던 부담이 줄어들며 관계가 편안해지는 흐름이에요. 가볍게 즐길 때 관계가 더 자연스럽게 자라요.', '부담 없이 즐길 수 있는 데이트를 해 보세요.'),
  (31, 'breakup', false, '혼자 다 짊어지지 마요', '이별의 아픔과 책임을 혼자 다 짊어지고 있을 수 있어요. 무거운 마음을 조금씩 나누면 훨씬 가벼워져요.', '힘든 마음을 가까운 사람과 나눠 보세요.'),
  (31, 'breakup', true, '짐을 내려놓을 때예요', '지난 관계에서 짊어졌던 짐을 내려놓을 수 있는 흐름이에요. 가벼워진 마음으로 새로운 시작을 준비할 수 있어요.', '지난 관계에서 내려놓고 싶은 것을 적어 보세요.'),
  (31, 'confess', false, '부담을 덜고 전해요', '고백에 너무 큰 무게를 싣고 있을 수 있어요. 마음을 전하는 것 자체에 의미를 두면 부담이 줄어들어요.', '고백을 ''마음을 나누는 대화''로 생각해 보세요.'),
  (31, 'confess', true, '가벼운 마음으로 전해요', '부담이 줄어든 지금, 편안하게 마음을 전하기 좋은 흐름이에요. 결과에 매달리지 않으면 고백도 자연스러워져요.', '편안한 분위기에서 가볍게 마음을 전해 보세요.'),
  (32, 'crush', false, '호기심이 마음을 열어요', '그 사람에 대한 호기심이 커지며 다가가고 싶은 마음이 생기는 흐름이에요. 순수한 관심이 좋은 대화로 이어질 수 있어요.', '그 사람에게 궁금한 것을 하나 물어보세요.'),
  (32, 'crush', true, '표현이 서툴러요', '좋아하는 마음은 있지만 표현이 서툴러 오해를 살 수 있어요. 진심을 담아 천천히 표현하면 괜찮아요.', '하고 싶은 말을 미리 정리해 보세요.'),
  (32, 'their_heart', false, '당신이 궁금해요', '그 사람은 당신에게 호기심을 느끼며 더 알고 싶어 하는 것 같아요. 순수한 관심의 시작일 수 있어요.', '나에 대한 이야기를 조금씩 들려 주세요.'),
  (32, 'their_heart', true, '마음이 들쑥날쑥해요', '상대는 관심이 있다가도 표현이 서툴러 들쑥날쑥한 모습을 보일 수 있어요. 아직 마음이 자라는 중일 수 있어요.', '상대의 반응에 너무 일희일비하지 않아도 돼요.'),
  (32, 'some', false, '풋풋한 썸이에요', '썸이 풋풋하고 설레게 시작되는 흐름이에요. 서로에 대한 호기심이 관계를 즐겁게 만들어요.', '새로운 경험을 함께 해 보자고 제안해 보세요.'),
  (32, 'some', true, '진지함이 부족해요', '썸이 재미는 있지만 진지하게 이어지지 않을 수 있어요. 관계에 대해 조금 더 진지하게 생각해 볼 때예요.', '이 관계에서 원하는 것을 생각해 보세요.'),
  (32, 'breakup', false, '새로운 관심이 생겨요', '이별 뒤 새로운 것에 호기심이 생기며 마음이 다시 움직이는 흐름이에요. 새로운 관심이 새로운 인연으로 이어질 수 있어요.', '평소 궁금했던 것을 하나 배워 보세요.'),
  (32, 'breakup', true, '마음이 흔들려요', '이별 후 감정이 오락가락하며 마음이 쉽게 흔들릴 수 있어요. 충동적인 결정보다 차분히 기다리는 게 좋아요.', '감정이 흔들릴 때 일기를 써 보세요.'),
  (32, 'confess', false, '설렘을 가볍게 전해요', '가볍고 설레는 마음을 전하기 좋은 흐름이에요. 무거운 고백보다 "너 좀 궁금해" 같은 표현이 잘 통할 수 있어요.', '가볍게 호감을 표현하는 말부터 시작해 보세요.'),
  (32, 'confess', true, '마음을 조금 더 키워요', '아직 마음이 충분히 자라지 않았거나 표현이 서툴 수 있어요. 조금 더 시간을 두고 마음을 키운 뒤 전하면 좋아요.', '고백 전 상대를 조금 더 알아가 보세요.'),
  (33, 'crush', false, '직진해도 좋아요', '마음이 뜨거운 지금, 망설임 없이 다가가기 좋은 흐름이에요. 당신의 열정적인 모습이 그 사람의 마음을 움직일 수 있어요.', '용기를 내서 먼저 만남을 제안해 보세요.'),
  (33, 'crush', true, '속도를 조절해요', '마음이 급해 너무 빠르게 다가가면 상대가 부담을 느낄 수 있어요. 열정은 그대로 두되 속도를 조금 늦추면 좋아요.', '상대의 반응을 살피며 한 걸음씩 다가가 보세요.'),
  (33, 'their_heart', false, '적극적으로 다가오고 싶어 해요', '그 사람은 당신에게 열정적으로 다가가고 싶은 마음이 있는 것 같아요. 적극적인 연락이나 제안이 그 신호일 수 있어요.', '상대의 제안에 반갑게 응해 주세요.'),
  (33, 'their_heart', true, '마음이 쉽게 변해요', '상대는 열정적이지만 마음이 쉽게 바뀌는 시기일 수 있어요. 진심을 확인하려면 시간이 조금 필요해요.', '상대의 꾸준함을 천천히 지켜보세요.'),
  (33, 'some', false, '썸이 뜨겁게 달아올라요', '썸이 빠르고 뜨겁게 진행되는 흐름이에요. 설렘을 마음껏 즐기되 서로의 마음도 함께 확인하면 좋아요.', '즉흥적인 데이트로 설렘을 더해 보세요.'),
  (33, 'some', true, '너무 서두르고 있어요', '썸에서 한쪽이 너무 앞서가거나 충동적으로 행동하고 있을 수 있어요. 서로의 속도를 맞추면 관계가 더 안정돼요.', '다음 단계로 가기 전 서로의 마음을 확인해 보세요.'),
  (33, 'breakup', false, '새로운 모험을 떠나요', '이별 뒤 새로운 모험을 떠나고 싶은 에너지가 생기는 흐름이에요. 새로운 경험이 마음을 회복시켜 주고 새 인연도 데려올 수 있어요.', '가 보고 싶던 곳으로 짧은 여행을 떠나 보세요.'),
  (33, 'breakup', true, '충동적인 연락은 참아요', '갑자기 연락하거나 충동적으로 행동하고 싶은 마음이 들 수 있어요. 감정이 가라앉은 뒤에 결정하면 후회가 줄어들어요.', '연락하고 싶을 때는 운동으로 에너지를 풀어 보세요.'),
  (33, 'confess', false, '용기 있게 직진해요', '망설임 없이 마음을 전하기 좋은 흐름이에요. 당신의 열정적인 고백이 상대의 마음을 설레게 할 수 있어요.', '망설이지 말고 솔직하게 마음을 전해 보세요.'),
  (33, 'confess', true, '충동은 잠시 미뤄요', '감정이 너무 앞서 준비 없이 고백하고 싶을 수 있어요. 조금만 마음을 가라앉히면 더 좋은 고백이 될 수 있어요.', '고백 전 하루만 생각해 보세요.'),
  (34, 'crush', false, '당당한 매력이 빛나요', '당신의 밝고 당당한 매력이 그 사람의 눈길을 끄는 때예요. 있는 그대로의 자신감 있는 모습을 보여 주면 좋아요.', '좋아하는 옷을 입고 자신 있게 하루를 보내 보세요.'),
  (34, 'crush', true, '질투가 마음을 흔들어요', '그 사람 주변의 다른 사람이 신경 쓰여 마음이 흔들릴 수 있어요. 비교보다 나만의 매력을 믿어 주세요.', '질투가 날 때 나의 장점을 떠올려 보세요.'),
  (34, 'their_heart', false, '당신에게 매력을 느껴요', '그 사람은 당신의 밝고 당당한 모습에 끌리고 있는 것 같아요. 함께 있으면 기분이 좋아진다고 느낄 수 있어요.', '상대에게 밝은 웃음을 보여 주세요.'),
  (34, 'their_heart', true, '불안해하고 있어요', '상대는 당신을 좋아하면서도 혹시 다른 사람에게 마음이 갈까 불안해하고 있을 수 있어요. 안심시켜 주는 표현이 도움이 돼요.', '상대에게 특별하다는 걸 표현해 주세요.'),
  (34, 'some', false, '매력이 통하는 썸이에요', '당신의 자신감 있는 매력이 썸을 주도하는 흐름이에요. 따뜻하고 당당한 모습이 관계를 더 깊게 만들어요.', '자신 있게 데이트를 이끌어 보세요.'),
  (34, 'some', true, '예민해진 마음을 달래요', '썸 중에 작은 일에도 예민해지거나 질투가 날 수 있어요. 감정을 솔직하게 나누면 오해가 줄어들어요.', '서운한 마음을 부드럽게 표현해 보세요.'),
  (34, 'breakup', false, '다시 당당해져요', '이별 뒤 당신만의 밝은 매력과 자신감을 되찾는 흐름이에요. 당당한 모습이 새로운 인연을 자연스럽게 끌어당겨요.', '나를 빛나게 하는 일에 시간을 써 보세요.'),
  (34, 'breakup', true, '비교하지 않아요', '전 연인의 새로운 소식에 마음이 흔들릴 수 있어요. 다른 사람과 비교하기보다 나의 회복에 집중하면 좋아요.', '전 연인의 소식은 잠시 보지 않기로 해 보세요.'),
  (34, 'confess', false, '자신 있게 전해요', '당신의 매력과 자신감이 빛나는 지금, 고백하기 좋은 흐름이에요. 당당하고 따뜻한 고백이 좋은 반응을 이끌 수 있어요.', '밝은 미소와 함께 마음을 전해 보세요.'),
  (34, 'confess', true, '불안함부터 달래요', '질투나 불안 때문에 서둘러 고백하고 싶을 수 있어요. 마음이 차분해진 뒤에 전하면 진심이 더 잘 닿아요.', '고백하려는 이유가 불안 때문인지 살펴보세요.'),
  (35, 'crush', false, '주도적으로 다가가요', '짝사랑을 당신이 주도적으로 이끌어 갈 수 있는 흐름이에요. 분명하고 든든한 모습이 그 사람에게 믿음을 줄 수 있어요.', '구체적인 계획을 세워 그 사람에게 다가가 보세요.'),
  (35, 'crush', true, '내 방식만 고집하지 않아요', '다가가는 방식이 너무 일방적이지 않은지 살펴볼 때예요. 그 사람의 반응과 속도를 존중하면 관계가 편안해져요.', '그 사람이 원하는 것을 먼저 물어보세요.'),
  (35, 'their_heart', false, '당신을 이끌고 싶어 해요', '그 사람은 당신과의 관계를 든든하게 이끌어 가고 싶은 마음이 있는 것 같아요. 함께할 미래를 그리고 있을 수 있어요.', '상대의 제안에 믿음을 보여 주세요.'),
  (35, 'their_heart', true, '자기 생각이 강해요', '상대는 관계에서 자기 방식을 고집하고 있을 수 있어요. 서로의 생각을 나누는 대화가 필요해요.', '내 생각도 솔직하게 이야기해 보세요.'),
  (35, 'some', false, '썸에 방향이 생겨요', '썸이 분명한 방향을 갖고 앞으로 나아가는 흐름이에요. 누군가 관계를 이끌어 주면 연애로 자연스럽게 이어질 수 있어요.', '관계의 다음 단계를 먼저 제안해 보세요.'),
  (35, 'some', true, '주도권 다툼이 있어요', '썸에서 서로 주도권을 쥐려 하며 부딪힐 수 있어요. 함께 결정하는 연습을 하면 관계가 편안해져요.', '데이트 계획을 함께 세워 보세요.'),
  (35, 'breakup', false, '내 삶을 이끌어요', '이별 뒤 내 삶의 주인으로서 방향을 다시 세우는 흐름이에요. 분명한 목표가 마음을 단단하게 회복시켜 줘요.', '앞으로 1년의 목표를 세워 보세요.'),
  (35, 'breakup', true, '억지로 바꾸려 하지 않아요', '상대의 마음이나 상황을 내 뜻대로 바꾸고 싶은 마음이 들 수 있어요. 바꿀 수 없는 것을 받아들이면 마음이 편해져요.', '내가 통제할 수 있는 일에만 집중해 보세요.'),
  (35, 'confess', false, '분명하게 전해요', '마음을 분명하고 당당하게 전하기 좋은 흐름이에요. 당신의 확신 있는 고백이 상대에게 믿음을 줄 수 있어요.', '원하는 관계를 분명하게 말해 보세요.'),
  (35, 'confess', true, '상대의 마음도 들어요', '고백할 때 내 마음만 앞세우면 상대가 부담을 느낄 수 있어요. 상대의 생각을 들을 여유를 함께 준비하면 좋아요.', '고백 후 상대의 대답을 천천히 기다려 주세요.'),
  (36, 'crush', false, '사랑이 샘솟고 있어요', '그 사람을 향한 순수한 마음이 가득 차오르는 흐름이에요. 이 따뜻한 감정이 자연스럽게 상대에게도 전해질 수 있어요.', '그 사람에게 따뜻한 말 한마디를 건네 보세요.'),
  (36, 'crush', true, '마음을 꺼내기 어려워요', '좋아하는 마음은 있지만 표현하기가 막막하게 느껴질 수 있어요. 작은 표현부터 시작하면 마음이 조금씩 흘러가요.', '오늘은 "고마워" 같은 작은 마음부터 표현해 보세요.'),
  (36, 'their_heart', false, '새로운 감정이 생겼어요', '그 사람의 마음속에 당신을 향한 새로운 감정이 피어나고 있는 것 같아요. 아직 시작이지만 순수하고 따뜻한 마음일 수 있어요.', '상대의 작은 호의에 따뜻하게 반응해 주세요.'),
  (36, 'their_heart', true, '감정을 숨기고 있어요', '상대는 마음이 있어도 감정을 표현하는 데 서툴러 숨기고 있을 수 있어요. 편안한 분위기가 마음을 여는 데 도움이 돼요.', '상대가 마음 편히 이야기할 수 있게 기다려 주세요.'),
  (36, 'some', false, '사랑이 시작되고 있어요', '썸이 진짜 사랑으로 피어나기 시작하는 흐름이에요. 서로를 향한 감정이 넘쳐 관계가 깊어지기 좋은 때예요.', '마음이 담긴 작은 선물을 건네 보세요.'),
  (36, 'some', true, '감정이 잘 오가지 않아요', '썸에서 감정 표현이 잘 오가지 않아 답답할 수 있어요. 한 사람이 먼저 마음을 열면 흐름이 바뀔 수 있어요.', '먼저 솔직한 감정을 하나 나눠 보세요.'),
  (36, 'breakup', false, '다시 사랑할 수 있어요', '이별의 아픔 뒤에도 마음속에는 새로운 사랑이 샘솟을 수 있어요. 마음이 채워지면 다시 사랑할 준비가 될 거예요.', '나를 사랑하는 시간을 먼저 가져 보세요.'),
  (36, 'breakup', true, '마음이 텅 빈 것 같아요', '이별 후 마음이 비어 버린 것처럼 느껴질 수 있어요. 빈 잔은 다시 채울 수 있으니 나를 위한 따뜻한 일로 조금씩 채워 주세요.', '좋아하는 음악이나 영화로 마음을 채워 보세요.'),
  (36, 'confess', false, '마음을 전하기 좋아요', '넘치는 감정을 솔직하게 전하기 좋은 흐름이에요. 순수한 마음이 그대로 상대에게 닿을 수 있어요.', '진심을 담아 솔직하게 마음을 전해 보세요.'),
  (36, 'confess', true, '내 마음부터 확인해요', '아직 내 감정이 정리되지 않았거나 표현할 준비가 덜 됐을 수 있어요. 마음을 먼저 들여다본 뒤 전하면 좋아요.', '고백 전 내 마음을 글로 정리해 보세요.'),
  (37, 'crush', false, '마음이 통하고 있어요', '그 사람과 서로 마음이 통하는 교감이 느껴지는 흐름이에요. 짝사랑이 한쪽만의 마음이 아닐 가능성이 보여요.', '둘만의 대화 시간을 만들어 보세요.'),
  (37, 'crush', true, '마음의 크기가 달라요', '내가 주는 마음과 상대의 마음이 지금은 조금 다를 수 있어요. 억지로 맞추기보다 천천히 서로를 알아가면 좋아요.', '그 사람에 대해 새로운 것을 하나 알아보세요.'),
  (37, 'their_heart', false, '서로 끌리고 있어요', '그 사람도 당신에게 끌림을 느끼며 마음이 통한다고 생각하는 것 같아요. 함께 있을 때 특별한 교감을 느낄 수 있어요.', '상대와 눈을 맞추며 이야기해 보세요.'),
  (37, 'their_heart', true, '오해가 있을 수 있어요', '상대는 당신의 마음을 오해하고 있거나 확신이 없을 수 있어요. 솔직한 대화가 오해를 풀어 줄 수 있어요.', '내 마음을 분명하게 표현해 보세요.'),
  (37, 'some', false, '연인 같은 썸이에요', '썸이 연인처럼 서로 마음을 주고받는 흐름이에요. 이 교감이 이어진다면 관계가 자연스럽게 연애로 이어질 수 있어요.', '서로의 마음을 확인하는 대화를 나눠 보세요.'),
  (37, 'some', true, '감정이 엇갈려요', '썸에서 서로의 감정이 엇갈려 어색할 수 있어요. 누가 더 좋아하는지 따지기보다 마음을 나누는 게 먼저예요.', '서운한 점을 부드럽게 이야기해 보세요.'),
  (37, 'breakup', false, '마음을 나눌 수 있어요', '지난 관계에서 서로 진심을 나눌 기회가 생길 수 있어요. 재회든 정리든, 마음을 나누는 대화가 서로에게 위로가 될 수 있어요.', '대화할 기회가 온다면 원망보다 고마움을 먼저 전해 보세요.'),
  (37, 'breakup', true, '엇갈린 마음을 인정해요', '서로의 마음이 엇갈렸다는 걸 받아들이기 힘들 수 있어요. 인정하는 것이 마음을 정리하고 새 인연으로 나아가는 첫걸음이에요.', '엇갈렸던 순간을 떠올리며 마음을 정리해 보세요.'),
  (37, 'confess', false, '마음이 통하는 지금이에요', '서로의 마음이 통하고 있는 지금, 고백하기 좋은 흐름이에요. 진심을 전하면 상대도 같은 마음으로 답할 가능성이 커요.', '둘만 있는 편안한 자리에서 마음을 전해 보세요.'),
  (37, 'confess', true, '마음을 먼저 맞춰요', '아직 서로의 마음이 엇갈려 있을 수 있어요. 조금 더 교감을 쌓은 뒤 고백하면 좋은 결과로 이어질 수 있어요.', '고백 전 서로를 더 알아가는 시간을 가져 보세요.'),
  (38, 'crush', false, '모임에서 가까워져요', '친구들과의 즐거운 모임에서 그 사람과 가까워질 기회가 생길 수 있어요. 편안한 분위기에서 자연스럽게 마음이 통해요.', '그 사람과 함께하는 모임에 적극적으로 참여해 보세요.'),
  (38, 'crush', true, '주변 관계를 살펴봐요', '그 사람 주변에 신경 쓰이는 사람이 있거나 친구 관계가 복잡할 수 있어요. 섣불리 판단하지 말고 상황을 살펴보면 좋아요.', '주변 사람들의 말보다 직접 확인해 보세요.'),
  (38, 'their_heart', false, '함께하면 즐거워해요', '그 사람은 당신과 함께하는 시간을 즐겁고 편안하게 느끼는 것 같아요. 친구처럼 편하면서도 즐거운 사이로 여기고 있을 수 있어요.', '함께 웃을 수 있는 즐거운 시간을 만들어 보세요.'),
  (38, 'their_heart', true, '마음이 여러 곳에 있어요', '상대는 지금 여러 사람과의 관계 속에서 마음이 분산되어 있을 수 있어요. 당신을 특별하게 느낄 수 있는 시간이 필요해요.', '둘만의 시간을 만들어 보세요.'),
  (38, 'some', false, '즐거운 썸이에요', '썸이 즐겁고 유쾌하게 이어지는 흐름이에요. 친구들과 함께하는 자리에서도 잘 어울리는 사이일 수 있어요.', '친구들과 함께하는 모임에 상대를 초대해 보세요.'),
  (38, 'some', true, '제3자가 신경 쓰여요', '썸 사이에 다른 사람이 끼어들어 마음이 불편할 수 있어요. 관계에 대해 솔직하게 이야기하면 마음이 편해져요.', '불편한 마음을 솔직하게 나눠 보세요.'),
  (38, 'breakup', false, '친구들이 힘이 돼요', '이별 뒤 친구들과의 즐거운 시간이 마음을 회복시켜 주는 흐름이에요. 함께 웃다 보면 새로운 인연도 자연스럽게 다가와요.', '친구들과 즐거운 약속을 잡아 보세요.'),
  (38, 'breakup', true, '주변 말에 흔들리지 않아요', '주변의 말이나 소문 때문에 마음이 더 복잡해질 수 있어요. 내 마음을 기준으로 정리하는 게 좋아요.', '이별 이야기는 믿을 수 있는 한두 사람에게만 나눠 보세요.'),
  (38, 'confess', false, '즐거운 분위기를 활용해요', '즐거운 모임이나 축하 자리 뒤에 마음을 전하기 좋은 흐름이에요. 기분 좋은 분위기가 고백을 자연스럽게 만들어 줘요.', '즐거운 모임 후 둘만 남는 시간에 마음을 전해 보세요.'),
  (38, 'confess', true, '둘만의 자리에서 전해요', '여러 사람 앞에서의 고백은 상대에게 부담이 될 수 있어요. 둘만 있는 조용한 자리에서 전하면 더 좋아요.', '고백은 꼭 단둘이 있을 때 해 보세요.'),
  (39, 'crush', false, '다가온 기회를 봐요', '짝사랑에 지쳐 마음이 무뎌져 있을 수 있어요. 그 사이 다가오는 작은 기회나 신호를 놓치지 않도록 주변을 살펴보면 좋아요.', '그 사람이 보내는 작은 신호를 다시 떠올려 보세요.'),
  (39, 'crush', true, '마음이 다시 깨어나요', '무뎌졌던 마음이 다시 설레기 시작하는 흐름이에요. 그 사람이나 새로운 인연을 새롭게 바라볼 수 있어요.', '새로운 시선으로 그 사람을 바라봐 주세요.'),
  (39, 'their_heart', false, '생각이 많은 상태예요', '그 사람은 지금 다른 고민에 빠져 당신의 마음을 잘 알아차리지 못하고 있을 수 있어요. 무관심이라기보다 여유가 없는 것일 수 있어요.', '상대에게 편하게 고민을 털어놓을 기회를 주세요.'),
  (39, 'their_heart', true, '당신을 다시 보고 있어요', '상대가 당신의 좋은 점을 새롭게 알아차리기 시작한 것 같아요. 관심이 조금씩 커지고 있을 수 있어요.', '상대에게 새로운 내 모습을 보여 주세요.'),
  (39, 'some', false, '썸이 지루해졌어요', '썸이 오래되며 설렘이 줄고 권태가 느껴질 수 있어요. 새로운 자극이 관계에 생기를 불어넣을 수 있어요.', '평소와 다른 새로운 데이트를 해 보세요.'),
  (39, 'some', true, '설렘이 돌아와요', '잠시 시들했던 썸에 다시 설렘이 돌아오는 흐름이에요. 서로에 대한 관심이 새롭게 커질 수 있어요.', '다시 설레는 마음을 표현해 보세요.'),
  (39, 'breakup', false, '주변을 둘러봐요', '지난 관계만 생각하다 보면 주변의 좋은 사람이나 기회를 놓칠 수 있어요. 고개를 들어 주변을 둘러보면 새로운 인연이 보일 수 있어요.', '새로운 사람들과의 만남에 마음을 열어 보세요.'),
  (39, 'breakup', true, '다시 세상이 보여요', '무뎌졌던 마음이 깨어나며 새로운 것들에 관심이 생기는 흐름이에요. 마음이 회복되고 있다는 좋은 신호예요.', '새롭게 관심 가는 일을 하나 시작해 보세요.'),
  (39, 'confess', false, '상대의 마음을 살펴요', '지금은 상대가 다른 일에 마음이 가 있어 고백이 잘 닿지 않을 수 있어요. 상대가 여유로운 때를 기다리면 좋아요.', '상대의 고민이 정리됐는지 먼저 살펴보세요.'),
  (39, 'confess', true, '기회를 알아차릴 때예요', '고백할 좋은 기회가 다가오고 있다는 걸 알아차리는 흐름이에요. 망설이지 말고 기회를 잡아 보면 좋아요.', '다음 만남에서 마음을 살짝 비춰 보세요.'),
  (40, 'crush', false, '남은 가능성을 봐요', '기대가 어긋나 실망했을 수 있지만, 아직 모든 게 끝난 건 아니에요. 아쉬움에만 머물지 말고 남은 가능성에 눈을 돌려 보세요.', '그 사람과의 좋은 기억을 하나 떠올려 보세요.'),
  (40, 'crush', true, '실망에서 일어서요', '짝사랑의 아픔에서 조금씩 회복되는 흐름이에요. 마음이 가벼워지면 다시 다가가든 정리하든 선택할 힘이 생겨요.', '오늘 나를 위한 작은 즐거움을 하나 만들어 보세요.'),
  (40, 'their_heart', false, '아쉬움이 남아 있어요', '그 사람은 무언가에 대한 아쉬움이나 상처 때문에 마음이 무거울 수 있어요. 지금은 위로가 필요한 상태일 수 있어요.', '상대에게 조용히 곁에 있어 주세요.'),
  (40, 'their_heart', true, '마음을 회복하고 있어요', '상대는 지난 아쉬움을 털어내고 다시 마음을 열어 가는 중인 것 같아요. 천천히 다가가면 좋은 관계로 이어질 수 있어요.', '상대가 편하게 마음을 열 수 있도록 기다려 주세요.'),
  (40, 'some', false, '작은 실망이 있었어요', '썸에서 기대와 다른 일이 있어 실망했을 수 있어요. 아쉬움만 보지 말고 관계에 남아 있는 좋은 점들도 함께 봐 주세요.', '상대의 좋은 점을 하나 떠올려 보세요.'),
  (40, 'some', true, '다시 좋아지고 있어요', '실망스러웠던 일을 지나 썸이 다시 좋아지는 흐름이에요. 서로 이해하며 관계를 회복할 수 있어요.', '먼저 다가가 분위기를 풀어 보세요.'),
  (40, 'breakup', false, '슬픔을 충분히 느껴요', '이별의 슬픔이 크게 느껴지는 때예요. 슬픔을 억누르기보다 충분히 느끼고, 그 뒤에 남아 있는 좋은 것들을 바라보면 좋아요.', '슬플 때는 참지 말고 충분히 울어도 괜찮아요.'),
  (40, 'breakup', true, '다시 일어설 수 있어요', '이별의 아픔을 받아들이고 다시 일어서는 흐름이에요. 남아 있는 사람들과 새로운 가능성이 당신을 기다리고 있어요.', '나를 아끼는 사람에게 연락해 보세요.'),
  (40, 'confess', false, '마음을 먼저 추슬러요', '최근 실망이나 아쉬움 때문에 마음이 흔들려 있을 수 있어요. 마음을 먼저 추스른 뒤 전하면 더 좋은 고백이 될 수 있어요.', '고백 전 내 마음을 편안하게 돌봐 주세요.'),
  (40, 'confess', true, '다시 용기를 내요', '지난 아쉬움을 털어내고 다시 용기를 낼 수 있는 흐름이에요. 회복된 마음으로 전하는 고백은 더 진솔하게 닿을 수 있어요.', '용기를 내서 마음을 전해 보세요.'),
  (41, 'crush', false, '순수한 마음이 통해요', '꾸밈없는 순수한 마음이 그 사람에게 따뜻하게 전해질 수 있는 흐름이에요. 오래 알던 사람이라면 추억이 관계를 이어 줄 수 있어요.', '그 사람과의 즐거운 추억을 함께 이야기해 보세요.'),
  (41, 'crush', true, '지금의 그 사람을 봐요', '예전의 기억 속 그 사람만 바라보고 있을 수 있어요. 지금의 그 사람을 있는 그대로 알아가면 관계가 더 분명해져요.', '요즘 그 사람의 관심사를 물어보세요.'),
  (41, 'their_heart', false, '편안하고 다정하게 느껴요', '그 사람은 당신에게 오래된 친구처럼 편안하고 다정한 감정을 느끼는 것 같아요. 함께한 추억을 소중히 여기고 있을 수 있어요.', '함께한 추억을 떠올리게 하는 이야기를 꺼내 보세요.'),
  (41, 'their_heart', true, '과거를 정리하는 중이에요', '상대는 지난 기억이나 관계를 정리하며 앞으로 나아가려는 중일 수 있어요. 지금의 관계에 집중할 시간을 주면 좋아요.', '지금 함께하는 순간에 집중해 주세요.'),
  (41, 'some', false, '풋풋하고 다정한 썸이에요', '썸이 순수하고 다정하게 이어지는 흐름이에요. 어린 시절처럼 꾸밈없는 마음이 관계를 따뜻하게 만들어요.', '추억의 장소나 놀이를 함께 즐겨 보세요.'),
  (41, 'some', true, '앞으로 나아갈 때예요', '썸이 편안하지만 친구 같은 관계에 머물러 있을 수 있어요. 관계를 앞으로 진전시키려면 새로운 시도가 필요해요.', '평소와 다른 분위기의 데이트를 제안해 보세요.'),
  (41, 'breakup', false, '추억은 간직해요', '지난 관계의 좋은 추억이 떠오르는 때예요. 추억은 소중하게 간직하되, 그 추억에 머물지 않고 앞으로 나아가면 좋아요.', '좋았던 추억에 고마움을 느끼며 정리해 보세요.'),
  (41, 'breakup', true, '현재로 돌아와요', '과거의 추억에서 벗어나 지금의 삶으로 돌아오는 흐름이에요. 새로운 추억을 만들 준비가 되어 가고 있어요.', '새로운 추억을 만들 수 있는 일을 계획해 보세요.'),
  (41, 'confess', false, '순수하게 전해요', '꾸밈없이 순수한 마음을 전하기 좋은 흐름이에요. 함께한 추억을 담아 고백하면 더 따뜻하게 전해질 수 있어요.', '함께한 추억을 떠올리며 마음을 전해 보세요.'),
  (41, 'confess', true, '지금의 마음을 전해요', '예전의 감정보다 지금 내 마음이 어떤지 먼저 확인해 보면 좋아요. 현재의 진심을 전할 때 고백이 더 힘을 가져요.', '지금 그 사람이 좋은 이유를 정리해 보세요.'),
  (42, 'crush', false, '상상 속 그 사람일 수 있어요', '그 사람을 마음속에서 이상화하고 있을 수 있어요. 상상 속 모습보다 실제 그 사람을 알아가는 게 중요해요.', '그 사람에 대해 실제로 아는 것을 적어 보세요.'),
  (42, 'crush', true, '마음이 분명해져요', '흐릿했던 마음이 정리되며 정말 원하는 것이 보이는 흐름이에요. 이제 다가갈지 정리할지 선택할 수 있어요.', '내가 정말 원하는 관계를 정리해 보세요.'),
  (42, 'their_heart', false, '마음이 여러 갈래예요', '그 사람은 여러 가능성 사이에서 고민하고 있어 마음이 분명하지 않을 수 있어요. 지금 당장 답을 기대하기보다 지켜보면 좋아요.', '상대가 스스로 정리할 시간을 주세요.'),
  (42, 'their_heart', true, '마음을 정하고 있어요', '상대는 여러 고민 끝에 마음을 분명히 정해 가는 중인 것 같아요. 곧 마음을 보여줄 수 있어요.', '상대의 결정을 차분히 기다려 주세요.'),
  (42, 'some', false, '기대와 현실을 구분해요', '썸에 대한 기대가 현실보다 커져 있을 수 있어요. 상상 속 관계가 아니라 지금의 실제 관계를 바라보면 좋아요.', '지금 우리 관계의 실제 모습을 정리해 보세요.'),
  (42, 'some', true, '관계가 선명해져요', '애매했던 썸이 분명해지며 관계의 방향이 보이는 흐름이에요. 현실적인 대화로 다음 단계를 정할 수 있어요.', '서로 원하는 관계를 솔직하게 이야기해 보세요.'),
  (42, 'breakup', false, '환상을 내려놓아요', '다시 만나면 모든 게 좋아질 거라는 상상이 마음을 붙잡고 있을 수 있어요. 현실을 차분히 바라보면 마음 정리가 쉬워져요.', '재회했을 때의 현실적인 모습을 떠올려 보세요.'),
  (42, 'breakup', true, '현실이 보이기 시작해요', '지난 관계를 있는 그대로 바라보게 되는 흐름이에요. 분명해진 마음으로 나에게 맞는 선택을 할 수 있어요.', '나에게 정말 필요한 관계가 무엇인지 적어 보세요.'),
  (42, 'confess', false, '마음을 먼저 정리해요', '지금은 상상과 기대가 커서 마음이 복잡할 수 있어요. 내가 정말 원하는 것을 분명히 한 뒤 고백하면 좋아요.', '고백하고 싶은 이유를 하나씩 적어 보세요.'),
  (42, 'confess', true, '선택할 준비가 됐어요', '마음이 분명해져 고백할 준비가 된 흐름이에요. 이제 망설임을 내려놓고 마음을 전해 봐도 좋아요.', '분명해진 마음을 담백하게 전해 보세요.'),
  (43, 'crush', false, '내 마음을 돌아볼 때예요', '짝사랑이 나를 채워 주지 못하고 지치게 하고 있다면 잠시 거리를 두는 것도 방법이에요. 더 나를 행복하게 하는 길이 있을 수 있어요.', '이 짝사랑이 나에게 주는 것과 가져가는 것을 생각해 보세요.'),
  (43, 'crush', true, '떠나기 망설여져요', '마음을 정리하고 싶으면서도 쉽게 놓지 못하고 있을 수 있어요. 서두르지 말고 내 마음이 원하는 걸 천천히 들어 보세요.', '그 사람을 계속 좋아하고 싶은지 스스로 물어보세요.'),
  (43, 'their_heart', false, '다른 길을 고민해요', '그 사람은 지금 무언가 더 의미 있는 것을 찾아 고민하고 있는 것 같아요. 관계보다 자신의 길에 집중하고 싶은 때일 수 있어요.', '상대의 고민을 존중하며 응원해 주세요.'),
  (43, 'their_heart', true, '머물지 떠날지 고민해요', '상대는 관계에 대해 망설이며 마음을 정하지 못하고 있을 수 있어요. 재촉하기보다 상대의 결정을 기다려 주는 게 좋아요.', '부담을 주지 않는 선에서 편안하게 대해 주세요.'),
  (43, 'some', false, '썸이 멀어지고 있어요', '썸에서 한쪽이 마음을 거두고 멀어지고 있을 수 있어요. 이 관계가 서로에게 의미 있는지 돌아볼 때예요.', '이 썸이 나를 행복하게 하는지 생각해 보세요.'),
  (43, 'some', true, '다시 돌아볼 때예요', '멀어지려던 썸을 다시 돌아보며 고민하는 흐름이에요. 아직 마음이 남아 있다면 솔직하게 이야기해 볼 수 있어요.', '남아 있는 마음을 솔직하게 나눠 보세요.'),
  (43, 'breakup', false, '새로운 길을 떠나요', '채워지지 않던 관계를 뒤로하고 더 나은 나를 찾아 떠나는 흐름이에요. 이 걸음이 새로운 인연과 행복으로 이어질 수 있어요.', '새로운 환경이나 경험에 도전해 보세요.'),
  (43, 'breakup', true, '자꾸 뒤돌아봐요', '떠나기로 마음먹었지만 자꾸 지난 관계를 돌아보게 될 수 있어요. 아쉬움은 자연스러운 감정이니, 천천히 앞을 보며 걸어가면 돼요.', '뒤돌아보고 싶을 때 앞으로의 계획을 떠올려 보세요.'),
  (43, 'confess', false, '마음을 먼저 확인해요', '고백보다 이 관계가 나에게 정말 의미 있는지 확인하는 게 먼저일 수 있어요. 마음이 분명해지면 고백도 자연스러워져요.', '이 사람과 함께하는 미래를 그려 보세요.'),
  (43, 'confess', true, '망설임을 정리해요', '고백할지 말지 오래 망설이고 있을 수 있어요. 망설임의 이유를 정리하면 어느 쪽이든 결정하기 쉬워져요.', '고백했을 때와 안 했을 때를 함께 상상해 보세요.'),
  (44, 'crush', false, '바라는 일이 이뤄져요', '짝사랑에 대한 소원이 이뤄지기 쉬운 행복한 흐름이에요. 그 사람과 가까워지는 기쁜 일이 생길 수 있어요.', '그 사람과의 즐거운 시간을 마음껏 누려 보세요.'),
  (44, 'crush', true, '기대를 조금 내려놓아요', '그 사람에게 바라는 것이 너무 커져 작은 반응에 만족하기 어려울 수 있어요. 기대를 조금 내려놓으면 작은 행복이 보여요.', '그 사람과의 작은 순간에 감사해 보세요.'),
  (44, 'their_heart', false, '당신과 있어 행복해요', '그 사람은 당신과 함께하는 시간에 큰 만족과 행복을 느끼는 것 같아요. 당신을 소중한 사람으로 여기고 있을 수 있어요.', '상대에게 함께해서 행복하다고 말해 주세요.'),
  (44, 'their_heart', true, '무언가 부족하다고 느껴요', '상대는 관계에서 무언가 채워지지 않는 부분을 느끼고 있을 수 있어요. 서로 원하는 것을 이야기해 보면 좋아요.', '상대가 바라는 것이 무엇인지 물어보세요.'),
  (44, 'some', false, '만족스러운 썸이에요', '썸이 만족스럽고 행복하게 이어지는 흐름이에요. 서로에게 바라던 것을 채워 주는 관계로 자랄 수 있어요.', '함께하고 싶었던 일을 하나 이뤄 보세요.'),
  (44, 'some', true, '욕심이 커졌어요', '썸에 대한 기대가 커져 지금의 관계에 만족하기 어려울 수 있어요. 지금의 좋은 점을 먼저 바라보면 마음이 편해져요.', '지금 썸에서 좋은 점 세 가지를 적어 보세요.'),
  (44, 'breakup', false, '나만의 행복을 찾아요', '이별 뒤에도 나를 행복하게 하는 것들을 찾아 만족할 수 있는 흐름이에요. 스스로 행복한 사람은 좋은 인연을 끌어당겨요.', '나를 행복하게 하는 일을 하나 해 보세요.'),
  (44, 'breakup', true, '빈자리를 서둘러 채우지 않아요', '허전함을 다른 것으로 급히 채우려 해도 마음이 채워지지 않을 수 있어요. 천천히 나를 돌보는 것이 진짜 채움이에요.', '오늘은 나를 위해 조용히 쉬어 보세요.'),
  (44, 'confess', false, '소원을 이룰 때예요', '고백이 좋은 결과로 이어지기 쉬운 행복한 흐름이에요. 바라던 관계를 향해 용기를 내 보면 좋아요.', '행복한 기분으로 마음을 전해 보세요.'),
  (44, 'confess', true, '기대를 조절하고 전해요', '고백에 너무 큰 기대를 걸고 있을 수 있어요. 결과보다 마음을 전한다는 데 의미를 두면 부담이 줄어요.', '고백의 목적을 ''마음을 나누는 것''으로 생각해 보세요.'),
  (45, 'crush', false, '행복한 미래가 그려져요', '그 사람과 함께하는 행복한 미래를 그려 볼 수 있는 흐름이에요. 짝사랑이 따뜻한 관계로 이어질 가능성이 보여요.', '그 사람과 함께하고 싶은 일을 상상해 보세요.'),
  (45, 'crush', true, '바라는 그림을 확인해요', '그 사람과 내가 원하는 관계의 모습이 다를 수 있어요. 그 사람이 어떤 사람인지 더 알아가며 확인하면 좋아요.', '그 사람의 가치관을 알 수 있는 대화를 나눠 보세요.'),
  (45, 'their_heart', false, '오래 함께하고 싶어 해요', '그 사람은 당신과 오래도록 행복한 관계를 이어가고 싶어 하는 것 같아요. 함께하는 미래를 진지하게 생각하고 있을 수 있어요.', '상대와 함께하는 미래 이야기를 나눠 보세요.'),
  (45, 'their_heart', true, '다른 그림을 그리고 있어요', '상대는 관계에 대해 당신과 조금 다른 기대를 품고 있을 수 있어요. 서로의 생각을 나누면 오해가 줄어들어요.', '서로 원하는 관계의 모습을 이야기해 보세요.'),
  (45, 'some', false, '행복한 연애로 이어져요', '썸이 따뜻하고 행복한 연애로 이어질 수 있는 흐름이에요. 서로가 같은 미래를 그리고 있다면 관계가 더 깊어질 수 있어요.', '함께하고 싶은 미래를 가볍게 이야기해 보세요.'),
  (45, 'some', true, '기대가 서로 달라요', '썸에서 서로 원하는 관계의 모습이 달라 어긋날 수 있어요. 솔직한 대화로 서로의 기대를 맞춰 보면 좋아요.', '"우리 어떤 관계가 되면 좋을까?"라고 물어보세요.'),
  (45, 'breakup', false, '행복한 관계를 다시 그려요', '지난 관계를 정리하며 내가 원하는 행복한 관계를 다시 그려 볼 수 있는 때예요. 그 그림이 새로운 인연을 만나는 기준이 돼요.', '내가 원하는 행복한 관계의 모습을 적어 보세요.'),
  (45, 'breakup', true, '다른 그림을 인정해요', '서로 원하던 미래가 달랐다는 걸 받아들이기 힘들 수 있어요. 그 차이를 인정하면 마음 정리가 조금 더 쉬워져요.', '서로 달랐던 점을 차분히 돌아보세요.'),
  (45, 'confess', false, '마음을 전하기 좋아요', '따뜻하고 행복한 흐름 속에서 고백하기 좋은 때예요. 함께하는 미래를 담아 진심을 전하면 좋은 결과로 이어질 수 있어요.', '그 사람과 함께하고 싶은 마음을 솔직하게 전해 보세요.'),
  (45, 'confess', true, '기대를 먼저 맞춰요', '고백 전에 서로 원하는 관계의 모습이 같은지 확인해 보면 좋아요. 같은 그림을 그릴 때 고백이 더 잘 닿아요.', '고백 전 상대가 원하는 연애를 넌지시 물어보세요.'),
  (46, 'crush', false, '설레는 소식이 와요', '그 사람과 관련된 설레는 소식이나 다정한 연락이 올 수 있는 흐름이에요. 작은 표현 하나가 마음을 가깝게 만들어요.', '그 사람에게 귀여운 이모티콘을 보내 보세요.'),
  (46, 'crush', true, '감정이 오락가락해요', '그 사람의 작은 반응에 기분이 쉽게 오르락내리락할 수 있어요. 감정에 휩쓸리기보다 마음을 차분히 다독여 주면 좋아요.', '기분이 흔들릴 때는 잠시 휴대폰을 내려놓아 보세요.'),
  (46, 'their_heart', false, '다정한 마음을 품고 있어요', '그 사람은 당신에게 순수하고 다정한 마음을 품고 있는 것 같아요. 수줍게 마음을 표현하고 싶어 할 수 있어요.', '상대의 작은 표현을 소중히 받아 주세요.'),
  (46, 'their_heart', true, '마음 표현이 서툴러요', '상대는 마음이 있어도 표현이 서툴러 오해를 살 수 있어요. 말보다 행동에서 마음을 읽어 주면 좋아요.', '상대의 행동에 담긴 마음을 알아봐 주세요.'),
  (46, 'some', false, '달콤한 썸이에요', '썸이 달콤하고 감성적으로 흐르는 흐름이에요. 다정한 말과 작은 선물이 오가며 마음이 깊어질 수 있어요.', '마음을 담은 짧은 편지를 써 보세요.'),
  (46, 'some', true, '감정 기복이 있어요', '썸 중에 감정이 쉽게 흔들리며 서운함이 생길 수 있어요. 작은 일에 너무 마음 쓰지 않으면 관계가 편안해져요.', '서운할 땐 하루 지나서 다시 생각해 보세요.'),
  (46, 'breakup', false, '마음이 다시 말랑해져요', '이별의 아픔이 조금씩 풀리며 다시 설렐 수 있는 마음이 돌아오는 흐름이에요. 새로운 감정에 마음을 열 준비가 되어 가요.', '나를 설레게 하는 작은 일을 찾아보세요.'),
  (46, 'breakup', true, '감정을 천천히 정리해요', '이별 후 감정이 오락가락하며 마음이 불안정할 수 있어요. 충동적으로 연락하기보다 감정을 글로 정리해 보면 좋아요.', '감정이 올라올 때 일기를 써 보세요.'),
  (46, 'confess', false, '귀엽게 마음을 전해요', '부담 없이 다정하게 마음을 전하기 좋은 흐름이에요. 무겁지 않은 귀여운 표현이 상대를 웃게 만들 수 있어요.', '작은 선물과 함께 마음을 살짝 전해 보세요.'),
  (46, 'confess', true, '마음을 조금 더 정리해요', '감정이 들뜨거나 흔들려 있는 상태라면 고백이 의도와 다르게 전해질 수 있어요. 마음이 차분해진 뒤 전하면 좋아요.', '고백할 말을 미리 적어 정리해 보세요.'),
  (47, 'crush', false, '로맨틱한 기회가 와요', '그 사람과 로맨틱한 시간을 보낼 기회가 생길 수 있는 흐름이에요. 다정하게 다가가면 마음이 잘 전해질 수 있어요.', '분위기 좋은 곳에서 만나자고 제안해 보세요.'),
  (47, 'crush', true, '환상과 현실을 구분해요', '그 사람에 대한 로맨틱한 상상이 현실보다 커져 있을 수 있어요. 실제 그 사람의 행동을 차분히 지켜보면 좋아요.', '그 사람의 실제 행동을 떠올려 보세요.'),
  (47, 'their_heart', false, '다가가고 싶어 해요', '그 사람은 당신에게 로맨틱하게 다가가고 싶은 마음이 있는 것 같아요. 다정한 제안이나 표현이 그 신호일 수 있어요.', '상대의 다정한 제안에 반갑게 응해 주세요.'),
  (47, 'their_heart', true, '말과 행동이 달라요', '상대는 달콤한 말을 하지만 행동이 따르지 않을 수 있어요. 진심인지 확인하려면 시간을 두고 지켜보면 좋아요.', '말보다 꾸준한 행동을 지켜봐 주세요.'),
  (47, 'some', false, '로맨틱한 썸이에요', '썸이 로맨틱하고 다정하게 흘러가는 흐름이에요. 한쪽에서 관계를 진전시키자는 제안이 올 수 있어요.', '분위기 있는 데이트를 계획해 보세요.'),
  (47, 'some', true, '약속이 지켜지지 않아요', '썸에서 달콤한 말이 오가지만 실제 약속은 자꾸 미뤄질 수 있어요. 관계를 현실적으로 바라볼 때예요.', '약속을 구체적으로 정해 보세요.'),
  (47, 'breakup', false, '다정한 연락이 올 수 있어요', '지난 인연이나 새로운 인연에게서 다정한 연락이 올 수 있는 흐름이에요. 마음이 흔들리더라도 천천히 내 마음을 확인하고 답하면 좋아요.', '연락이 오면 바로 답하기보다 내 마음을 먼저 확인해 보세요.'),
  (47, 'breakup', true, '달콤한 말에 흔들리지 않아요', '다시 잘해 보자는 달콤한 말에 마음이 흔들릴 수 있어요. 말보다 실제로 무엇이 달라졌는지 살펴보면 좋아요.', '예전과 달라진 점이 있는지 차분히 생각해 보세요.'),
  (47, 'confess', false, '로맨틱하게 전해요', '다정하고 로맨틱한 고백이 잘 어울리는 흐름이에요. 진심을 담은 표현이 상대의 마음을 설레게 할 수 있어요.', '분위기 좋은 장소에서 마음을 전해 보세요.'),
  (47, 'confess', true, '진심을 먼저 확인해요', '고백에 대한 상상이 너무 커서 현실과 다를 수 있어요. 화려한 연출보다 진심이 중요하다는 걸 기억해 주세요.', '고백 이벤트보다 전할 말에 집중해 보세요.'),
  (48, 'crush', false, '따뜻한 배려가 통해요', '당신의 다정한 공감과 배려가 그 사람에게 깊이 전해지는 흐름이에요. 그 사람의 마음을 헤아려 주는 모습이 큰 매력이 돼요.', '그 사람의 이야기에 진심으로 공감해 주세요.'),
  (48, 'crush', true, '나를 잃지 않아요', '그 사람의 감정에 너무 맞추다 보니 내 마음이 지칠 수 있어요. 나의 감정도 똑같이 소중하다는 걸 기억해 주세요.', '오늘은 내 감정을 먼저 돌봐 주세요.'),
  (48, 'their_heart', false, '당신에게 위로받아요', '그 사람은 당신의 따뜻한 마음에서 큰 위로와 안정감을 느끼는 것 같아요. 감정적으로 깊이 연결되어 있다고 느낄 수 있어요.', '상대가 힘들 때 곁에서 들어 주세요.'),
  (48, 'their_heart', true, '감정이 예민해요', '상대는 지금 감정이 예민해 작은 일에도 쉽게 흔들릴 수 있어요. 부드럽게 다가가 주면 좋아요.', '상대의 기분을 살피며 다정하게 대해 주세요.'),
  (48, 'some', false, '깊이 교감하는 썸이에요', '썸에서 서로의 감정을 깊이 나누며 교감하는 흐름이에요. 마음을 헤아려 주는 관계가 연애로 이어지기 좋아요.', '서로의 속마음을 나누는 대화를 해 보세요.'),
  (48, 'some', true, '감정에 휩쓸리고 있어요', '썸 중에 감정이 너무 커져 상대의 반응에 쉽게 흔들릴 수 있어요. 마음의 중심을 잡으면 관계가 편안해져요.', '감정이 커질 때 잠시 숨을 고르고 생각해 보세요.'),
  (48, 'breakup', false, '나를 다정하게 안아줘요', '이별의 아픔을 다정하게 보듬어 주는 시간이 필요한 때예요. 내 감정을 충분히 헤아려 주면 마음이 천천히 회복돼요.', '나에게 따뜻한 위로의 말을 건네 보세요.'),
  (48, 'breakup', true, '감정에 잠기지 않아요', '이별의 슬픔에 너무 깊이 잠겨 있을 수 있어요. 감정을 느끼되, 일상을 조금씩 되찾는 것도 함께 해 주면 좋아요.', '오늘 해야 할 작은 일 하나를 해 보세요.'),
  (48, 'confess', false, '다정하게 전해요', '따뜻하고 진심 어린 고백이 잘 통하는 흐름이에요. 상대의 마음을 배려하며 전하면 좋은 반응을 얻을 수 있어요.', '상대가 편안한 분위기에서 마음을 전해 보세요.'),
  (48, 'confess', true, '감정을 먼저 다독여요', '감정이 너무 커서 고백이 부담스럽게 전해질 수 있어요. 마음을 차분히 다독인 뒤 전하면 좋아요.', '고백 전 내 감정을 정리해 보세요.'),
  (49, 'crush', false, '성숙하게 다가가요', '감정에 휩쓸리지 않고 차분하게 다가가는 모습이 그 사람에게 믿음을 줄 수 있어요. 안정감 있는 태도가 큰 매력이 돼요.', '그 사람이 고민을 이야기하면 차분하게 들어 주세요.'),
  (49, 'crush', true, '감정을 숨기고 있어요', '좋아하는 마음을 너무 억누르고 있어 상대가 알아차리지 못할 수 있어요. 조금은 솔직하게 표현해도 괜찮아요.', '작은 호감 표현을 하나 해 보세요.'),
  (49, 'their_heart', false, '든든하게 생각해요', '그 사람은 당신을 감정적으로 안정되고 믿을 수 있는 사람으로 여기는 것 같아요. 함께 있으면 마음이 편안해진다고 느낄 수 있어요.', '상대에게 든든한 모습을 보여 주세요.'),
  (49, 'their_heart', true, '감정을 드러내지 않아요', '상대는 마음이 있어도 감정을 잘 드러내지 않아 차갑게 보일 수 있어요. 표현이 적다고 마음이 없는 건 아닐 수 있어요.', '상대의 작은 행동에서 마음을 읽어 주세요.'),
  (49, 'some', false, '안정적인 썸이에요', '썸이 감정적으로 안정되고 성숙하게 이어지는 흐름이에요. 서로를 포용하는 관계가 오래가는 연애로 이어질 수 있어요.', '서로의 고민을 나누며 의지해 보세요.'),
  (49, 'some', true, '표현이 부족해요', '썸에서 서로 감정 표현이 부족해 관계가 미지근하게 느껴질 수 있어요. 조금 더 솔직하게 마음을 나누면 좋아요.', '"너랑 있으면 편해"처럼 마음을 표현해 보세요.'),
  (49, 'breakup', false, '차분하게 정리해요', '이별을 감정적으로 휩쓸리지 않고 성숙하게 정리할 수 있는 흐름이에요. 차분한 마음이 앞으로의 선택을 지혜롭게 만들어 줘요.', '지난 관계를 차분하게 돌아보는 시간을 가져 보세요.'),
  (49, 'breakup', true, '감정을 억누르지 않아요', '괜찮은 척 감정을 억누르고 있을 수 있어요. 슬픔을 인정하고 표현해야 진짜로 정리할 수 있어요.', '믿을 수 있는 사람에게 솔직한 감정을 털어놓아 보세요.'),
  (49, 'confess', false, '차분하게 전해요', '감정에 휩쓸리지 않고 차분하게 마음을 전하기 좋은 흐름이에요. 성숙한 고백이 상대에게 믿음을 줄 수 있어요.', '조용하고 편안한 장소에서 진지하게 이야기해 보세요.'),
  (49, 'confess', true, '솔직함이 필요해요', '고백하면서도 감정을 너무 절제하면 마음이 잘 전해지지 않을 수 있어요. 조금 더 솔직하게 표현해도 괜찮아요.', '내 감정을 있는 그대로 말해 보세요.'),
  (50, 'crush', false, '마음이 또렷해져요', '그 사람에 대한 내 마음이 분명해지는 흐름이에요. 이제 어떻게 할지 명확하게 결정할 수 있어요.', '그 사람에게 하고 싶은 말을 한 문장으로 정리해 보세요.'),
  (50, 'crush', true, '생각이 엉켜 있어요', '그 사람을 두고 이런저런 생각이 엉켜 마음이 복잡할 수 있어요. 생각을 하나씩 정리하면 답이 보여요.', '머릿속 생각을 종이에 적어 정리해 보세요.'),
  (50, 'their_heart', false, '솔직한 마음을 갖고 있어요', '그 사람은 당신에 대해 분명한 생각을 갖고 있는 것 같아요. 기회가 되면 솔직하게 마음을 말해 줄 수 있어요.', '상대에게 솔직하게 물어볼 기회를 만들어 보세요.'),
  (50, 'their_heart', true, '마음이 혼란스러워요', '상대는 당신에 대한 마음을 정리하지 못해 혼란스러워하고 있을 수 있어요. 말이 앞뒤가 맞지 않더라도 너무 마음 쓰지 않아도 돼요.', '상대가 생각을 정리할 시간을 주세요.'),
  (50, 'some', false, '관계를 분명히 할 때예요', '애매했던 썸을 분명하게 정리할 수 있는 흐름이에요. 솔직한 대화가 관계의 방향을 정해 줄 수 있어요.', '"우리 무슨 사이야?"라고 솔직하게 물어보세요.'),
  (50, 'some', true, '말이 엇나가요', '썸 중에 말 한마디가 날카롭게 전해져 오해가 생길 수 있어요. 감정적인 말은 잠시 미뤄 두면 좋아요.', '중요한 말은 한 번 더 생각하고 해 보세요.'),
  (50, 'breakup', false, '진실을 마주해요', '지난 관계를 있는 그대로 바라보며 진실을 마주하는 흐름이에요. 분명해진 마음이 앞으로 나아갈 힘이 돼요.', '이별의 이유를 솔직하게 적어 보세요.'),
  (50, 'breakup', true, '말로 상처 주지 않아요', '이별 후 감정이 올라와 날카로운 말을 하고 싶을 수 있어요. 말은 되돌리기 어려우니 마음이 차분해진 뒤에 전하면 좋아요.', '보내고 싶은 말은 일단 메모장에 적어 두세요.'),
  (50, 'confess', false, '분명하게 전할 때예요', '마음이 또렷해져 솔직하고 분명하게 고백하기 좋은 흐름이에요. 돌려 말하지 않는 진심이 잘 전해질 수 있어요.', '하고 싶은 말을 짧고 분명하게 준비해 보세요.'),
  (50, 'confess', true, '생각을 먼저 정리해요', '아직 마음이 정리되지 않아 고백이 혼란스럽게 전해질 수 있어요. 생각을 정리한 뒤 전하면 좋아요.', '고백할 말을 미리 적어 연습해 보세요.'),
  (51, 'crush', false, '결정을 미루고 있어요', '다가갈지 마음을 접을지 고민하며 결정을 미루고 있을 수 있어요. 눈을 가리고 있으면 답이 보이지 않으니 조금씩 상황을 바라봐 주세요.', '다가갈 때와 마음을 접을 때의 장단점을 적어 보세요.'),
  (51, 'crush', true, '마음을 정할 때예요', '오래 망설였던 짝사랑에 대해 마음을 정하는 흐름이에요. 어떤 결정이든 내 마음을 따르면 후회가 적어요.', '내 마음이 가리키는 방향을 믿어 보세요.'),
  (51, 'their_heart', false, '마음을 닫아 두고 있어요', '그 사람은 상처받을까 봐 마음의 문을 닫고 고민하고 있을 수 있어요. 결정을 재촉하면 더 닫힐 수 있으니 기다려 주면 좋아요.', '부담 없이 편안하게 대해 주세요.'),
  (51, 'their_heart', true, '마음을 열기 시작해요', '상대가 고민을 끝내고 조금씩 마음을 열기 시작하는 것 같아요. 곧 자신의 생각을 이야기해 줄 수 있어요.', '상대가 이야기할 때 끝까지 들어 주세요.'),
  (51, 'some', false, '팽팽한 썸이에요', '썸이 어느 쪽으로도 기울지 않고 멈춰 있을 수 있어요. 서로 눈치만 보고 있다면 누군가 먼저 마음을 보여 줘야 해요.', '먼저 작은 호감 표현을 해 보세요.'),
  (51, 'some', true, '균형이 깨지고 있어요', '멈춰 있던 썸이 한쪽으로 움직이기 시작하는 흐름이에요. 이 변화가 관계를 분명하게 만들어 줄 수 있어요.', '변화가 생기면 솔직한 마음을 나눠 보세요.'),
  (51, 'breakup', false, '감정을 피하고 있어요', '이별의 아픔을 마주하기 싫어 감정을 외면하고 있을 수 있어요. 감정을 인정해야 진짜로 정리할 수 있어요.', '조용한 곳에서 내 감정을 솔직하게 들여다보세요.'),
  (51, 'breakup', true, '마주할 용기가 생겨요', '피하던 감정을 마주하고 결정을 내릴 수 있는 흐름이에요. 아프더라도 그 결정이 나를 앞으로 나아가게 해 줘요.', '마음을 정리하는 작은 결정을 하나 내려 보세요.'),
  (51, 'confess', false, '아직 고민 중이에요', '고백할지 말지 마음이 팽팽하게 맞서 있을 수 있어요. 결정을 서두르기보다 내 마음을 차분히 들여다보면 좋아요.', '고백하고 싶은 마음과 망설이는 마음을 함께 적어 보세요.'),
  (51, 'confess', true, '결정할 때가 왔어요', '오래 고민했던 고백에 대해 결정을 내릴 수 있는 흐름이에요. 내 마음이 정한 대로 용기를 내 보면 좋아요.', '고백하기로 했다면 날짜를 정해 보세요.'),
  (52, 'crush', false, '마음이 아플 수 있어요', '짝사랑 때문에 서운하거나 아픈 일이 있을 수 있어요. 아픈 마음을 숨기지 말고 충분히 다독여 주는 게 먼저예요.', '속상한 마음을 친구에게 털어놓아 보세요.'),
  (52, 'crush', true, '상처가 아물고 있어요', '짝사랑으로 아팠던 마음이 조금씩 회복되고 있어요. 다시 웃을 수 있는 날이 다가오고 있어요.', '나를 웃게 하는 일을 하나 해 보세요.'),
  (52, 'their_heart', false, '마음에 상처가 있어요', '그 사람은 지금 다른 일로 마음이 아프거나 상처받은 상태일 수 있어요. 연애보다 위로가 필요한 때일 수 있어요.', '상대에게 조용히 위로를 건네 보세요.'),
  (52, 'their_heart', true, '상처를 털어내고 있어요', '상대는 지난 상처를 털어내고 다시 마음을 열어 가는 중인 것 같아요. 천천히 다가가면 좋은 관계로 이어질 수 있어요.', '상대가 편하게 기댈 수 있게 해 주세요.'),
  (52, 'some', false, '서운한 일이 생겨요', '썸 중에 서운하거나 마음 아픈 일이 생길 수 있어요. 혼자 삭이기보다 솔직하게 이야기하면 오해가 풀릴 수 있어요.', '서운한 마음을 부드럽게 전해 보세요.'),
  (52, 'some', true, '서운함이 풀려요', '썸에서 생긴 서운함이나 오해가 풀리는 흐름이에요. 서로 이해하며 관계가 더 단단해질 수 있어요.', '먼저 미안하다고, 고맙다고 말해 보세요.'),
  (52, 'breakup', false, '아픔을 충분히 느껴요', '이별의 아픔이 크게 느껴지는 때예요. 슬픔을 억지로 참기보다 충분히 느끼고 흘려보내야 마음이 회복될 수 있어요.', '슬플 때는 참지 말고 울어도 괜찮아요.'),
  (52, 'breakup', true, '마음이 아물어 가요', '이별의 상처가 조금씩 아물며 마음이 편안해지는 흐름이에요. 회복된 마음 위에 새로운 인연이 들어올 자리가 생겨요.', '회복된 나를 위해 작은 선물을 해 보세요.'),
  (52, 'confess', false, '마음을 먼저 돌봐요', '지금은 마음이 아프거나 서운한 상태라 고백이 부담스러울 수 있어요. 마음을 먼저 돌본 뒤 전해도 늦지 않아요.', '고백보다 내 마음을 먼저 다독여 주세요.'),
  (52, 'confess', true, '회복된 마음으로 전해요', '아팠던 마음이 회복되며 다시 용기를 낼 수 있는 흐름이에요. 상처를 이겨낸 진심은 더 단단하게 전해질 수 있어요.', '준비가 됐다면 차분하게 마음을 전해 보세요.'),
  (53, 'crush', false, '잠시 쉬어 가요', '짝사랑에 지친 마음을 잠시 쉬게 해 주면 좋은 때예요. 쉬는 동안 마음이 정리되며 더 좋은 방법이 보일 수 있어요.', '오늘은 그 사람 생각을 내려놓고 푹 쉬어 보세요.'),
  (53, 'crush', true, '다시 움직일 때예요', '충분히 쉬었다면 이제 다시 다가갈 힘이 생기는 흐름이에요. 재충전된 마음으로 한 걸음 나아가 보면 좋아요.', '가벼운 연락으로 다시 대화를 시작해 보세요.'),
  (53, 'their_heart', false, '쉬고 싶어 해요', '그 사람은 지금 지쳐서 혼자만의 쉼이 필요한 상태일 수 있어요. 연락이 뜸하더라도 마음이 식은 건 아닐 수 있어요.', '상대가 쉴 수 있도록 여유를 주세요.'),
  (53, 'their_heart', true, '다시 기운을 차렸어요', '상대가 쉼을 마치고 다시 관계에 마음을 쓸 준비가 된 것 같아요. 곧 연락이나 만남이 다시 이어질 수 있어요.', '상대의 연락에 반갑게 응해 주세요.'),
  (53, 'some', false, '썸이 잠시 쉬어 가요', '썸이 잠시 멈춘 것처럼 느껴질 수 있지만, 서로 숨을 고르는 시간일 수 있어요. 조급해하지 않아도 괜찮아요.', '연락을 재촉하지 말고 내 일상을 챙겨 보세요.'),
  (53, 'some', true, '다시 이어지는 흐름이에요', '잠시 멈췄던 썸이 다시 이어지기 시작하는 흐름이에요. 쉼 뒤의 관계는 더 편안할 수 있어요.', '가벼운 안부로 다시 대화를 시작해 보세요.'),
  (53, 'breakup', false, '쉼이 필요한 때예요', '이별 뒤 지친 마음과 몸을 쉬게 해 주는 게 가장 중요한 때예요. 아무것도 하지 않는 시간도 회복의 일부예요.', '오늘은 일찍 잠자리에 들어 보세요.'),
  (53, 'breakup', true, '다시 일어설 힘이 생겨요', '충분히 쉬고 나서 다시 일상으로 돌아갈 힘이 생기는 흐름이에요. 천천히 움직이면 새로운 시작도 자연스럽게 따라와요.', '미뤄 둔 일 하나를 다시 시작해 보세요.'),
  (53, 'confess', false, '지금은 쉬어 가요', '고백보다 마음을 쉬게 하고 정리하는 시간이 필요한 때예요. 충분히 쉰 뒤 전하면 마음이 더 잘 닿아요.', '고백은 잠시 미루고 나를 돌봐 주세요.'),
  (53, 'confess', true, '준비가 되어 가요', '쉼을 통해 마음이 정리되고 다시 용기가 생기는 흐름이에요. 마음이 준비됐다면 천천히 고백을 계획해 보세요.', '편안한 마음으로 고백할 날을 정해 보세요.'),
  (54, 'crush', false, '이기려 하지 않아요', '그 사람과의 관계에서 자존심을 세우거나 주변과 경쟁하느라 지칠 수 있어요. 이기는 것보다 마음이 통하는 게 더 중요해요.', '자존심보다 솔직한 마음을 보여 주세요.'),
  (54, 'crush', true, '갈등이 정리돼요', '짝사랑을 둘러싼 갈등이나 신경전이 정리되는 흐름이에요. 마음이 편안해지면 다시 자연스럽게 다가갈 수 있어요.', '불편했던 관계가 있다면 먼저 손을 내밀어 보세요.'),
  (54, 'their_heart', false, '자존심을 세우고 있어요', '그 사람은 관계에서 자존심 때문에 솔직한 마음을 드러내지 못하고 있을 수 있어요. 먼저 편하게 다가가 주면 좋아요.', '상대의 자존심을 지켜 주며 부드럽게 대해 주세요.'),
  (54, 'their_heart', true, '화해하고 싶어 해요', '상대는 지난 다툼이나 어색함을 풀고 화해하고 싶어 하는 것 같아요. 먼저 손을 내밀어 주면 관계가 회복될 수 있어요.', '가벼운 인사로 분위기를 풀어 주세요.'),
  (54, 'some', false, '다툼이 생길 수 있어요', '썸 중에 서로 자존심을 세우며 다툼이 생길 수 있어요. 누가 이기는지보다 관계를 지키는 게 더 중요해요.', '다툼이 생기면 먼저 한 발 물러서 보세요.'),
  (54, 'some', true, '화해의 흐름이에요', '썸에서 생긴 다툼이나 어색함이 풀리는 흐름이에요. 서로 이해하며 관계가 다시 따뜻해질 수 있어요.', '먼저 "미안해"라고 말해 보세요.'),
  (54, 'breakup', false, '누가 옳았는지보다요', '이별의 원인을 두고 누가 옳았는지 따지다 보면 마음이 더 지칠 수 있어요. 그보다 내 마음을 정리하는 데 집중하면 좋아요.', '옳고 그름 대신 내가 배운 점을 적어 보세요.'),
  (54, 'breakup', true, '갈등을 내려놓아요', '이별을 둘러싼 원망이나 갈등을 내려놓는 흐름이에요. 마음이 가벼워지면 새로운 시작이 보일 수 있어요.', '원망하는 마음을 조금씩 내려놓는 연습을 해 보세요.'),
  (54, 'confess', false, '갈등부터 풀어요', '최근 다툼이나 어색함이 있었다면 고백보다 화해가 먼저예요. 관계가 편안해진 뒤 전하면 더 잘 받아들여질 수 있어요.', '먼저 화해하고 분위기를 편안하게 만들어 보세요.'),
  (54, 'confess', true, '편안해진 지금이에요', '갈등이 풀리고 관계가 편안해진 지금, 마음을 전하기 좋은 흐름이에요. 솔직한 고백이 관계를 더 가깝게 만들어 줄 수 있어요.', '화해한 뒤 편안한 분위기에서 마음을 전해 보세요.'),
  (55, 'crush', false, '편안한 쪽으로 가요', '짝사랑으로 힘들었던 마음이 점점 편안해지는 흐름이에요. 관계가 조금씩 좋은 방향으로 나아갈 수 있어요.', '그 사람과 편안한 대화를 이어가 보세요.'),
  (55, 'crush', true, '같은 자리에 머물러요', '짝사랑이 진전 없이 같은 자리에 머물러 답답할 수 있어요. 작은 변화가 흐름을 바꿀 수 있어요.', '평소와 다른 방법으로 다가가 보세요.'),
  (55, 'their_heart', false, '관계를 좋게 이끌고 싶어 해요', '그 사람은 어색했던 관계를 더 편안하게 이끌어 가고 싶어 하는 것 같아요. 천천히 좋은 방향으로 나아가고 있어요.', '상대의 노력에 따뜻하게 반응해 주세요.'),
  (55, 'their_heart', true, '과거에 머물러 있어요', '상대는 지난 일이나 관계에 아직 마음이 머물러 있을 수 있어요. 시간을 주면 조금씩 앞으로 나아갈 수 있어요.', '상대가 지난 일을 정리할 시간을 존중해 주세요.'),
  (55, 'some', false, '썸이 순조로워져요', '어색하거나 힘들었던 썸이 점점 편안하고 순조롭게 흘러가는 흐름이에요. 관계가 좋은 방향으로 나아가고 있어요.', '편안한 분위기의 데이트를 계획해 보세요.'),
  (55, 'some', true, '앞으로 나아가지 못해요', '썸이 지난 문제에 발목 잡혀 앞으로 나아가지 못하고 있을 수 있어요. 지난 일을 정리하면 다시 흐름이 이어져요.', '마음에 걸리는 일을 솔직하게 이야기해 보세요.'),
  (55, 'breakup', false, '새로운 곳으로 나아가요', '이별의 아픔을 지나 마음이 더 편안한 곳으로 나아가는 흐름이에요. 천천히 나아가다 보면 새로운 인연도 만날 수 있어요.', '새로운 환경에서 기분 전환을 해 보세요.'),
  (55, 'breakup', true, '떠나기 어려워요', '지난 관계에서 쉽게 떠나지 못하고 마음이 머물러 있을 수 있어요. 서두르지 않아도 되니, 아주 작은 걸음부터 시작해 보면 좋아요.', '오늘은 지난 관계를 떠올리게 하는 물건 하나를 치워 보세요.'),
  (55, 'confess', false, '흐름이 좋아지고 있어요', '관계가 편안해지며 고백할 분위기가 점점 무르익는 흐름이에요. 조금만 더 기다리면 좋은 기회가 올 수 있어요.', '편안한 분위기가 이어질 때 마음을 살짝 비춰 보세요.'),
  (55, 'confess', true, '지난 일부터 정리해요', '아직 정리되지 않은 일이 고백을 망설이게 하고 있을 수 있어요. 마음에 걸리는 것을 정리하면 고백도 편해져요.', '고백 전 마음에 걸리는 일을 먼저 정리해 보세요.'),
  (56, 'crush', false, '혼자 작전을 짜고 있어요', '그 사람에게 다가가려고 혼자 이런저런 작전을 짜고 있을 수 있어요. 계산보다 솔직한 마음이 더 잘 통할 때가 많아요.', '작전 대신 솔직한 한마디를 건네 보세요.'),
  (56, 'crush', true, '솔직해질 때예요', '마음을 숨기던 짝사랑에서 솔직해질 용기가 생기는 흐름이에요. 진심을 드러내면 관계가 더 분명해질 수 있어요.', '그 사람에게 작은 진심 하나를 표현해 보세요.'),
  (56, 'their_heart', false, '속마음을 감추고 있어요', '그 사람은 당신에 대한 마음을 쉽게 드러내지 않고 감추고 있을 수 있어요. 겉으로 보이는 모습만으로 판단하지 않는 게 좋아요.', '상대의 말보다 행동을 천천히 살펴보세요.'),
  (56, 'their_heart', true, '솔직해지려 해요', '상대가 감추던 마음을 솔직하게 털어놓으려는 것 같아요. 곧 진짜 마음을 알게 될 수 있어요.', '상대가 솔직하게 말할 수 있게 편안한 분위기를 만들어 주세요.'),
  (56, 'some', false, '서로 눈치를 봐요', '썸에서 서로 마음을 숨기며 눈치를 보고 있을 수 있어요. 계산하는 관계보다 솔직한 관계가 더 오래가요.', '먼저 솔직하게 마음을 보여 주세요.'),
  (56, 'some', true, '숨긴 마음이 드러나요', '썸에서 서로 감추던 마음이나 사실이 드러나는 흐름이에요. 솔직해지면 관계가 오히려 편안해질 수 있어요.', '드러난 마음을 부드럽게 받아들여 주세요.'),
  (56, 'breakup', false, '몰래 확인하지 않아요', '전 연인의 소식을 몰래 확인하며 마음을 쓰고 있을 수 있어요. 그럴수록 마음 정리가 늦어지니 조금씩 줄여 보면 좋아요.', '전 연인의 SNS를 보지 않는 날을 하루 정해 보세요.'),
  (56, 'breakup', true, '진실을 알게 돼요', '지난 관계에 대해 몰랐던 사실을 알게 되며 마음이 정리되는 흐름이에요. 분명해진 마음이 앞으로 나아갈 힘이 돼요.', '알게 된 것을 담담하게 받아들여 보세요.'),
  (56, 'confess', false, '계산보다 진심이에요', '고백을 너무 계산하고 있으면 진심이 잘 전해지지 않을 수 있어요. 솔직한 마음이 가장 좋은 전략이에요.', '꾸미지 않은 진심을 전해 보세요.'),
  (56, 'confess', true, '솔직하게 털어놓아요', '숨겨 온 마음을 솔직하게 털어놓기 좋은 흐름이에요. 진실한 고백이 상대에게 믿음을 줄 수 있어요.', '그동안 숨겨 온 마음을 담백하게 말해 보세요.'),
  (57, 'crush', false, '스스로 막고 있어요', '"나는 안 될 거야"라는 생각이 다가가지 못하게 막고 있을 수 있어요. 생각보다 길은 열려 있으니 눈가리개를 살짝 내려 보면 좋아요.', '다가가지 못하는 이유를 적고, 정말 그런지 다시 봐 주세요.'),
  (57, 'crush', true, '두려움에서 벗어나요', '짝사랑을 가로막던 두려움에서 벗어나는 흐름이에요. 마음이 자유로워지면 자연스럽게 다가갈 수 있어요.', '용기를 내서 작은 행동 하나를 해 보세요.'),
  (57, 'their_heart', false, '상황에 갇혀 있어요', '그 사람은 마음이 있어도 상황이나 두려움 때문에 움직이지 못하고 있을 수 있어요. 당신의 문제라기보다 상대의 사정일 수 있어요.', '상대의 상황을 이해해 주세요.'),
  (57, 'their_heart', true, '마음이 자유로워져요', '상대가 자신을 막던 고민에서 벗어나 마음을 표현하려는 것 같아요. 조금씩 다가올 수 있어요.', '상대가 다가올 때 반갑게 맞아 주세요.'),
  (57, 'some', false, '썸이 막혀 있는 느낌이에요', '썸이 답답하게 막혀 있는 듯 느껴질 수 있어요. 서로의 두려움이나 걱정이 관계를 가로막고 있을 수 있어요.', '걱정하는 것을 솔직하게 나눠 보세요.'),
  (57, 'some', true, '답답함이 풀려요', '막혀 있던 썸이 풀리며 관계가 자유롭게 흘러가는 흐름이에요. 마음을 열면 관계가 한결 편안해져요.', '부담 없이 편하게 대해 보세요.'),
  (57, 'breakup', false, '생각이 나를 가두고 있어요', '"다시는 사랑할 수 없을 거야" 같은 생각이 마음을 가두고 있을 수 있어요. 그건 지금의 감정일 뿐, 사실이 아닐 수 있어요.', '나를 가두는 생각을 적고 그 반대 문장을 적어 보세요.'),
  (57, 'breakup', true, '자유로워지고 있어요', '이별의 아픔과 두려움에서 벗어나 마음이 자유로워지는 흐름이에요. 새로운 시선으로 앞날을 바라볼 수 있어요.', '새로운 경험에 마음을 열어 보세요.'),
  (57, 'confess', false, '두려움을 살펴봐요', '거절에 대한 두려움이 고백을 막고 있을 수 있어요. 두려움을 하나씩 들여다보면 생각보다 작을 수 있어요.', '가장 두려운 것을 적고 그에 대한 대처법도 함께 적어 보세요.'),
  (57, 'confess', true, '용기가 생겨요', '고백을 가로막던 두려움에서 벗어나 용기가 생기는 흐름이에요. 자유로워진 마음으로 진심을 전해 보면 좋아요.', '마음이 가벼워진 지금 고백을 계획해 보세요.'),
  (58, 'crush', false, '걱정이 너무 커요', '그 사람 생각에 밤마다 걱정이 커지고 있을 수 있어요. 머릿속 상상이 실제보다 더 무겁게 느껴질 수 있어요.', '잠들기 전 걱정을 종이에 적고 내려놓아 보세요.'),
  (58, 'crush', true, '걱정이 줄어들어요', '짝사랑에 대한 걱정이 조금씩 가라앉는 흐름이에요. 마음이 편안해지면 상황을 더 차분하게 볼 수 있어요.', '걱정 대신 그 사람과의 좋은 기억을 떠올려 보세요.'),
  (58, 'their_heart', false, '걱정이 많은 상태예요', '그 사람은 지금 이런저런 걱정으로 마음이 무거운 상태일 수 있어요. 연애에 마음 쓸 여유가 없는 것일 수 있어요.', '상대에게 따뜻한 위로를 건네 보세요.'),
  (58, 'their_heart', true, '마음이 편안해지고 있어요', '상대의 걱정이 조금씩 풀리며 마음에 여유가 생기는 것 같아요. 관계에도 다시 관심을 기울일 수 있어요.', '가벼운 대화로 분위기를 편하게 만들어 주세요.'),
  (58, 'some', false, '혼자 걱정하고 있어요', '썸이 잘못될까 봐 혼자 걱정하며 마음을 졸이고 있을 수 있어요. 걱정은 실제로 확인하면 줄어드는 경우가 많아요.', '걱정되는 점을 솔직하게 물어보세요.'),
  (58, 'some', true, '불안이 풀려요', '썸에 대한 불안이 풀리며 관계가 편안해지는 흐름이에요. 걱정했던 일이 생각보다 괜찮을 수 있어요.', '편안해진 마음으로 썸을 즐겨 보세요.'),
  (58, 'breakup', false, '밤이 길게 느껴져요', '이별 뒤 밤마다 생각이 많아 잠 못 드는 날이 있을 수 있어요. 혼자 견디기 힘들다면 주변 사람에게 기대도 괜찮아요.', '잠들기 전 따뜻한 차를 마시며 마음을 쉬게 해 주세요.'),
  (58, 'breakup', true, '걱정이 가라앉아요', '이별 후의 불안과 걱정이 조금씩 가라앉는 흐름이에요. 마음이 편안해지면 새로운 시작을 준비할 수 있어요.', '마음이 편안해진 나를 칭찬해 주세요.'),
  (58, 'confess', false, '걱정을 먼저 덜어요', '고백에 대한 걱정이 너무 커서 마음이 무거울 수 있어요. 걱정을 덜어낸 뒤 전하면 더 편안하게 마음을 전할 수 있어요.', '믿을 수 있는 친구에게 고민을 털어놓아 보세요.'),
  (58, 'confess', true, '불안이 줄어들어요', '고백에 대한 불안이 줄어들며 용기가 생기는 흐름이에요. 마음이 편안해졌다면 차분히 고백을 준비해 보면 좋아요.', '편안한 마음으로 고백할 말을 정리해 보세요.'),
  (59, 'crush', false, '새벽이 밝아오고 있어요', '짝사랑으로 많이 지쳤다면 이제 가장 힘든 순간을 지나고 있는지도 몰라요. 이 시기를 지나면 마음이 한결 가벼워질 수 있어요.', '지친 마음을 위해 오늘은 푹 쉬어 주세요.'),
  (59, 'crush', true, '다시 일어서고 있어요', '짝사랑의 아픔에서 조금씩 일어서는 흐름이에요. 회복된 마음으로 다시 다가가거나 새로운 인연을 만날 수 있어요.', '회복을 위한 작은 일 하나를 시작해 보세요.'),
  (59, 'their_heart', false, '많이 지쳐 있어요', '그 사람은 지금 많은 일로 지쳐 마음의 여유가 없을 수 있어요. 당신에 대한 마음과는 별개로 쉼이 필요한 상태일 수 있어요.', '상대에게 부담 없는 응원을 보내 주세요.'),
  (59, 'their_heart', true, '다시 힘을 내고 있어요', '상대가 힘든 시기를 지나 다시 기운을 차리는 것 같아요. 관계에 다시 마음을 쓸 여유가 생길 수 있어요.', '상대의 회복을 곁에서 응원해 주세요.'),
  (59, 'some', false, '한 단계가 끝나요', '썸이 지금의 모습으로는 끝나고 새로운 국면을 맞을 수 있는 흐름이에요. 끝이 꼭 나쁜 것만은 아니라, 새로운 관계의 시작일 수도 있어요.', '이 관계에서 내가 원하는 것을 다시 생각해 보세요.'),
  (59, 'some', true, '다시 시작할 수 있어요', '힘들었던 썸이 회복되며 다시 시작할 수 있는 흐름이에요. 지난 일을 교훈 삼으면 더 좋은 관계가 될 수 있어요.', '새로운 마음으로 다시 대화를 시작해 보세요.'),
  (59, 'breakup', false, '가장 힘든 때를 지나요', '이별의 아픔이 가장 크게 느껴지는 때일 수 있어요. 하지만 바닥을 지나면 올라갈 일만 남아 있으니, 오늘은 나를 쉬게 해 주세요.', '힘들 땐 혼자 견디지 말고 가까운 사람에게 기대 보세요.'),
  (59, 'breakup', true, '회복이 시작됐어요', '이별의 아픔에서 벗어나 다시 일어서는 흐름이에요. 마음이 회복되며 새로운 인연을 맞을 준비가 되어 가요.', '회복된 나를 위해 새로운 계획을 세워 보세요.'),
  (59, 'confess', false, '지금은 회복이 먼저예요', '마음이 많이 지친 상태라면 고백보다 나를 먼저 돌보는 게 좋아요. 회복된 뒤 전하는 마음이 더 단단해요.', '고백은 잠시 미루고 충분히 쉬어 주세요.'),
  (59, 'confess', true, '다시 용기가 생겨요', '힘든 시기를 지나 다시 용기를 낼 수 있는 흐름이에요. 회복된 마음으로 천천히 고백을 준비해 보면 좋아요.', '마음이 준비되면 편안한 때에 마음을 전해 보세요.'),
  (60, 'crush', false, '그 사람을 알아가요', '그 사람에 대해 새로운 것을 알게 되는 흐름이에요. 호기심을 갖고 관찰하다 보면 다가갈 방법이 보여요.', '그 사람이 좋아하는 것을 하나 알아보세요.'),
  (60, 'crush', true, '소문에 흔들리지 않아요', '그 사람에 대한 소문이나 주변 말에 마음이 흔들릴 수 있어요. 직접 확인하지 않은 말은 잠시 내려놓으면 좋아요.', '궁금한 건 그 사람에게 직접 물어보세요.'),
  (60, 'their_heart', false, '당신이 궁금해요', '그 사람은 당신에 대해 궁금해하며 알아가고 싶어 하는 것 같아요. 이것저것 질문하는 건 관심의 표현일 수 있어요.', '상대의 질문에 친절하게 답해 주세요.'),
  (60, 'their_heart', true, '오해가 있을 수 있어요', '상대는 주변에서 들은 이야기 때문에 당신을 오해하고 있을 수 있어요. 직접 대화하면 오해가 풀릴 수 있어요.', '오해가 있다면 차분하게 설명해 보세요.'),
  (60, 'some', false, '서로를 탐색해요', '썸에서 서로에 대해 알아가며 탐색하는 흐름이에요. 궁금한 것을 묻고 답하며 관계가 깊어질 수 있어요.', '서로에게 궁금한 질문을 주고받아 보세요.'),
  (60, 'some', true, '말을 조심해요', '썸 중에 무심코 한 말이 오해를 살 수 있어요. 중요한 이야기는 한 번 더 생각하고 하면 좋아요.', '농담도 상대가 어떻게 받아들일지 생각해 보세요.'),
  (60, 'breakup', false, '새로운 시선이 생겨요', '지난 관계를 새로운 시선으로 바라보며 배우는 흐름이에요. 새로운 정보나 깨달음이 마음 정리를 도와줄 수 있어요.', '이별에서 배운 점을 하나 적어 보세요.'),
  (60, 'breakup', true, '소식에 휘둘리지 않아요', '전 연인의 소식이나 주변 말에 마음이 휘둘릴 수 있어요. 그런 소식은 잠시 멀리하는 것이 마음을 지키는 방법이에요.', '전 연인 소식을 전하는 대화는 정중히 피해 보세요.'),
  (60, 'confess', false, '상대를 더 알아봐요', '고백 전에 상대의 마음이나 상황을 조금 더 알아보기 좋은 흐름이에요. 충분히 알고 나면 더 좋은 타이밍을 잡을 수 있어요.', '상대의 요즘 관심사나 고민을 넌지시 물어보세요.'),
  (60, 'confess', true, '성급하게 말하지 않아요', '마음이 급해 준비 없이 고백하면 의도와 다르게 전해질 수 있어요. 조금 더 준비한 뒤 전하면 좋아요.', '고백할 말을 미리 연습해 보세요.'),
  (61, 'crush', false, '빠르게 다가가요', '망설임 없이 빠르게 다가가기 좋은 흐름이에요. 솔직하고 시원한 태도가 그 사람에게 좋은 인상을 줄 수 있어요.', '망설이지 말고 먼저 말을 걸어 보세요.'),
  (61, 'crush', true, '속도를 늦춰요', '너무 빠르게 다가가면 그 사람이 부담을 느낄 수 있어요. 상대의 반응을 살피며 속도를 조절하면 좋아요.', '한 번에 많은 걸 바라지 말고 천천히 다가가 보세요.'),
  (61, 'their_heart', false, '빨리 표현하고 싶어 해요', '그 사람은 당신에 대한 마음을 빠르게 표현하고 싶어 하는 것 같아요. 직설적인 표현이 진심의 신호일 수 있어요.', '상대의 솔직한 표현에 솔직하게 답해 주세요.'),
  (61, 'their_heart', true, '말이 거칠게 나올 수 있어요', '상대는 마음이 급하거나 스트레스가 있어 말이 거칠게 나올 수 있어요. 말투보다 속마음을 봐 주면 좋아요.', '상대의 말에 바로 반응하기보다 한 번 생각해 보세요.'),
  (61, 'some', false, '빠르게 진전돼요', '썸이 빠르게 진전되며 관계가 급속도로 가까워지는 흐름이에요. 솔직한 대화가 관계를 더 분명하게 만들어요.', '솔직한 마음을 바로 나눠 보세요.'),
  (61, 'some', true, '부딪힐 수 있어요', '썸 중에 서로 급하게 말하다 부딪힐 수 있어요. 감정이 올라올 땐 잠시 쉬었다 이야기하면 좋아요.', '다툼이 생기면 잠시 시간을 갖고 다시 이야기해 보세요.'),
  (61, 'breakup', false, '빠르게 정리해요', '이별 뒤 마음을 빠르게 정리하고 앞으로 나아가는 흐름이에요. 결단력 있는 태도가 새로운 시작을 앞당길 수 있어요.', '정리해야 할 것들을 하나씩 정리해 보세요.'),
  (61, 'breakup', true, '성급한 결정은 피해요', '감정에 휩쓸려 성급하게 연락하거나 결정하고 싶을 수 있어요. 마음이 차분해진 뒤 결정하면 후회가 줄어요.', '중요한 결정은 하루 미뤄 보세요.'),
  (61, 'confess', false, '솔직하게 직진해요', '망설임 없이 솔직하게 마음을 전하기 좋은 흐름이에요. 시원한 고백이 상대의 마음을 움직일 수 있어요.', '돌려 말하지 말고 솔직하게 말해 보세요.'),
  (61, 'confess', true, '말을 다듬어요', '급하게 고백하면 말이 거칠게 전해질 수 있어요. 하고 싶은 말을 미리 다듬으면 진심이 더 잘 전해져요.', '고백할 말을 부드럽게 다듬어 보세요.'),
  (62, 'crush', false, '분명한 기준을 가져요', '그 사람을 좋아하면서도 내 기준을 잃지 않는 흐름이에요. 이 관계가 나에게 좋은지 분명하게 판단할 수 있어요.', '내가 연애에서 지키고 싶은 기준을 적어 보세요.'),
  (62, 'crush', true, '마음의 벽을 낮춰요', '예전 상처 때문에 그 사람에게 마음을 쉽게 열지 못하고 있을 수 있어요. 조금씩 벽을 낮추면 따뜻한 관계가 될 수 있어요.', '그 사람에게 작은 마음 하나를 열어 보세요.'),
  (62, 'their_heart', false, '솔직하게 보고 있어요', '그 사람은 당신을 솔직하고 객관적으로 바라보며 판단하고 있는 것 같아요. 꾸밈없는 모습이 더 좋은 인상을 줄 수 있어요.', '있는 그대로의 나를 보여 주세요.'),
  (62, 'their_heart', true, '마음을 닫고 있어요', '상대는 지난 상처 때문에 마음을 닫고 차갑게 대하고 있을 수 있어요. 당신 때문이 아닐 수 있으니 천천히 다가가 주면 좋아요.', '상대의 차가운 반응에 너무 상처받지 않아도 돼요.'),
  (62, 'some', false, '솔직한 대화가 필요해요', '썸에서 솔직하고 분명한 대화가 관계를 정리해 줄 수 있는 흐름이에요. 애매함보다 분명함이 서로를 편하게 해 줘요.', '원하는 관계를 솔직하게 말해 보세요.'),
  (62, 'some', true, '말이 날카로워졌어요', '썸 중에 서로 말이 날카로워져 상처를 줄 수 있어요. 솔직함과 상처 주는 말은 다르다는 걸 기억해 주세요.', '솔직하되 부드러운 말투로 이야기해 보세요.'),
  (62, 'breakup', false, '단단하게 정리해요', '이별을 감정에 휩쓸리지 않고 단단하게 정리할 수 있는 흐름이에요. 분명한 기준이 다음 인연을 고르는 힘이 돼요.', '다음 연애에서 지키고 싶은 기준을 정해 보세요.'),
  (62, 'breakup', true, '마음을 너무 닫지 않아요', '이별의 상처 때문에 마음을 꽁꽁 닫고 있을 수 있어요. 나를 지키는 것도 중요하지만, 마음을 조금씩 여는 연습도 필요해요.', '새로운 사람과 가벼운 대화를 나눠 보세요.'),
  (62, 'confess', false, '분명하게 전해요', '돌려 말하지 않고 분명하게 마음을 전하기 좋은 흐름이에요. 솔직하고 담백한 고백이 상대에게 믿음을 줄 수 있어요.', '원하는 것을 분명하게 말해 보세요.'),
  (62, 'confess', true, '따뜻함을 더해요', '고백이 너무 딱딱하거나 차갑게 전해질 수 있어요. 진심에 따뜻한 표현을 조금 더하면 좋아요.', '고백할 때 미소와 다정한 말을 함께 전해 보세요.'),
  (63, 'crush', false, '차분하게 판단해요', '감정에 휩쓸리지 않고 짝사랑을 차분하게 바라볼 수 있는 흐름이에요. 이성적인 판단이 좋은 선택으로 이어질 수 있어요.', '그 사람과의 관계를 객관적으로 정리해 보세요.'),
  (63, 'crush', true, '마음의 소리도 들어요', '머리로만 판단하다 보니 내 마음을 놓치고 있을 수 있어요. 이성과 감정 모두 소중하다는 걸 기억해 주세요.', '머리가 아닌 마음이 원하는 걸 적어 보세요.'),
  (63, 'their_heart', false, '진지하게 생각하고 있어요', '그 사람은 당신과의 관계를 이성적이고 진지하게 생각하는 것 같아요. 신중하게 판단한 만큼 진심일 수 있어요.', '상대의 진지한 태도를 존중해 주세요.'),
  (63, 'their_heart', true, '감정 표현이 서툴러요', '상대는 감정보다 이성을 앞세워 차갑게 보일 수 있어요. 표현이 적다고 마음이 없는 건 아닐 수 있어요.', '상대가 감정을 편하게 표현할 수 있게 도와주세요.'),
  (63, 'some', false, '신뢰가 쌓이는 썸이에요', '썸이 신뢰를 바탕으로 차분하게 이어지는 흐름이에요. 서로를 믿는 마음이 관계를 단단하게 만들어요.', '약속을 지키며 신뢰를 쌓아 보세요.'),
  (63, 'some', true, '너무 따지고 있어요', '썸을 이성적으로만 따지다 보면 설렘이 줄어들 수 있어요. 가끔은 마음 가는 대로 즐겨도 괜찮아요.', '계산 없이 즐길 수 있는 데이트를 해 보세요.'),
  (63, 'breakup', false, '이성적으로 정리해요', '이별을 감정보다 이성으로 차분하게 정리할 수 있는 흐름이에요. 객관적인 시선이 다음 선택을 지혜롭게 만들어 줘요.', '지난 관계를 객관적으로 돌아보며 정리해 보세요.'),
  (63, 'breakup', true, '감정을 무시하지 않아요', '괜찮다고 머리로만 정리하고 감정은 외면하고 있을 수 있어요. 감정도 충분히 느껴야 진짜로 정리할 수 있어요.', '내 감정을 솔직하게 적어 보세요.'),
  (63, 'confess', false, '신중하게 전해요', '신중하고 진지하게 마음을 전하기 좋은 흐름이에요. 분명하고 믿음직한 고백이 상대에게 신뢰를 줄 수 있어요.', '진지한 분위기에서 차분하게 마음을 전해 보세요.'),
  (63, 'confess', true, '마음을 담아 전해요', '고백이 너무 논리적으로만 전해지면 마음이 잘 닿지 않을 수 있어요. 진심과 감정을 함께 담아 전하면 좋아요.', '고백할 때 내 감정을 솔직하게 표현해 보세요.'),
  (64, 'crush', false, '좋은 기회가 생겨요', '그 사람과 가까워질 수 있는 현실적인 기회가 생기는 흐름이에요. 작은 기회라도 놓치지 않고 잡으면 관계가 자라날 수 있어요.', '그 사람과 함께할 수 있는 일에 손을 들어 보세요.'),
  (64, 'crush', true, '기회를 다시 만들어요', '그 사람과 가까워질 기회를 놓쳤다고 느낄 수 있어요. 기회는 다시 만들 수 있으니 차근차근 준비해 보면 좋아요.', '그 사람과 자연스럽게 만날 수 있는 계기를 찾아보세요.'),
  (64, 'their_heart', false, '진지한 관심이 있어요', '그 사람은 당신에게 가볍지 않은 현실적인 관심을 갖고 있는 것 같아요. 오래 이어갈 수 있는 관계를 생각하고 있을 수 있어요.', '상대에게 믿음직한 모습을 보여 주세요.'),
  (64, 'their_heart', true, '확신이 부족해요', '상대는 관계를 시작하기에 아직 확신이나 여유가 부족하다고 느낄 수 있어요. 시간을 두고 신뢰를 쌓으면 좋아요.', '꾸준한 모습으로 믿음을 주세요.'),
  (64, 'some', false, '안정적인 시작이에요', '썸이 현실적이고 안정적인 관계로 시작되는 흐름이에요. 천천히 쌓아 가면 오래가는 연애가 될 수 있어요.', '함께할 수 있는 작은 일상을 만들어 보세요.'),
  (64, 'some', true, '기반이 약해요', '썸이 아직 단단한 기반 없이 흔들리고 있을 수 있어요. 서로를 알아가는 시간을 더 쌓으면 좋아요.', '서로의 일상을 조금 더 나눠 보세요.'),
  (64, 'breakup', false, '새로운 기반을 다져요', '이별 뒤 내 삶의 기반을 새롭게 다지기 좋은 흐름이에요. 안정된 일상이 마음을 회복시키고 새로운 인연을 맞을 준비가 돼요.', '새로운 목표나 계획을 하나 세워 보세요.'),
  (64, 'breakup', true, '기초부터 다시 해요', '이별 후 일상이 흔들려 불안할 수 있어요. 수면, 식사처럼 기본적인 것부터 챙기면 마음도 안정돼요.', '오늘은 규칙적으로 식사하는 것부터 챙겨 보세요.'),
  (64, 'confess', false, '좋은 기회가 와요', '고백하기 좋은 현실적인 기회가 찾아오는 흐름이에요. 준비된 마음으로 기회를 잡으면 좋은 결과로 이어질 수 있어요.', '고백할 기회가 오면 놓치지 말아요.'),
  (64, 'confess', true, '준비를 조금 더 해요', '아직 고백할 준비가 덜 됐거나 상황이 안정되지 않았을 수 있어요. 기초를 다진 뒤 전하면 더 좋아요.', '고백 전 관계를 조금 더 단단히 다져 보세요.'),
  (65, 'crush', false, '일상과 마음의 균형이에요', '바쁜 일상 속에서도 짝사랑을 유연하게 이어가는 흐름이에요. 너무 무겁지 않게, 즐겁게 마음을 이어가면 좋아요.', '바쁜 날에도 짧은 안부 하나는 챙겨 보세요.'),
  (65, 'crush', true, '여유가 부족해요', '할 일이 많아 짝사랑에 마음 쓸 여유가 부족할 수 있어요. 지금은 내 일상을 먼저 정리하는 게 좋아요.', '오늘 꼭 해야 할 일을 세 가지만 정해 보세요.'),
  (65, 'their_heart', false, '바쁘지만 마음이 있어요', '그 사람은 바쁜 일상 속에서도 당신을 생각하며 균형을 잡으려 하는 것 같아요. 연락이 짧아도 마음은 있을 수 있어요.', '상대의 바쁜 상황을 이해해 주세요.'),
  (65, 'their_heart', true, '여유가 없어요', '상대는 지금 여러 일에 치여 관계에 마음 쓸 여유가 없을 수 있어요. 당신에 대한 마음과는 별개일 수 있어요.', '부담 없는 응원 메시지를 보내 보세요.'),
  (65, 'some', false, '유연한 썸이에요', '서로 바쁜 와중에도 즐겁게 썸을 이어가는 흐름이에요. 무겁지 않고 유연한 관계가 오히려 편안할 수 있어요.', '짧은 시간이라도 즐겁게 만나 보세요.'),
  (65, 'some', true, '시간이 맞지 않아요', '서로 바빠 만남이나 연락의 타이밍이 계속 엇갈릴 수 있어요. 서로의 일정을 맞추는 노력이 필요해요.', '서로 여유 있는 시간을 미리 맞춰 보세요.'),
  (65, 'breakup', false, '바쁜 일상이 힘이 돼요', '이별 뒤 바쁜 일상을 유연하게 해내며 마음을 회복하는 흐름이에요. 할 일에 집중하다 보면 마음도 자연스럽게 정리돼요.', '새로운 일이나 활동에 에너지를 써 보세요.'),
  (65, 'breakup', true, '무리하지 않아요', '이별의 아픔을 잊으려 너무 많은 일을 벌이고 있을 수 있어요. 무리하면 더 지칠 수 있으니 쉼도 함께 챙기면 좋아요.', '일정 사이에 쉬는 시간을 꼭 넣어 보세요.'),
  (65, 'confess', false, '유연하게 타이밍을 봐요', '바쁜 일상 속에서도 고백할 타이밍을 유연하게 찾을 수 있는 흐름이에요. 완벽한 때보다 자연스러운 때가 더 좋을 수 있어요.', '여유가 생기는 날을 골라 마음을 전해 보세요.'),
  (65, 'confess', true, '여유가 생길 때까지요', '지금은 서로 너무 바빠 고백이 부담스러울 수 있어요. 여유가 생긴 뒤 전하면 마음이 더 잘 닿아요.', '상대의 바쁜 시기가 지나길 기다려 보세요.'),
  (66, 'crush', false, '함께하며 가까워져요', '그 사람과 함께 무언가를 하며 자연스럽게 가까워질 수 있는 흐름이에요. 같이 일하거나 활동하는 시간이 관계를 키워 줘요.', '그 사람과 함께할 수 있는 활동에 참여해 보세요.'),
  (66, 'crush', true, '혼자 애쓰고 있어요', '짝사랑을 이어가느라 혼자만 노력하고 있다고 느낄 수 있어요. 관계는 함께 만드는 것이니 상대의 반응도 함께 살펴보면 좋아요.', '내가 들이는 노력을 조금 줄이고 상대의 반응을 지켜보세요.'),
  (66, 'their_heart', false, '함께하는 게 좋아요', '그 사람은 당신과 함께 무언가를 하는 시간을 좋아하는 것 같아요. 좋은 팀이 될 수 있다고 느끼고 있을 수 있어요.', '함께 무언가를 해 보자고 제안해 보세요.'),
  (66, 'their_heart', true, '소통이 부족해요', '상대는 당신과 마음이 잘 통하지 않는다고 느끼고 있을 수 있어요. 솔직한 대화가 서로를 이해하는 데 도움이 돼요.', '서로의 생각을 나누는 대화를 해 보세요.'),
  (66, 'some', false, '함께 관계를 만들어 가요', '썸을 두 사람이 함께 만들어 가는 흐름이에요. 서로 노력하는 만큼 관계가 단단해질 수 있어요.', '함께 계획을 세우는 데이트를 해 보세요.'),
  (66, 'some', true, '노력이 한쪽에 치우쳐요', '썸에서 한쪽만 노력하고 있어 관계가 기울어 있을 수 있어요. 서로의 노력을 맞추면 관계가 편안해져요.', '내가 원하는 것을 솔직하게 이야기해 보세요.'),
  (66, 'breakup', false, '함께하는 사람들이 있어요', '이별 뒤 주변 사람들과 함께하는 시간이 큰 힘이 되는 흐름이에요. 함께 무언가를 하며 마음이 회복될 수 있어요.', '친구들과 함께하는 활동에 참여해 보세요.'),
  (66, 'breakup', true, '서로의 노력을 돌아봐요', '지난 관계에서 서로의 노력이 맞지 않았던 부분을 돌아보기 좋은 때예요. 그 깨달음이 다음 관계를 더 건강하게 만들어 줘요.', '다음 연애에서 서로 노력하고 싶은 점을 적어 보세요.'),
  (66, 'confess', false, '관계가 무르익었어요', '함께하는 시간이 쌓여 고백하기 좋은 흐름이에요. 함께 만든 추억이 고백을 더 따뜻하게 해 줄 수 있어요.', '함께한 일을 떠올리며 마음을 전해 보세요.'),
  (66, 'confess', true, '조금 더 쌓아요', '아직 서로를 충분히 알지 못해 고백이 어색할 수 있어요. 함께하는 시간을 조금 더 쌓은 뒤 전하면 좋아요.', '고백 전 함께하는 시간을 늘려 보세요.'),
  (67, 'crush', false, '마음을 꽉 쥐고 있어요', '상처받기 싫어 마음을 꽁꽁 숨기고 있을 수 있어요. 조금만 마음을 열면 그 사람도 다가올 수 있어요.', '그 사람에게 작은 마음 하나를 표현해 보세요.'),
  (67, 'crush', true, '마음을 열기 시작해요', '꽉 닫혀 있던 마음이 조금씩 열리는 흐름이에요. 마음을 표현할수록 관계가 자연스럽게 가까워져요.', '용기를 내서 먼저 다가가 보세요.'),
  (67, 'their_heart', false, '조심스럽게 지키고 있어요', '그 사람은 마음을 쉽게 내주지 않고 조심스럽게 지키는 성향일 수 있어요. 천천히 믿음을 쌓으면 마음을 열 수 있어요.', '꾸준하고 한결같은 모습을 보여 주세요.'),
  (67, 'their_heart', true, '마음을 열고 있어요', '상대가 조금씩 마음을 열며 당신에게 다가오려는 것 같아요. 그 변화를 반갑게 맞아 주면 좋아요.', '상대가 다가올 때 따뜻하게 반응해 주세요.'),
  (67, 'some', false, '안정을 원하는 썸이에요', '썸에서 서로 안정을 원하지만 마음을 쉽게 드러내지 않을 수 있어요. 서로 조금씩 마음을 열면 관계가 진전돼요.', '먼저 솔직한 마음 하나를 나눠 보세요.'),
  (67, 'some', true, '집착을 내려놓아요', '썸에 너무 매달리거나 상대를 붙잡으려 하면 관계가 답답해질 수 있어요. 조금 여유를 주면 오히려 가까워질 수 있어요.', '연락 빈도를 조금 줄이고 여유를 가져 보세요.'),
  (67, 'breakup', false, '붙잡고 있는 게 있어요', '지난 관계의 추억이나 물건을 꽉 붙잡고 있을 수 있어요. 소중한 건 간직하되, 마음이 앞으로 나아갈 공간도 만들어 주면 좋아요.', '추억이 담긴 물건을 정리할 시간을 가져 보세요.'),
  (67, 'breakup', true, '놓아줄 수 있어요', '붙잡고 있던 마음을 내려놓고 자유로워지는 흐름이에요. 빈자리에 새로운 인연과 행복이 들어올 수 있어요.', '내려놓고 싶은 것을 하나 정해 정리해 보세요.'),
  (67, 'confess', false, '마음을 조금 열어요', '거절이 두려워 마음을 꽁꽁 숨기고 있을 수 있어요. 조금씩 마음을 열어 표현하면 고백도 자연스러워져요.', '고백 전 작은 호감 표현부터 시작해 보세요.'),
  (67, 'confess', true, '마음을 열 준비가 됐어요', '닫혀 있던 마음이 열리며 고백할 용기가 생기는 흐름이에요. 열린 마음으로 진심을 전해 보면 좋아요.', '편안한 마음으로 진심을 전해 보세요.'),
  (68, 'crush', false, '외로움이 느껴져요', '짝사랑 때문에 외롭고 소외된 기분이 들 수 있어요. 혼자 견디기보다 주변의 따뜻한 사람들에게 기대도 괜찮아요.', '가까운 친구와 따뜻한 시간을 보내 보세요.'),
  (68, 'crush', true, '따뜻함이 돌아와요', '짝사랑으로 외로웠던 마음이 조금씩 따뜻해지는 흐름이에요. 그 사람과의 관계도 조금씩 나아질 수 있어요.', '나를 따뜻하게 해 주는 일을 하나 해 보세요.'),
  (68, 'their_heart', false, '힘든 시기를 보내요', '그 사람은 지금 외롭거나 힘든 시기를 보내고 있을 수 있어요. 연애보다 위로와 도움이 필요한 때일 수 있어요.', '상대에게 따뜻한 손길을 내밀어 주세요.'),
  (68, 'their_heart', true, '기댈 곳을 찾고 있어요', '상대는 힘든 시기를 지나며 따뜻하게 기댈 곳을 찾는 것 같아요. 당신이 그 따뜻함이 되어 줄 수 있어요.', '상대가 편하게 기댈 수 있게 곁에 있어 주세요.'),
  (68, 'some', false, '썸이 쓸쓸하게 느껴져요', '썸에서 서로 마음이 잘 닿지 않아 외롭게 느껴질 수 있어요. 솔직하게 마음을 나누면 거리가 좁혀질 수 있어요.', '외로운 마음을 솔직하게 이야기해 보세요.'),
  (68, 'some', true, '다시 따뜻해져요', '쓸쓸했던 썸이 다시 따뜻해지는 흐름이에요. 서로에게 의지하며 관계가 회복될 수 있어요.', '상대에게 따뜻한 말 한마디를 건네 보세요.'),
  (68, 'breakup', false, '혼자가 아니에요', '이별 뒤 외로움과 허전함이 크게 느껴질 수 있어요. 가까이에 당신을 아끼는 사람들이 있다는 걸 기억해 주세요.', '외로울 때 연락할 수 있는 사람에게 연락해 보세요.'),
  (68, 'breakup', true, '회복이 시작돼요', '힘들었던 이별의 시기를 지나 따뜻함을 되찾는 흐름이에요. 마음이 회복되면 새로운 인연도 자연스럽게 찾아와요.', '나를 위한 따뜻한 일상을 하나씩 되찾아 보세요.'),
  (68, 'confess', false, '외로움 때문은 아닌지요', '외로움 때문에 고백하고 싶은 마음이 커졌을 수 있어요. 그 사람이 정말 좋은 건지 내 마음을 먼저 확인해 보면 좋아요.', '외로움과 좋아하는 마음을 구분해 보세요.'),
  (68, 'confess', true, '마음이 따뜻해졌어요', '힘든 시기를 지나 마음이 따뜻해진 지금, 진심을 전하기 좋은 흐름이에요. 따뜻한 마음이 고백에 담길 수 있어요.', '따뜻한 분위기에서 마음을 전해 보세요.'),
  (69, 'crush', false, '마음을 나눌 수 있어요', '그 사람과 마음과 배려를 주고받으며 가까워지는 흐름이에요. 작은 친절이 관계를 따뜻하게 만들어 줘요.', '그 사람에게 작은 도움을 건네 보세요.'),
  (69, 'crush', true, '주기만 하고 있어요', '그 사람에게 마음을 일방적으로 주기만 하고 있을 수 있어요. 관계는 주고받을 때 건강해지니 나도 받을 자격이 있다는 걸 기억해 주세요.', '내가 지치지 않는 선을 정해 보세요.'),
  (69, 'their_heart', false, '당신에게 고마워해요', '그 사람은 당신이 베푼 배려에 고마움을 느끼며 보답하고 싶어 하는 것 같아요. 서로 주고받는 관계를 원하고 있을 수 있어요.', '상대의 보답을 기쁘게 받아 주세요.'),
  (69, 'their_heart', true, '관계가 기울어 있어요', '상대는 관계에서 한쪽만 애쓰고 있다고 느끼거나 부담을 느끼고 있을 수 있어요. 균형을 맞추는 대화가 필요해요.', '서로의 마음을 솔직하게 나눠 보세요.'),
  (69, 'some', false, '균형 잡힌 썸이에요', '썸에서 마음과 관심이 균형 있게 오가는 흐름이에요. 서로 배려하는 관계가 연애로 자연스럽게 이어질 수 있어요.', '서로에게 고마운 점을 이야기해 보세요.'),
  (69, 'some', true, '한쪽만 애쓰고 있어요', '썸에서 한쪽만 마음을 쏟고 있어 관계가 기울어 있을 수 있어요. 기울어진 관계는 지치기 쉬우니 솔직하게 이야기해 보면 좋아요.', '내가 원하는 관계의 모습을 말해 보세요.'),
  (69, 'breakup', false, '받은 마음에 감사해요', '지난 관계에서 주고받은 마음을 감사하게 정리하는 흐름이에요. 좋았던 것을 인정하면 미련 없이 마음을 정리할 수 있어요.', '지난 관계에서 고마웠던 점을 떠올려 보세요.'),
  (69, 'breakup', true, '기울어진 관계였어요', '지난 관계가 한쪽으로 기울어 있었다는 걸 깨닫게 될 수 있어요. 다음 관계에서는 서로 주고받는 균형을 찾으면 좋아요.', '다음 연애에서 원하는 균형을 적어 보세요.'),
  (69, 'confess', false, '마음을 나누기 좋아요', '서로 배려하는 관계 속에서 마음을 전하기 좋은 흐름이에요. 진심을 나누면 상대도 따뜻하게 받아줄 수 있어요.', '상대에게 고마운 마음과 함께 진심을 전해 보세요.'),
  (69, 'confess', true, '대가를 바라지 않아요', '그동안 해 준 것에 대한 보답으로 고백을 받아 주길 바라고 있을 수 있어요. 고백은 대가가 아니라 마음을 전하는 일이에요.', '결과보다 마음을 전하는 데 집중해 보세요.'),
  (70, 'crush', false, '천천히 자라고 있어요', '짝사랑이 눈에 띄지 않아도 천천히 자라나고 있는 흐름이에요. 꾸준히 마음을 쏟으면 결실을 볼 수 있어요.', '조급해하지 말고 꾸준히 다가가 보세요.'),
  (70, 'crush', true, '방향을 점검해요', '노력한 만큼 짝사랑에 진전이 없어 답답할 수 있어요. 다가가는 방법을 조금 바꿔 보면 좋은 변화가 생길 수 있어요.', '지금까지와 다른 방법으로 다가가 보세요.'),
  (70, 'their_heart', false, '천천히 마음을 키워요', '그 사람은 당신에 대한 마음을 서두르지 않고 천천히 키워 가는 것 같아요. 시간이 지날수록 마음이 깊어질 수 있어요.', '상대의 속도를 존중하며 기다려 주세요.'),
  (70, 'their_heart', true, '확신을 기다리고 있어요', '상대는 관계에 대해 아직 확신이 서지 않아 지켜보고 있을 수 있어요. 꾸준한 모습이 확신을 줄 수 있어요.', '한결같은 모습으로 믿음을 주세요.'),
  (70, 'some', false, '꾸준히 자라는 썸이에요', '썸이 천천히, 하지만 꾸준히 깊어지는 흐름이에요. 서두르지 않아도 관계가 자연스럽게 무르익을 수 있어요.', '꾸준한 연락으로 관계를 이어가 보세요.'),
  (70, 'some', true, '진전이 더뎌요', '썸에 들인 노력에 비해 진전이 더뎌 지칠 수 있어요. 이 관계가 나에게 맞는지 한 번 점검해 보면 좋아요.', '이 썸에서 내가 원하는 것을 다시 생각해 보세요.'),
  (70, 'breakup', false, '회복을 기다려요', '이별의 아픔이 천천히 회복되는 흐름이에요. 조급해하지 않고 나를 돌보다 보면 마음에도 새로운 싹이 틀 수 있어요.', '회복을 위한 작은 습관을 꾸준히 이어가 보세요.'),
  (70, 'breakup', true, '들인 노력을 돌아봐요', '지난 관계에 들인 노력이 아깝게 느껴질 수 있어요. 그 노력은 사라지지 않고 나를 성장시킨 경험으로 남아요.', '지난 관계에서 성장한 점을 적어 보세요.'),
  (70, 'confess', false, '조금 더 기다려요', '관계가 조금 더 무르익을 때까지 기다리면 좋은 흐름이에요. 충분히 자란 마음은 더 좋은 결실로 이어질 수 있어요.', '고백할 때가 무르익을 때까지 꾸준히 다가가 보세요.'),
  (70, 'confess', true, '조급함을 내려놓아요', '노력한 만큼 빨리 결과를 보고 싶어 조급할 수 있어요. 조급함을 내려놓으면 더 좋은 타이밍이 보여요.', '고백을 서두르기보다 지금 관계를 즐겨 보세요.'),
  (71, 'crush', false, '정성이 통해요', '그 사람을 향한 꾸준하고 정성스러운 마음이 전해지는 흐름이에요. 작은 노력이 쌓여 관계가 가까워질 수 있어요.', '그 사람을 위한 작은 정성을 꾸준히 보여 주세요.'),
  (71, 'crush', true, '완벽하지 않아도 돼요', '그 사람에게 완벽하게 보이려고 너무 애쓰고 있을 수 있어요. 있는 그대로의 모습이 더 편안하게 다가갈 수 있어요.', '완벽함보다 편안함을 보여 주세요.'),
  (71, 'their_heart', false, '성실하게 생각해요', '그 사람은 당신과의 관계를 성실하고 진지하게 생각하는 것 같아요. 꾸준한 노력으로 마음을 보여 주고 있을 수 있어요.', '상대의 꾸준한 노력을 알아봐 주세요.'),
  (71, 'their_heart', true, '다른 일에 집중해요', '상대는 지금 일이나 공부에 집중하느라 관계에 신경 쓸 여유가 없을 수 있어요. 마음이 없는 건 아닐 수 있어요.', '상대의 노력을 응원해 주세요.'),
  (71, 'some', false, '차곡차곡 쌓이는 썸이에요', '썸이 꾸준하고 성실하게 쌓여 가는 흐름이에요. 서로 노력하는 만큼 관계가 단단해질 수 있어요.', '작은 약속을 꾸준히 지켜 보세요.'),
  (71, 'some', true, '썸이 지루해졌어요', '같은 패턴이 반복되며 썸이 지루하게 느껴질 수 있어요. 새로운 시도로 관계에 활력을 불어넣으면 좋아요.', '평소와 다른 데이트를 시도해 보세요.'),
  (71, 'breakup', false, '나를 가꾸는 시간이에요', '이별 뒤 나를 성장시키는 일에 정성을 쏟기 좋은 흐름이에요. 꾸준히 나를 가꾸다 보면 마음도 단단해져요.', '배우고 싶었던 것을 하나 시작해 보세요.'),
  (71, 'breakup', true, '너무 몰아붙이지 않아요', '이별을 잊으려 일이나 공부에만 몰두하며 지쳐 있을 수 있어요. 쉼과 즐거움도 함께 챙겨야 마음이 회복돼요.', '오늘은 나를 위한 즐거운 일을 하나 해 보세요.'),
  (71, 'confess', false, '정성스럽게 준비해요', '고백을 정성스럽게 준비하기 좋은 흐름이에요. 진심을 담아 준비한 고백이 상대에게 잘 전해질 수 있어요.', '고백할 말을 정성껏 준비해 보세요.'),
  (71, 'confess', true, '완벽함보다 진심이에요', '완벽한 고백을 준비하느라 오히려 망설이고 있을 수 있어요. 조금 서툴러도 진심이면 충분해요.', '완벽한 준비보다 진심을 전하는 데 집중해 보세요.'),
  (72, 'crush', false, '스스로 빛나는 때예요', '혼자서도 충분히 행복하고 빛나는 당신의 모습이 그 사람에게 매력적으로 다가갈 수 있는 흐름이에요. 여유로운 모습이 큰 매력이 돼요.', '나를 위한 여유로운 시간을 즐겨 보세요.'),
  (72, 'crush', true, '나를 먼저 채워요', '그 사람에게 너무 기대며 내 행복을 맡기고 있을 수 있어요. 나 스스로 행복할 때 관계도 더 건강해져요.', '나를 행복하게 하는 일을 하나 해 보세요.'),
  (72, 'their_heart', false, '당신의 여유에 끌려요', '그 사람은 당신의 여유롭고 자신감 있는 모습에 끌리는 것 같아요. 혼자서도 빛나는 모습을 멋지다고 느낄 수 있어요.', '나다운 여유를 그대로 보여 주세요.'),
  (72, 'their_heart', true, '혼자가 편할 수 있어요', '상대는 지금 혼자만의 생활에 만족하며 연애에 대한 마음이 크지 않을 수 있어요. 부담 없이 천천히 다가가면 좋아요.', '부담 주지 않고 편안하게 대해 주세요.'),
  (72, 'some', false, '여유로운 썸이에요', '서로의 생활을 존중하며 여유롭게 이어지는 썸이에요. 각자 행복한 두 사람이 만나 관계가 더 건강해질 수 있어요.', '각자의 시간을 존중하며 여유롭게 만나 보세요.'),
  (72, 'some', true, '기대가 커졌어요', '썸에 너무 기대며 내 일상의 균형이 흔들릴 수 있어요. 나의 생활도 함께 챙기면 관계가 더 편안해져요.', '썸 외에 나만의 즐거움도 챙겨 보세요.'),
  (72, 'breakup', false, '혼자서도 충분해요', '이별 뒤 혼자서도 충분히 행복할 수 있다는 걸 알게 되는 흐름이에요. 스스로 빛나는 당신에게 좋은 인연이 찾아올 수 있어요.', '나를 위한 작은 사치를 부려 보세요.'),
  (72, 'breakup', true, '외로움을 다독여요', '혼자가 된 것이 외롭고 허전하게 느껴질 수 있어요. 나의 가치는 관계와 상관없이 그대로라는 걸 기억해 주세요.', '나를 아끼는 사람들과 시간을 보내 보세요.'),
  (72, 'confess', false, '여유롭게 전해요', '스스로에 대한 자신감과 여유가 있는 지금, 고백하기 좋은 흐름이에요. 여유로운 고백이 상대에게 편안하게 전해질 수 있어요.', '부담 없이 여유롭게 마음을 전해 보세요.'),
  (72, 'confess', true, '나를 먼저 믿어요', '외로움 때문에 고백을 서두르고 있을 수 있어요. 스스로를 먼저 믿고 채운 뒤 전하면 더 좋은 고백이 될 수 있어요.', '고백 전 나의 좋은 점을 떠올려 보세요.'),
  (73, 'crush', false, '오래 함께할 인연일 수 있어요', '그 사람과 오래도록 안정적인 관계를 이어갈 수 있는 기운이 보여요. 서두르지 않고 천천히 쌓아 가면 좋아요.', '그 사람의 가치관을 알 수 있는 대화를 나눠 보세요.'),
  (73, 'crush', true, '현실을 함께 봐요', '그 사람과 나 사이에 현실적인 차이가 있을 수 있어요. 그 차이가 극복 가능한지 차분히 살펴보면 좋아요.', '그 사람이 중요하게 여기는 것을 알아보세요.'),
  (73, 'their_heart', false, '미래를 생각하고 있어요', '그 사람은 당신과의 관계를 진지하게, 오래 함께할 사람으로 생각하는 것 같아요. 안정적인 관계를 원하고 있을 수 있어요.', '상대와 함께하는 미래 이야기를 나눠 보세요.'),
  (73, 'their_heart', true, '현실적인 고민이 있어요', '상대는 관계를 이어가는 데 현실적인 고민이나 걱정이 있을 수 있어요. 함께 이야기하면 해결책을 찾을 수 있어요.', '상대의 고민을 함께 들어 주세요.'),
  (73, 'some', false, '안정적인 연애로 이어져요', '썸이 오래가는 안정적인 연애로 이어질 수 있는 흐름이에요. 서로의 가족이나 친구들과도 잘 어울릴 수 있어요.', '서로의 소중한 사람들에게 상대를 소개해 보세요.'),
  (73, 'some', true, '생각의 차이가 있어요', '썸에서 서로의 가치관이나 생활 방식에 차이가 느껴질 수 있어요. 차이를 인정하고 맞춰 가는 대화가 필요해요.', '서로 중요하게 생각하는 것을 이야기해 보세요.'),
  (73, 'breakup', false, '오래가는 행복을 그려요', '지난 관계를 정리하며 내가 원하는 오래가는 행복을 그려 볼 수 있는 때예요. 그 그림이 새로운 인연을 만나는 기준이 돼요.', '내가 꿈꾸는 미래의 모습을 적어 보세요.'),
  (73, 'breakup', true, '현실의 차이를 인정해요', '현실적인 차이 때문에 이별했다면 그 이유를 받아들이기 힘들 수 있어요. 서로 다른 길이 각자에게 더 맞을 수 있다는 걸 생각해 보면 좋아요.', '서로의 다른 점을 차분히 돌아보세요.'),
  (73, 'confess', false, '진지하게 전해요', '오래 함께하고 싶은 마음을 진지하게 전하기 좋은 흐름이에요. 미래를 담은 고백이 상대에게 믿음을 줄 수 있어요.', '함께하고 싶은 미래를 담아 마음을 전해 보세요.'),
  (73, 'confess', true, '생각을 먼저 맞춰요', '고백 전에 서로 원하는 관계나 미래가 같은지 확인해 보면 좋아요. 생각이 맞을 때 고백이 더 잘 닿아요.', '고백 전 상대가 원하는 관계를 넌지시 물어보세요.'),
  (74, 'crush', false, '차근차근 알아가요', '그 사람을 성실하게 알아가며 천천히 가까워지는 흐름이에요. 진지한 관심이 좋은 관계로 이어질 수 있어요.', '그 사람에 대해 새로운 것을 하나 배워 보세요.'),
  (74, 'crush', true, '행동을 미루고 있어요', '다가가고 싶은 마음은 있지만 행동을 계속 미루고 있을 수 있어요. 작은 한 걸음부터 시작하면 좋아요.', '오늘 그 사람에게 짧은 인사를 건네 보세요.'),
  (74, 'their_heart', false, '진지하게 관심을 가져요', '그 사람은 당신에게 성실하고 진지한 관심을 갖고 있는 것 같아요. 천천히 알아가고 싶어 할 수 있어요.', '상대가 알아갈 수 있도록 나에 대해 조금씩 이야기해 주세요.'),
  (74, 'their_heart', true, '관계에 집중하지 못해요', '상대는 다른 일에 마음을 빼앗겨 관계에 집중하지 못하고 있을 수 있어요. 부담을 주기보다 기다려 주면 좋아요.', '상대가 여유로워질 때까지 기다려 주세요.'),
  (74, 'some', false, '성실하게 이어지는 썸이에요', '썸이 서두르지 않고 성실하게 이어지는 흐름이에요. 서로 진지하게 알아가며 관계가 단단해질 수 있어요.', '함께 배울 수 있는 일을 찾아보세요.'),
  (74, 'some', true, '진전 없이 미뤄져요', '썸을 진전시키는 일을 서로 미루고 있을 수 있어요. 누군가 먼저 작은 행동을 하면 흐름이 바뀌어요.', '다음 약속을 먼저 구체적으로 잡아 보세요.'),
  (74, 'breakup', false, '새로운 배움이 와요', '이별 뒤 새로운 것을 배우며 나를 성장시키기 좋은 흐름이에요. 배움의 시간이 마음을 회복시키고 새로운 인연으로 이어질 수 있어요.', '새로운 수업이나 강의를 들어 보세요.'),
  (74, 'breakup', true, '작은 것부터 시작해요', '이별 후 아무것도 하기 싫어 해야 할 일을 미루고 있을 수 있어요. 아주 작은 일부터 하나씩 해내면 다시 힘이 나요.', '오늘 할 수 있는 가장 작은 일 하나를 해 보세요.'),
  (74, 'confess', false, '천천히 준비해요', '고백을 서두르지 않고 성실하게 준비하기 좋은 흐름이에요. 충분히 알아간 뒤 전하는 고백은 더 진심으로 닿아요.', '상대를 더 알아가며 고백을 준비해 보세요.'),
  (74, 'confess', true, '미루지 않아요', '고백을 계속 미루다 보면 기회를 놓칠 수 있어요. 완벽한 때를 기다리기보다 작은 표현부터 시작하면 좋아요.', '오늘은 작은 호감 표현 하나만 해 보세요.'),
  (75, 'crush', false, '꾸준함이 통해요', '화려한 표현보다 꾸준하고 믿음직한 모습이 그 사람에게 잘 통하는 흐름이에요. 천천히 다가가도 마음은 분명히 전해질 수 있어요.', '약속을 잘 지키며 신뢰를 쌓아 보세요.'),
  (75, 'crush', true, '조금 더 표현해요', '너무 조심스럽고 느리게 다가가서 그 사람이 마음을 알아차리지 못할 수 있어요. 조금 더 적극적으로 표현해도 괜찮아요.', '평소보다 한 번 더 먼저 연락해 보세요.'),
  (75, 'their_heart', false, '묵묵히 마음을 쌓아요', '그 사람은 말보다 행동으로 꾸준히 마음을 보여 주는 성향인 것 같아요. 표현은 적어도 마음은 진지할 수 있어요.', '상대의 꾸준한 행동에 담긴 마음을 알아봐 주세요.'),
  (75, 'their_heart', true, '진전을 망설이고 있어요', '상대는 관계를 진전시키는 데 신중하다 보니 속도가 느릴 수 있어요. 재촉하기보다 편하게 다가갈 수 있게 해 주면 좋아요.', '상대가 다가오기 쉬운 분위기를 만들어 주세요.'),
  (75, 'some', false, '믿음직한 썸이에요', '썸이 천천히, 하지만 안정적으로 이어지는 흐름이에요. 꾸준한 관계가 믿음을 쌓아 오래가는 연애로 이어질 수 있어요.', '꾸준하게 연락하며 관계를 이어가 보세요.'),
  (75, 'some', true, '썸이 너무 느려요', '썸이 너무 느리게 진행되어 답답하게 느껴질 수 있어요. 새로운 계기를 만들면 관계가 한 걸음 나아갈 수 있어요.', '새로운 장소에서 데이트를 해 보세요.'),
  (75, 'breakup', false, '천천히 회복해요', '이별의 아픔에서 서두르지 않고 꾸준히 회복하는 흐름이에요. 매일 조금씩 나를 돌보다 보면 마음이 단단해져요.', '매일 할 수 있는 작은 회복 습관을 만들어 보세요.'),
  (75, 'breakup', true, '같은 자리에 머물러요', '이별 후 일상이 너무 단조롭게 반복되며 마음이 정체되어 있을 수 있어요. 작은 변화를 더하면 기분이 새로워져요.', '평소와 다른 새로운 일을 하나 해 보세요.'),
  (75, 'confess', false, '신중하게 준비해요', '서두르지 않고 신중하게 고백을 준비하기 좋은 흐름이에요. 믿음직한 고백이 상대에게 안정감을 줄 수 있어요.', '충분히 준비한 뒤 진지하게 마음을 전해 보세요.'),
  (75, 'confess', true, '너무 오래 미루지 않아요', '신중함이 지나쳐 고백을 계속 미루고 있을 수 있어요. 적당한 때가 왔다면 한 걸음 내디뎌도 괜찮아요.', '고백할 날을 정하고 미루지 않기로 해 보세요.'),
  (76, 'crush', false, '따뜻한 배려가 통해요', '당신의 따뜻하고 현실적인 배려가 그 사람에게 안정감을 주는 흐름이에요. 챙겨 주는 마음이 큰 매력이 될 수 있어요.', '그 사람에게 필요한 작은 것을 챙겨 주세요.'),
  (76, 'crush', true, '나도 챙겨요', '그 사람을 챙기느라 정작 나를 돌보지 못하고 있을 수 있어요. 나를 아끼는 마음도 함께 챙기면 관계가 더 건강해져요.', '오늘은 나를 위한 시간을 꼭 가져 보세요.'),
  (76, 'their_heart', false, '당신에게 안정감을 느껴요', '그 사람은 당신에게서 따뜻하고 편안한 안정감을 느끼는 것 같아요. 함께 있으면 마음이 놓인다고 생각할 수 있어요.', '상대에게 편안한 시간을 선물해 주세요.'),
  (76, 'their_heart', true, '걱정이 많아요', '상대는 현실적인 걱정이 많아 관계에 마음을 쏟기 어려울 수 있어요. 함께 걱정을 나누면 마음이 가벼워질 수 있어요.', '상대의 걱정을 차분히 들어 주세요.'),
  (76, 'some', false, '서로 챙겨 주는 썸이에요', '썸에서 서로를 따뜻하게 챙겨 주며 안정감이 쌓이는 흐름이에요. 이런 관계는 오래가는 연애로 이어지기 좋아요.', '상대를 위해 작은 정성을 보여 주세요.'),
  (76, 'some', true, '한쪽만 챙기고 있어요', '썸에서 한쪽만 상대를 챙기며 지쳐 갈 수 있어요. 서로 주고받는 배려가 관계를 더 건강하게 만들어요.', '나도 챙김받고 싶다는 마음을 표현해 보세요.'),
  (76, 'breakup', false, '나를 따뜻하게 돌봐요', '이별 뒤 나를 따뜻하게 돌보며 회복하기 좋은 흐름이에요. 나를 아끼는 생활이 마음을 안정시키고 새 인연을 맞을 준비가 돼요.', '건강한 음식을 챙겨 먹으며 나를 돌봐 주세요.'),
  (76, 'breakup', true, '걱정을 내려놓아요', '이별 후 앞으로에 대한 걱정이 많아질 수 있어요. 지금은 걱정보다 오늘 하루를 잘 보내는 데 집중하면 좋아요.', '오늘 하루 잘한 일을 하나 적어 보세요.'),
  (76, 'confess', false, '따뜻하게 전해요', '따뜻하고 편안한 분위기 속에서 마음을 전하기 좋은 흐름이에요. 당신의 다정함이 고백에 그대로 담길 수 있어요.', '편안한 장소에서 따뜻하게 마음을 전해 보세요.'),
  (76, 'confess', true, '나를 먼저 채워요', '상대를 챙기느라 내 마음이 지쳐 있다면 고백 전에 나를 먼저 채워 주면 좋아요. 마음이 넉넉할 때 고백도 더 편안해져요.', '고백 전 나를 위한 휴식을 가져 보세요.'),
  (77, 'crush', false, '든든한 모습이 매력이에요', '당신의 안정되고 믿음직한 모습이 그 사람에게 든든하게 느껴지는 흐름이에요. 책임감 있는 태도가 신뢰를 줄 수 있어요.', '그 사람이 도움이 필요할 때 든든하게 곁에 있어 주세요.'),
  (77, 'crush', true, '마음도 함께 보여요', '현실적인 조건이나 겉모습에만 신경 쓰고 있을 수 있어요. 진심과 따뜻한 마음을 함께 보여 주면 더 가까워질 수 있어요.', '그 사람에게 마음을 담은 말을 건네 보세요.'),
  (77, 'their_heart', false, '든든하게 지켜 주고 싶어 해요', '그 사람은 당신을 든든하게 지켜 주고 싶은 책임감 있는 마음을 갖고 있는 것 같아요. 안정적인 관계를 원하고 있을 수 있어요.', '상대의 든든한 마음을 고맙게 받아 주세요.'),
  (77, 'their_heart', true, '현실적으로 따지고 있어요', '상대는 관계를 현실적인 조건으로 따지며 고민하고 있을 수 있어요. 마음의 교감도 중요하다는 걸 함께 나누면 좋아요.', '함께할 때 행복한 순간을 떠올리게 해 주세요.'),
  (77, 'some', false, '안정적인 관계로 가요', '썸이 안정적이고 든든한 연애로 이어질 수 있는 흐름이에요. 서로에게 믿음을 주는 관계가 오래갈 수 있어요.', '믿음직한 모습으로 관계를 이끌어 보세요.'),
  (77, 'some', true, '유연함이 필요해요', '썸에서 서로 자기 방식을 고집하며 부딪힐 수 있어요. 조금 유연해지면 관계가 편안해질 수 있어요.', '상대의 의견을 한 번 더 들어 주세요.'),
  (77, 'breakup', false, '단단하게 다시 서요', '이별 뒤 내 삶을 든든하게 다시 세우는 흐름이에요. 안정된 일상과 자신감이 새로운 인연을 맞는 힘이 돼요.', '앞으로의 생활 계획을 차근차근 세워 보세요.'),
  (77, 'breakup', true, '조건보다 마음이에요', '현실적인 이유로 관계를 정리했다면 아쉬움이 남을 수 있어요. 다음엔 조건과 마음 모두를 함께 바라보는 연애를 할 수 있어요.', '다음 연애에서 소중히 하고 싶은 마음을 적어 보세요.'),
  (77, 'confess', false, '믿음직하게 전해요', '안정되고 진지한 마음을 전하기 좋은 흐름이에요. 책임감 있는 고백이 상대에게 믿음과 안정감을 줄 수 있어요.', '진지하고 차분하게 마음을 전해 보세요.'),
  (77, 'confess', true, '마음을 먼저 보여요', '고백을 조건이나 계획으로만 준비하면 마음이 잘 전해지지 않을 수 있어요. 따뜻한 진심을 먼저 보여 주면 좋아요.', '고백할 때 내 감정을 솔직하게 표현해 보세요.')
